// Multi-word scientific terms that must be preserved as a phrase. Users type
// them variably . "co occurrence", "co-occurrence", "cooccurrence" . but all
// should become the canonical hyphenated form for search.
const SCIENTIFIC_COMPOUNDS = [
  [/\bco[\s-]?occurr?ence[s]?\b/gi, "co-occurrence"],
  [/\bmachine[\s-]?learning\b/gi, "machine-learning"],
  [/\bdeep[\s-]?learning\b/gi, "deep-learning"],
  [/\bgene[\s-]?expression\b/gi, "gene-expression"],
  [/\bwhole[\s-]?genome\b/gi, "whole-genome"],
  [/\bhigh[\s-]?throughput\b/gi, "high-throughput"],
  [/\bnext[\s-]?generation\b/gi, "next-generation"],
  [/\bcell[\s-]?free\b/gi, "cell-free"],
  [/\bsingle[\s-]?cell\b/gi, "single-cell"],
  [/\bloss[\s-]?of[\s-]?function\b/gi, "loss-of-function"],
  [/\bgain[\s-]?of[\s-]?function\b/gi, "gain-of-function"],
  [/\bin[\s-]?vivo\b/gi, "in-vivo"],
  [/\bin[\s-]?vitro\b/gi, "in-vitro"],
  [/\bin[\s-]?silico\b/gi, "in-silico"],
  [/\bdouble[\s-]?stranded?\b/gi, "double-stranded"],
  [/\bsingle[\s-]?stranded?\b/gi, "single-stranded"],
  [/\blong[\s-]?non[\s-]?coding\b/gi, "long-non-coding"],
  [/\banti[\s-]?microbial\b/gi, "antimicrobial"],
  [/\banti[\s-]?biotic\b/gi, "antibiotic"],
  [/\banti[\s-]?fungal\b/gi, "antifungal"],
  [/\banti[\s-]?viral\b/gi, "antiviral"],
  [/\banti[\s-]?oxidant\b/gi, "antioxidant"],
  [/\banti[\s-]?inflammatory\b/gi, "anti-inflammatory"],
  [/\bmulti[\s-]?drug\b/gi, "multidrug"],
  [/\bmulti[\s-]?omics\b/gi, "multi-omics"],
  [/\bcrispr[\s-]?cas9?\b/gi, "CRISPR-Cas9"],
  [/\bopen[\s-]?access\b/gi, "open-access"],
  [/\blong[\s-]?term\b/gi, "long-term"],
  [/\bshort[\s-]?term\b/gi, "short-term"],
  [/\bdose[\s-]?response\b/gi, "dose-response"],
  [/\bex[\s-]?vivo\b/gi, "ex-vivo"],
  [/\bde[\s-]?novo\b/gi, "de-novo"],
  [/\bgut[\s-]?brain\b/gi, "gut-brain"],
  [/\bblood[\s-]?brain[\s-]?barrier\b/gi, "blood-brain-barrier"],
  [/\bhost[\s-]?pathogen\b/gi, "host-pathogen"],
  [/\bstructure[\s-]?activity\b/gi, "structure-activity"],
  [/\bgenome[\s-]?editing\b/gi, "genome-editing"],
  [/\bstem[\s-]?cell\b/gi, "stem-cell"],
];

// Spelling correction only (no paraphrasing, no compound joining): the
// canonical-spelling form of a query. 2026-10-09: constraint extraction
// (analyzeQuery) must see the SAME corrected terms the retrieval pipeline
// searches for. Before this, retrieval searched the corrected query while
// the constraint check ran on the raw one, so a typo ("plauge") became a
// load-bearing constraint no paper could satisfy and every retrieved paper
// was capped below the relevance floor.
function correctQuerySpelling(raw) {
  let q = " " + (raw || "").toLowerCase() + " ";
  // Binomial typo correction before anything else . fixes voice-dictation
  // mangling like "Hermetia illucens" -> "Hermia illusions" so the organism
  // detector below (which needs the correct spelling) actually recognizes
  // the species instead of silently falling through to a generic keyword
  // search across every field that happens to mention "microbiome".
  q = " " + correctBinomialTypos(q.trim()) + " ";
  // Spelling correction FIRST . otherwise a misspelled half of a compound
  // ("co occurance") won't match the compound pattern (which expects the
  // correct spelling).
  const words = q.split(/(\s+)/);
  for (let i = 0; i < words.length; i++) {
    const w = words[i].replace(/[^a-z-]/g, "");
    if (w && SPELLING_CORRECTIONS[w]) {
      words[i] = words[i].replace(w, SPELLING_CORRECTIONS[w]);
    }
  }
  return words.join("");
}

// Preprocess a raw query BEFORE term extraction. Fixes typos, joins scientific
// compounds, so downstream code sees the canonical form.
function preprocessQuery(raw) {
  let q = correctQuerySpelling(raw);
  // Then join scientific compounds so "co occurrence" becomes "co-occurrence".
  for (const [re, canonical] of SCIENTIFIC_COMPOUNDS) {
    q = q.replace(re, canonical);
  }
  // Scientific paraphrase: rewrite natural-language concepts into proper
  // search terminology. "turning air into ethanol" should search for
  // "CO2 ethanol conversion", not "air ethanol".
  //
  // Contested rewrites dropped as a class (2026-10-23, logic
  // audit L1-12): a substitution that presupposes the answer to
  // the question being asked, or equates the asked concept with
  // a narrower one, is not a paraphrase. The cure entries are
  // gone entirely (a cure is not any treatment or therapy, and
  // a question asking whether one exists must not be searched
  // as if it does), "global warming" no longer acquires
  // "anthropogenic" (the cause a question may be asking
  // about), the safety rewrite no longer equates safety with
  // toxicity, and "how is X made" no longer presupposes a
  // biological origin. What stands are terminology equivalents,
  // and the canonical representation (canonicalQueryForms
  // below) keeps the original text beside them: retrieval,
  // analysis, and gating all derive from that one
  // representation, never from three different texts.
  const PARAPHRASES = [
    [/turning\s+air\s+into/gi, "CO2 conversion to"],
    [/air\s+(?:to|into)\s+(ethanol|fuel|methanol|plastic)/gi, "CO2 conversion to $1"],
    [/(ethanol|fuel|methanol)\s+from\s+air/gi, "$1 from CO2 atmospheric carbon capture"],
    [/global\s+warming/gi, "climate change"],
    [/how\s+(?:does|do)\s+(.+?)\s+work/gi, "$1 mechanism"],
    [/what\s+causes?\s+(.+?)(?:\?|$)/gi, "$1 etiology mechanism cause"],
    // Plant biology
    [/not\s+need\s+(?:it|photosynthesis|sunlight|light)/gi, "non-photosynthetic heterotrophic mycoheterotrophic parasitic"],
    [/without\s+(?:photosynthesis|sunlight|light)/gi, "non-photosynthetic heterotrophic"],
    // Ecology / evolution
    [/(?:go|went)\s+extinct/gi, "extinction cause"],
    [/why\s+(?:do|did)\s+dinosaurs?\s+(?:go|die)/gi, "dinosaur extinction Cretaceous-Paleogene"],
    // Medicine / disease
    [/side\s+effects?\s+of\s+(.+?)(?:\?|$)/gi, "$1 adverse effects safety"],
    [/is\s+(.+?)\s+safe/gi, "$1 safety adverse effects"],
    // Nutrition / biochemistry
    [/(?:good|bad)\s+(?:for\s+)?(?:your?\s+)?health/gi, "health effects benefits risks"],
    [/what\s+(?:does|do)\s+(.+?)\s+do\s+(?:to|in|for)\s+(?:the\s+)?body/gi, "$1 physiological effects mechanism of action"],
    [/how\s+is\s+(.+?)\s+made/gi, "$1 production synthesis"],
    // Genetics
    [/gene\s+for\s+(.+?)(?:\?|$)/gi, "$1 genetic basis gene locus"],
    [/is\s+(.+?)\s+(?:hereditary|genetic|inherited)/gi, "$1 heritability genetic predisposition inheritance"],
    // Neuroscience
    [/how\s+(?:does|do)\s+(?:the\s+)?brain\s+(.+?)(?:\?|$)/gi, "brain $1 neural mechanism neuroscience"],
    [/what\s+happens?\s+(?:to|in)\s+(?:the\s+)?brain\s+(?:when|during)\s+(.+?)(?:\?|$)/gi, "brain $1 neural activity neurophysiology"],
    // Microbiology
    [/(?:good|beneficial)\s+bacteria/gi, "probiotic commensal microbiome beneficial microbiota"],
    [/(?:bad|harmful)\s+bacteria/gi, "pathogenic bacteria virulence infection"],
    [/superbugs?/gi, "antimicrobial resistance multidrug-resistant bacteria"],
    // Environment
    [/(?:save|saving)\s+(?:the\s+)?(?:planet|earth|environment)/gi, "environmental conservation sustainability"],
    [/clean\s+energy/gi, "renewable energy solar wind sustainable"],
    [/greenhouse\s+gas(?:es)?/gi, "greenhouse gas emissions CO2 methane climate"],
  ];
  for (const [re, repl] of PARAPHRASES) {
    q = q.replace(re, repl);
  }
  return q.trim();
}

// The one canonical query representation (2026-10-23, L1-12).
// Before this, retrieval searched the paraphrase rewritten
// text, analysis ran on the spelling corrected text only, and
// the handler's intent and gate consumers ran on the raw text:
// three different texts of one question, so a failure could
// not be attributed to any one of them. Every form below is
// computed here, once, from the same preprocessed text, and
// the consumers take their form from this object: retrieval
// the cleaned and surface forms, analysis the preprocessed
// form (analyzeQuery calls this), gating the question as
// asked beside them. The paraphrase forms are declared on the
// object (paraphrased) rather than silently replacing the
// original, which stays on the object as original.
export function canonicalQueryForms(raw) {
  const original = String(raw || "").trim();
  const paraphrased = preprocessQuery(original);
  return {
    original,
    paraphrased,
    cleaned: cleanQuery(paraphrased),
    surface: cleanSurfaceQuery(paraphrased),
  };
}

const GENERIC_SCIENCE_WORDS = new Set([
  "types", "type", "kinds", "kind", "sort", "sorts", "form", "forms",
  "compound", "compounds", "substance", "substances", "material", "materials",
  "capitalize", "utilize", "utilise", "leverage", "involve", "involves",
  "process", "processes", "method", "methods", "approach", "approaches",
  "effect", "effects", "impact", "impacts", "influence", "role", "roles",
  "function", "functions", "mechanism", "mechanisms", "system", "systems",
  "factor", "factors", "level", "levels", "amount", "amounts", "rate", "rates",
  "result", "results", "outcome", "outcomes", "finding", "findings",
  "study", "studies", "research", "paper", "papers", "article", "articles",
  "analysis", "data", "evidence", "review", "reviews", "report", "reports",
  "different", "various", "several", "many", "much", "high", "low", "large",
  "small", "new", "novel", "recent", "current", "important", "significant",
  "possible", "potential", "specific", "general", "common", "main", "major",
  "help", "helps", "make", "makes", "made", "get", "gets", "give", "gives",
  "produce", "produces", "produced", "production",
  "related", "associated", "based", "including", "such", "well", "known",
  "information", "info", "detail", "details", "aspect", "aspects",
  "question", "answer", "example", "examples", "case", "cases",
  "air", "water", "light", "heat", "cold", "food", "plant", "plants",
  "time", "life", "cell", "cells", "model", "models", "group", "groups",
]);

// Concept equivalence groups. If a query term is in a group, a paper matching
// ANY member of that group satisfies the term. This is what lets a question
// about "plastic" find a paper that only ever says "polyethylene", and a
// question about "insects" find one that says "Galleria mellonella".
const CONCEPT_GROUPS = [
  // 2026-10-08 search reliability fix: physical/geoscience vocabulary was
  // missing. A query like "why does soil crack as it dries" had no concept
  // groups for cracking, drying, or patterns . so the concept-expanded
  // fallback couldn't find the synonyms papers actually use ("desiccation
  // cracking", "mudcrack", "polygonal pattern formation").
  ["crack", "cracks", "cracking", "cracked", "fracture", "fractures",
   "fracturing", "fractured", "fissure", "fissures", "fissuring",
   "mudcrack", "mudcracks", "desiccation crack", "desiccation cracking",
   "shrinkage crack"],
  ["dry", "dries", "drying", "dried", "desiccation", "desiccating",
   "desiccated", "dehydration", "dehydrated", "moisture loss", "water loss",
   "evaporation", "evaporative"],
  ["pattern", "patterns", "patterning", "patterned", "polygonal",
   "morphology", "morphological", "formation", "geometry", "geometric"],
  ["plastic", "plastics", "polymer", "polymers", "polyethylene", "polystyrene",
   "polypropylene", "polyurethane", "pvc", "pet", "ldpe", "hdpe", "microplastic",
   "microplastics", "nanoplastic", "nanoplastics", "polyolefin"],
  ["insect", "insects", "larva", "larvae", "larval", "worm", "worms", "caterpillar",
   "grub", "mealworm", "waxworm", "galleria", "tenebrio", "hermetia", "zophobas",
   "beetle", "moth", "fly", "arthropod", "arthropods", "entomological"],
  // 2026-10-13: methods vocabulary. A question about insect gut
  // homogenates retrieved only microbiome reviews, because the
  // digestive enzymology papers describe the same preparation as a
  // crude extract or gut extract, and the relevance matcher gated
  // them out as weak. One preparation, several names in print.
  ["homogenate", "homogenates", "homogenized", "homogenised", "homogenization",
   "crude extract", "crude extracts", "gut extract", "gut extracts",
   "midgut homogenate", "midgut extract", "midgut homogenates",
   "tissue homogenate", "tissue extract",
   "crude enzyme", "crude enzymatic", "enzyme preparation",
   // 2026-10-13 (fleet and coverage pass): the preparation PHRASINGS as
   // keys in the same group. The entries above only fire when a
   // question already contains homogenate wording; the live probe on
   // build 2197a8f ("Has anyone assayed digestive enzymes in whole gut
   // preparations from insects without isolating the enzymes?")
   // retrieved an assay flavored shelf, because nothing deterministic
   // bridged the phrasing a researcher actually uses to the vocabulary
   // the papers use. topicOverlapFilter scans CONCEPT_GROUPS for
   // multi word members present in the question and pulls the whole
   // group in as an accept set, so these keys make that scan bridge
   // preparation phrasing to homogenate vocabulary with no model call.
   "whole gut preparation", "whole gut preparations", "gut preparation",
   "gut preparations", "whole gut", "whole gut homogenate",
   "gut homogenate", "gut homogenates",
   // 2026-10-13 (midgut coverage): the field's dominant word for an
   // insect gut preparation is MIDGUT (midgut homogenate, midgut
   // extract), and the preparation phrasings above must reach those
   // forms deterministically too. "midgut extract" sits up in the
   // phrase run beside "midgut homogenate"; these tail forms widen
   // the group for the filter bridge and the phrase anchored rung.
   "midgut preparation", "midgut lysate", "insect midgut homogenate"],
  // 2026-10-09: BSFL concept group. The query term "bsfl" was not matching
  // papers that only wrote "Hermetia illucens" or "black soldier fly" because
  // SYNONYMS (used for query expansion) was not connected to CONCEPT_LOOKUP
  // (used by the scoring matcher). This group makes has("bsfl") match all
  // common name variants, so BSFL papers score correctly.
  ["bsfl", "bsf", "black soldier fly", "black soldier fly larvae",
   "black soldier fly larva", "hermetia", "hermetia illucens"],
  // 2026-10-15 (wave seventeen, citation depth diagnosis, stage
  // 4): the everyday vocabulary bridges, seeded statically so
  // they exist on EVERY draw. Before this, the only bridge from
  // "puff" to the edema literature was one nondeterministic
  // model expansion call — the parent run's draw lost it and
  // retrieved petroleum "huff and puff" papers for a question
  // about ankles, the diagnosis's draw won it and cited the
  // edema trial; same code, coin flip. The sleep and cold
  // bridges were the same coin (the diagnosis's sleep run's
  // expansion produced one group, a sleep deprivation group and
  // a common cold group reached only sometimes), and the waste
  // oil bridge matters because the literature writes "waste
  // cooking oil" and "used cooking oil" where people write
  // "fryer oil". Groups, not SYNONYMS entries: SYNONYMS keys
  // feed the scorer's neutral word machinery, which would
  // reclassify a symptom word as an organism word; every
  // consumer named by the diagnosis (the structured query
  // builder, the gate's concept groups, the scorer, the
  // deterministic fallback) reads the concept groups.
  ["puff", "swelling", "edema", "swollen"],
  // 2026-10-21 (search fix wave, Lane A): the restriction members
  // ride the TAIL of the sleep group. The Oct 20 audit's sleep
  // probes ("six hours every night for two weeks", "short nights
  // with barely any sleep") retrieved zero on point papers in both
  // phrasings while the canonical literature (Van Dongen 2003 and
  // replications) is written in exactly this vocabulary: chronic
  // sleep restriction, sleep loss, short sleep. Without these
  // members no rung, gate, or scorer could bridge the asker's
  // words to the papers' words deterministically; the bridge was
  // another model expansion coin flip of the kind wave seventeen
  // removed for puff and waste oil.
  ["sleep", "sleeping", "slept", "insomnia", "sleep deprivation",
   "sleep duration", "sleep quality", "sleep restriction",
   "sleep restricted", "chronic sleep restriction", "sleep loss",
   "short sleep", "sleep deprived"],
  ["cold", "common cold", "rhinovirus", "upper respiratory infection",
   "upper respiratory tract infection", "respiratory infection"],
  ["waste oil", "waste cooking oil", "used cooking oil", "cooking oil",
   "used oil"],
  // 2026-10-24 (citation wave, Lane 2): the burnout bridge. A
  // person asks about being "burned out"; the literature indexes
  // the same state under the single word "burnout", and no stem
  // connects them (the stemmers strip plural and s endings, never
  // the ed of "burned", and "burnout" is a compound, not an
  // inflection). On the live burnout probes the subject therefore
  // scored ZERO gate hits and zero concept engagement for every
  // paper that used the field's own word, while title only news
  // items carrying the population words rode phrase bonuses into
  // the cited set. The group is the Lane A bridge pattern: the
  // asker's phrasal forms and the literature's word as one
  // concept, so a citable paper must still engage a second
  // concept beside it. Bare "burned"/"burnt" are members so the
  // bare head term a key phrase yields ("burned" out of "burned
  // out") resolves the group; a thermal burns question resolves
  // the wound group through "burn"/"burns", different members,
  // and is untouched.
  ["burnout", "burned out", "burnt out", "burn out", "burning out",
   "burned-out", "burnt-out", "burned", "burnt"],
  // 2026-10-24 (citation wave, Lane 2): the graduate population
  // bridge. A question names its population once, in one wording
  // ("graduate school", "phd students"); the literature names the
  // same population a dozen ways (graduate students, doctoral
  // students, medical students, postgraduates, postdoctoral
  // trainees), and the floor's word counting treated the
  // question's wording as the only one that exists: on the live
  // burnout probes, papers engaging the subject plus this
  // population under any other wording scored one core hit and
  // were classed weak beside papers in mining and other
  // occupations that scored the same one hit. The members are
  // the standard wordings of the graduate and trainee
  // population, as one concept: engaging it satisfies the
  // population half of a question, never the subject half, so
  // the two concept standard still demands the subject beside
  // it.
  ["graduate student", "graduate students", "grad student",
   "grad students", "graduate school", "phd student",
   "phd students", "doctoral student", "doctoral students",
   "doctoral candidate", "doctoral candidates",
   "postgraduate student", "postgraduate students",
   "postgraduate", "medical student", "medical students",
   "postdoctoral student", "postdoctoral students",
   "postdoctoral researcher", "postdoctoral researchers",
   "graduate", "grad", "phd", "doctoral"],
  // 2026-10-21 (search fix wave, Lane A): honey and wound groups.
  // The honey probes had NO group at all: every central concept
  // resolved bare, and "honey" separately sits in ORGANISM_WORDS
  // (for honey bees), so honey as a treatment was judged by an
  // organism gate it cannot pass and by bare words alone. These
  // two groups give the gate and the structured query the same
  // bridge the other everyday topics have: the substance and the
  // wound it is put on, as separate concepts, so a citable paper
  // must still engage both.
  ["honey", "manuka honey", "medical grade honey", "honey dressing",
   "honey dressings"],
  ["wound", "wounds", "wound healing", "wound repair", "ulcer",
   "ulcers", "burn", "burns", "laceration", "lacerations"],
  // 2026-10-21 (search fix wave, Lane A): the wood breakdown
  // bridge. A plain phrasing describes the enzyme instead of
  // naming it ("the fungi enzyme that breaks down wood"), and no
  // table connected that phrase to the lignin vocabulary the
  // papers use, so expansion had nothing deterministic to stand
  // on and the draw filled with unrelated methacrylate papers.
  // The group's asker side members are the PHRASE and its
  // nominal forms, never the bare word "wood": a bare member
  // would resolve this group for every wood question (the wood
  // frog control in the query expansion suite resolves no
  // groups, and its standard is central terms alone). The
  // phrase scan in questionConceptGroups finds the multi word
  // members in the question's own text. The rest are the
  // literature's words for the same breakdown, manganese
  // peroxidase included, since it is the enzyme that phrase
  // describes in the fungal literature.
  ["breaks down wood", "breaking down wood", "wood breakdown",
   "wood decay", "lignin", "lignocellulose", "ligninolytic",
   "lignin degradation", "white rot", "white rot fungi",
   "manganese peroxidase", "lignin peroxidase"],
  // 2026-10-22 (search diagnosis, metagenomics trace): the two
  // sequencing subjects and the comparison they are put in. The
  // owner's question ("are there any primary research papers
  // that compares the ratio of metagenomics to
  // metatranscriptomics reads ... abundance:relative gene
  // expression") resolved NO concept group for either subject:
  // expansion (model and deterministic alike) grouped the
  // framing words instead ("primary", "organisms", "sense",
  // "order"), the one executed rung read "metagenomics ratio
  // order relative", and no source call ever required both
  // subjects, so the paired comparison literature (Franzosa
  // 2014, "Relating the metatranscriptome and metagenome of
  // the human gut"; the HUMAnN2 profiling paper) was never
  // gathered by any index — proven by an instrumented run in
  // which none of the four ground truth papers appeared in any
  // source's returns. The groups are the Lane A bridge pattern:
  // both subjects as separate concepts, so a citable paper must
  // engage the pair, and the comparison's own vocabulary as a
  // third, so the rebuilt boolean can phrase the ratio the
  // papers report. Members stay rooted to the two subjects'
  // own stems on purpose; the generic shotgun and microbiome
  // sequencing phrases live in SYNONYMS and would let any
  // single omics paper satisfy a subject rung.
  ["metagenome", "metagenomes", "metagenomics", "metagenomic",
   "metagenome sequencing", "metagenomic reads", "metagenome reads"],
  ["metatranscriptome", "metatranscriptomes", "metatranscriptomics",
   "metatranscriptomic", "metatranscriptome sequencing",
   "metatranscriptomic reads", "metatranscriptome reads"],
  ["relative gene expression", "gene expression", "rna dna ratio",
   "rna:dna ratio", "dna rna ratio", "transcriptional activity",
   "transcriptional contribution", "relative expression",
   "transcript abundance", "expression ratio"],
  // 2026-10-13 (wave two): "germ"/"germs" appended at the tail. Plain
  // everyday wording for microbes had no group at all, so a question
  // asking about "the germs in a baby's belly" collapsed to the literal
  // tokens and cited phrase collisions (belly dance obstetrics, prune
  // belly syndrome). Tail placement keeps every existing rung that
  // renders this group's head members byte identical.
  ["microbe", "microbes", "microbial", "microbiome", "microbiota", "bacteria",
   "bacterial", "bacterium", "gut flora", "microflora", "symbiont", "symbionts",
   "microorganism", "microorganisms", "germ", "germs"],
  ["enzyme", "enzymes", "enzymatic", "oxidase", "oxidases", "hydrolase",
   "hydrolases", "esterase", "esterases", "cutinase", "lipase", "protease",
   "depolymerase", "oxidoreductase", "oxidoreductases", "phenoloxidase",
   "laccase", "peroxidase"],
  ["degrade", "degradation", "degrading", "biodegradation", "biodegrade",
   "breakdown", "depolymerization", "depolymerisation", "catabolism",
   "decompose", "decomposition", "oxidation", "oxidize", "oxidise", "oxidative"],
  ["gut", "intestinal", "intestine", "digestive", "midgut", "hindgut", "foregut",
   "gastrointestinal", "alimentary", "crop", "proventriculus",
   "peritrophic membrane", "alimentary canal", "digestive tract",
   // 2026-10-13 (wave two): the everyday body words, appended at the
   // tail so rungs rendering this group's head members stay byte
   // identical. "stomach" and "tummy" had NO handling anywhere in the
   // tables before this (no group, no synonym); "belly" likewise, so
   // a plain language question about a baby's belly never reached the
   // gut vocabulary the papers use. This group is the tables' body
   // word group (it already spans gastrointestinal, alimentary, and
   // digestive), so the pathway belongs here: belly/tummy/stomach/
   // abdomen resolve to it, and its members accept belly worded
   // papers in return.
   "belly", "tummy", "stomach", "abdomen", "abdominal"],
  ["saliva", "salivary", "secretion", "secretions", "oral", "labial"],
  ["cancer", "tumour", "tumor", "carcinoma", "neoplasm", "oncology", "malignant"],
  // Split from a single overly-broad ["gene","genes","genetic","genomic",
  // "genome","transcript","transcriptome"] group. That group let a query
  // term "genetic" (e.g. from "mobile genetic elements") count ANY paper
  // mentioning "genome" or "transcriptome" as a match . which is how a
  // canine reference-genome paper, a bovine genome-annotation paper, and a
  // maize single-cell atlas all scored as relevant to a question about
  // insect-microbe mobile genetic elements. "Gene-level", "genome-level",
  // and "transcript-level" are related but genuinely different research
  // topics/methods; conflating them causes false-topic query expansion.
  ["gene", "genes", "genetic"],
  ["genome", "genomic", "genomics"],
  ["transcript", "transcripts", "transcriptome", "transcriptomic"],
  // The ACTUAL concept behind "mobile genetic elements" . transposons,
  // plasmids, phages/prophages, insertion sequences, integrons. Without
  // this, "genetic" (from "mobile genetic elements") had no correct
  // concept group to expand into and fell back to the generic gene group
  // above, or worse, the old conflated genome/transcriptome group.
  ["transposon", "transposons", "transposable element", "transposable elements",
   "plasmid", "plasmids", "horizontal gene transfer", "prophage", "prophages",
   "insertion sequence", "insertion sequences", "integron", "integrons",
   "conjugative transposon", "mobile genetic element", "mobile genetic elements",
   "bacteriophage", "bacteriophages", "phage", "phages"],
  ["protein", "proteins", "proteomic", "peptide", "peptides", "polypeptide"],
  ["climate", "warming", "temperature", "thermal", "heat"],
  // 2026-10-21 (search fix wave, Lane A): the cognitive members
  // ride the tail. A plain sleep question asks what happens to
  // your BRAIN; the restriction literature answers in cognitive
  // vocabulary (neurobehavioral functions, attention, working
  // memory) and may never use the word brain at all, so the
  // canonical papers engaged only one of the question's two
  // backed concepts and failed the two concept standard no
  // matter their score. The members are the brain literature's
  // own outcome words, appended at the tail like the other
  // everyday bridges.
  ["neuron", "neurons", "neural", "neuronal", "brain", "cortical", "cerebral",
   "cognitive", "cognition", "neurobehavioral", "attention", "working memory"],
  // Ecology / environment
  ["ecology", "ecological", "ecosystem", "ecosystems", "community", "communities",
   "biodiversity", "species richness", "assemblage"],
  ["network", "networks", "co-occurrence", "cooccurrence", "interaction",
   "interactions", "graph", "connectivity", "modularity"],
  ["soil", "soils", "edaphic", "rhizosphere", "pedosphere", "substrate"],
  // Crop rotation (2026-10-13, wave two): the practice of planting
  // different crops in sequence on the same field across seasons.
  // Everyday phrasings ("different crops on the same field in
  // different years", "rotating crops") carried none of the field's
  // vocabulary, so the boolean shipped the literal words and the
  // shelf filled with collisions. The phrase members are what the
  // phrase scans in buildStructuredQuery and topicOverlapFilter key
  // on; "crop" itself stays claimed by the gut group above (the
  // insect crop organ), which is exactly why this group leads with
  // the two word practice names instead of the bare noun.
  ["crop rotation", "crop rotations", "rotating crops", "rotate crops",
   "rotated crops", "crops in rotation", "rotation of crops",
   "rotational cropping", "crop sequence", "crop sequences", "crop succession",
   "cover crop", "cover crops",
   // The descriptive shapes, still distinctive enough to key on:
   // several crops sharing one field is the rotation setup itself,
   // and a different crop each year is the practice stated as a
   // schedule. Neither can appear in an unrelated question without
   // the question being about this practice in substance.
   "crops on the same field", "different crops each year",
   "different crop each year", "different crops every year"],
  ["ocean", "oceanic", "marine", "sea", "seawater", "pelagic", "benthic"],
  ["coral", "corals", "reef", "reefs", "calcification", "bleaching"],
  ["forest", "forests", "woodland", "canopy", "tree", "trees", "silviculture"],
  // Molecular biology
  ["mutation", "mutations", "variant", "variants", "polymorphism", "snp", "indel"],
  ["expression", "transcription", "regulation", "promoter", "enhancer", "silencer"],
  ["antibody", "antibodies", "immunoglobulin", "antigen", "epitope"],
  ["vaccine", "vaccines", "vaccination", "immunization", "adjuvant"],
  ["virus", "viruses", "viral", "virology", "pathogen", "infection", "infectious"],
  // Chemistry
  ["nanoparticle", "nanoparticles", "nanostructure", "nanomaterial", "quantum dot"],
  ["catalyst", "catalysts", "catalysis", "catalytic", "photocatalyst", "electrocatalyst"],
  // Decomposition / decay
  // Chemical conversion / synthesis
  ["ethanol", "ethyl alcohol", "bioethanol", "alcohol", "fermentation"],
  ["co2", "carbon dioxide", "carbon capture", "atmospheric carbon", "carbon fixation"],
  ["conversion", "synthesis", "catalysis", "electrochemical", "electrolysis",
   "reduction", "oxidation", "transformation"],
  ["decomposition", "decompose", "decay", "necrobiome", "cadaver", "carcass",
   "putrefaction", "autolysis", "bloat", "rupture"],
  // Photosynthesis / plant energy
  ["photosynthesis", "photosynthetic", "chloroplast", "chlorophyll", "light reactions",
   "dark reactions", "calvin cycle", "rubisco", "carbon fixation", "thylakoid",
   "photosystem", "photoautotroph", "c3", "c4", "cam"],
  // Parasitic / heterotrophic plants
  ["parasitic", "parasite", "mycoheterotroph", "mycoheterotrophic", "holoparasite",
   "hemiparasite", "heterotroph", "heterotrophic", "non-photosynthetic",
   "achlorophyllous"],
  // Touch response plants (2026-10-13, wave two): the sensitive
  // plant path. People ask about this plant in pure everyday words
  // ("why do some plants fold their leaves when you touch them")
  // that share nothing with the literature's vocabulary (Mimosa
  // pudica, thigmonasty, the pulvinus motor organ). The group keys
  // on the plant's common names, the everyday leaf movement phrases
  // the phrase scans can see verbatim in a question, and the field
  // terms papers actually use, so any of those phrasings pulls the
  // whole shelf vocabulary in.
  ["mimosa pudica", "mimosa", "sensitive plant", "touch-me-not", "touch me not",
   "shy plant", "thigmonasty", "thigmonastic", "seismonasty", "seismonastic",
   "leaf folding", "fold their leaves", "leaves fold", "folds its leaves",
   "close when touched", "closes when touched", "pulvinus", "pulvini",
   "nastic movement", "nastic movements"],
  // Abundance / diversity (common ecological measures)
  ["abundance", "diversity", "richness", "composition", "community structure",
   "alpha diversity", "beta diversity", "evenness", "dominance"],
  // Evolution / adaptation
  ["evolution", "evolutionary", "phylogenetic", "phylogeny", "adaptation",
   "selection", "speciation", "divergence", "convergent"],
  // Immunology
  ["immune", "immunity", "innate immunity", "adaptive immunity", "inflammatory",
   "inflammation", "cytokine", "chemokine", "lymphocyte"],
  // Stem cells & regeneration
  ["stem cell", "stem cells", "pluripotent", "multipotent", "ipsc", "ips cell",
   "embryonic stem cell", "progenitor", "differentiation", "reprogramming"],
  // Epigenetics
  ["epigenetic", "epigenetics", "methylation", "histone", "chromatin",
   "acetylation", "imprinting", "epigenome", "chromatin remodeling"],
  // Drug / pharmacology
  ["drug", "drugs", "pharmaceutical", "pharmacological", "therapeutic",
   "therapy", "treatment", "medication", "compound", "inhibitor"],
  // Apoptosis / cell death
  ["apoptosis", "apoptotic", "programmed cell death", "necrosis", "necroptosis",
   "pyroptosis", "ferroptosis", "autophagy", "autophagic", "cell death"],
  // Metabolism
  ["metabolism", "metabolic", "metabolite", "metabolites", "metabolome",
   "glycolysis", "krebs cycle", "tca cycle", "oxidative phosphorylation",
   "fatty acid oxidation", "beta oxidation"],
  // Aging / senescence
  ["aging", "ageing", "senescence", "senescent", "longevity", "lifespan",
   "telomere", "telomerase", "gerontology"],
  // Biofilm / microbial community
  ["biofilm", "biofilms", "quorum sensing", "planktonic", "sessile",
   "extracellular polymeric substance", "eps", "biofouling"],
  // Antibiotic resistance
  ["antibiotic resistance", "antimicrobial resistance", "amr", "multidrug resistant",
   "mdr", "drug resistant", "beta-lactamase", "efflux pump", "resistance gene"],
  // CRISPR & gene editing
  ["crispr", "cas9", "cas12", "cas13", "gene editing", "genome editing",
   "guide rna", "sgrna", "base editing", "prime editing"],
  // Microscopy / imaging
  ["microscopy", "microscope", "imaging", "fluorescence", "confocal",
   "electron microscopy", "sem", "tem", "super-resolution", "cryo-em"],
  // Bioinformatics / computation
  ["bioinformatics", "computational biology", "sequence analysis", "alignment",
   "phylogenetics", "homology", "blast", "pipeline", "annotation"],
  // Diabetes / metabolic disease
  ["diabetes", "diabetic", "insulin", "glucose", "glycemic", "hyperglycemia",
   "type 2 diabetes", "type 1 diabetes", "insulin resistance", "metabolic syndrome"],
  // Cardiovascular
  ["cardiovascular", "cardiac", "heart", "myocardial", "coronary",
   "atherosclerosis", "hypertension", "ischemia", "arrhythmia"],
  // Respiratory
  ["lung", "lungs", "pulmonary", "respiratory", "airway", "alveolar",
   "bronchial", "asthma", "copd", "pneumonia"],
  // Gut-brain axis
  ["gut-brain", "gut brain axis", "microbiome brain", "enteric nervous system",
   "vagus nerve", "psychobiotic", "neuroinflammation"],
  // Food science / nutrition
  ["nutrition", "nutritional", "dietary", "diet", "nutrient", "nutrients",
   "bioavailability", "fortification", "supplementation", "nutraceutical"],
];

// Build a fast lookup: term -> the full set of equivalent terms
const CONCEPT_LOOKUP = (() => {
  const map = new Map();
  for (const group of CONCEPT_GROUPS) {
    const set = new Set(group);
    for (const t of group) map.set(t, set);
  }
  return map;
})();

// ── Typed relations inside concept groups (2026-10-23, logic
// audit L1-8) ────────────────────────────────────────────────
// The flat groups above were read as equivalence sets by every
// consumer, but they encode association and hypernymy as often
// as equivalence: "sleep" grouped with "insomnia" (a disorder
// beside it) and "sleep duration" (an aspect of it), "waste
// oil" with bare "cooking oil" (the qualifier the question
// turns on, dropped), "enzyme" with its subtypes. Widening and
// gating inherit opposite needs from that mixture. OR widening
// may use any member: a narrower or related term is a
// legitimate way to find more of the literature. A GATE touch
// is a satisfaction claim, and it requires a synonym or a
// narrower term, never a qualifier dropping broader term and
// never a merely related one: a paper feeding larvae fresh
// cooking oil has not touched the waste oil concept, however
// close the words are. The typed tables below name the
// relations for the groups the audit evidenced; consumers
// that count touches (centralConceptHits, paperConceptGroupHits)
// read gateConceptSetFor, widening consumers keep the full set.
export const CONCEPT_GROUP_RELATIONS = [
  {
    head: "sleep",
    synonyms: ["sleep", "sleeping", "slept"],
    narrower: ["sleep deprivation", "sleep restriction", "sleep restricted",
      "chronic sleep restriction", "sleep loss", "short sleep", "sleep deprived"],
    broader: [],
    related: ["insomnia", "sleep duration", "sleep quality"],
  },
  {
    head: "waste oil",
    synonyms: ["waste oil", "waste cooking oil", "used cooking oil"],
    narrower: [],
    broader: ["cooking oil", "used oil"],
    related: [],
  },
  {
    head: "enzyme",
    synonyms: ["enzyme", "enzymes", "enzymatic"],
    narrower: ["oxidase", "oxidases", "hydrolase", "hydrolases", "esterase",
      "esterases", "cutinase", "lipase", "protease", "depolymerase",
      "oxidoreductase", "oxidoreductases", "phenoloxidase", "laccase", "peroxidase"],
    broader: [],
    related: [],
  },
];

// The typed view of one hand group. Matching is by CONTENT,
// not Set identity: the lookup hands out one Set per group,
// but the pipeline also rebuilds group Sets (buildDynLookup
// copies every group it merges), so an identity keyed table
// would silently never fire on the handler path. A group is
// the typed entry's group when it names the entry's head
// term; its gate set is then the group's OWN members that the
// entry types as synonyms or narrower, so a rebuilt or
// supplemented copy keeps exactly the typed members it
// actually carries. Returns null for groups with no typed
// table: those keep the flat reading everywhere, exactly as
// before, until someone types them.
export function typedConceptGroup(group) {
  if (!group || typeof group.has !== "function") return null;
  for (const rel of CONCEPT_GROUP_RELATIONS) {
    if (!group.has(rel.head)) continue;
    const allowed = new Set([...(rel.synonyms || []), ...(rel.narrower || [])]);
    const gate = new Set([...group].filter((m) => allowed.has(m)));
    if (gate.size === 0) continue;
    return { head: rel.head, gate, widen: group, relations: rel };
  }
  return null;
}

// The set a gate touch may be counted on: for a typed group,
// synonyms and narrower terms only. For anything else, the
// group itself, unchanged.
export function gateConceptSetFor(group) {
  const typed = typedConceptGroup(group);
  return typed ? typed.gate : group;
}

// ════════════════════════════════════════════════════════════════════
// MODEL-PROPOSED CONCEPT GROUPS (2026-10-13)
//
// CONCEPT_GROUPS above is hand written. Every vocabulary mismatch a
// user hits needs a human to notice it and add a group by hand . the
// homogenate fix (2026-10-13) was exactly that: a question about gut
// homogenates retrieved only microbiome reviews until someone added
// "crude extract / gut extract" to the table by hand.
//
// Now a single cheap model call proposes equivalent groups per
// question, for specific terms the hand written table does NOT cover.
// Three safeguards keep the model on a short leash:
//   1. The prompt may only reword concepts already in the question.
//      It may never drop a constraint or introduce a new topic,
//      organism, or method.
//   2. Everything proposed passes validateExpansionGroups(), a strict
//      deterministic gate (shape, character, size, and the term must
//      literally appear in the question). Junk yields no groups.
//   3. The result is request scoped only. It is built fresh inside
//      gatherPapers() and passed down as a parameter. Module state is
//      never mutated per request: Workers isolates serve concurrent
//      requests, so a shared mutable lookup would be a race.
// Any failure (no key, timeout, rate limit, unparseable reply) fails
// open to no groups, and the search runs exactly as before.
// ════════════════════════════════════════════════════════════════════

// Resolve a term's equivalence set, model-proposed groups first.
// dynLookup is a Map in the CONCEPT_LOOKUP value shape (or null).
function conceptSetFor(term, dynLookup) {
  return (dynLookup && dynLookup.get(term)) || CONCEPT_LOOKUP.get(term) || null;
}

// Words that frame a question rather than name a concept. A proposed
// group built on one of these, or an "alternate" that is one of these,
// is the model padding its answer, not rewording anything.
const EXPANSION_FRAMING_WORDS = new Set([
  "the", "what", "how", "study", "studies", "paper", "papers", "research",
  // People and role words (2026-10-13): the model spent its group cap
  // expanding "scientist" and "researcher" on plain language probes.
  // Who is asking is never the concept a paper phrases differently.
  "scientist", "scientists", "researcher", "researchers",
  "investigator", "investigators", "author", "authors", "people",
  "person", "someone", "anyone",
]);

// Negation leads (2026-10-13): a concept that denotes an ABSENCE can
// never be a positive boolean requirement. Live probe on build
// 553caa4: "Has anyone assayed digestive enzymes in whole gut
// preparations from insects without isolating the enzymes?" shipped
// a structured query whose second rung was ("without isolat enzyme"
// OR "without isolated enzyme" OR "without purified enzyme" OR
// "without enzyme purification") . a REQUIRED AND constraint.
// Papers almost never phrase an absence, so the boolean starved
// (gathered 42, against 80 on the looser prior build) and the answer
// was a scoped No again. A negation led group is therefore rejected
// at the validator and skipped again, defensively, when
// buildStructuredQuery forms its AND rungs. Widening uses (OR
// fallbacks, topicOverlapFilter accept sets) are unaffected: an
// absence term may help ACCEPT a paper, it just may never GATE one.
const EXPANSION_NEGATION_LEADS = new Set([
  "without", "not", "no", "never", "non", "lacking",
]);
const EXPANSION_NEGATION_PHRASES = ["absence of", "free of"];

// True when a cleaned, lowercased term BEGINS with a negation lead as
// a whole word (or as a whole lead phrase). Whole word matching is
// deliberate on both sides:
//   . "nitrogen fixation" is safe: its first word is "nitrogen",
//     not "no" . the letters n-o inside a longer word are not a lead.
//   . Closed "non" compounds are safe: "noncoding", "nonlinear", and
//     "non-photosynthetic" (a real CONCEPT_GROUPS member, in the
//     parasitic plant group) are ordinary positive vocabulary that
//     papers use constantly. Only a standalone "non" ("non coding")
//     counts as a lead.
export function hasNegationLead(term) {
  const t = String(term || "").toLowerCase().trim().replace(/\s+/g, " ");
  if (!t) return false;
  for (const phrase of EXPANSION_NEGATION_PHRASES) {
    if (t === phrase || t.startsWith(phrase + " ")) return true;
  }
  return EXPANSION_NEGATION_LEADS.has(t.split(" ")[0]);
}

// Wording accepted in an expansion term or alternate (2026-10-22,
// L1-2 repair). The old alphabet test only allowed letters, spaces
// and hyphens, so it deleted exactly the alternates that carry a
// stated quantity: digits, units, abbreviations and symbols such
// as "6 hours", "14 days", "mg/dl" or a percent figure. Wording is
// now judged by shape, not by alphabet: letters and digits, spaces,
// hyphens, dots, slashes, percent signs and plus signs, starting
// with a letter or a digit and never ending in a hyphen. Junk
// punctuation (exclamation marks, hashes, underscores and the
// like) is still refused, so a malformed alternate still drops
// while the clean ones beside it survive.
export function isAcceptableExpansionWording(s) {
  const t = String(s || "");
  if (!t || t.length > 60) return false;
  if (!/^[a-z0-9][a-z0-9\s\-./%+]*$/.test(t)) return false;
  if (!/[a-z0-9]/.test(t)) return false;
  if (t.endsWith("-") || t.endsWith("/")) return false;
  return true;
}

// True when a term is itself a stated quantity constraint of the
// question: a quantity phrase in the gate sense (a number word or
// digit beside a time unit, as in "six hours" or "two weeks"), or
// any term carrying a digit. Such terms are the discriminating
// constraints of dose and duration questions, so their groups get
// the single alternate and numeric allowances in the validator
// below. isQuantityPhraseKey is the diagnosis era predicate the
// gate already uses for the same class; it is read at call time.
export function isQuantityConstraintTerm(term) {
  const t = String(term || "").toLowerCase().trim();
  if (!t) return false;
  if (/\d/.test(t)) return true;
  try { return isQuantityPhraseKey(t); } catch { return false; }
}

// Strict gate for model-proposed expansion groups. Accepts the model's
// reply as an already-parsed value or as raw text (JSON, possibly
// fenced). Returns a clean array of { term, alternates }:
//   . term is lowercased and appears in the query as a word or phrase
//   . alternates are unique strings of 1 to 4 words in acceptable
//     wording (see isAcceptableExpansionWording: digits, units,
//     symbols and abbreviations are allowed), none equal to the
//     term, none a framing word; a list over the cap of 6 is
//     trimmed to the cap, never a reason to drop the group
//   . a group normally needs at least 2 surviving alternates; a
//     single alternate survives when the term itself is a stated
//     quantity constraint (isQuantityConstraintTerm), because a
//     dose or duration may have exactly one equivalent wording
//   . the term never begins with a negation lead (hasNegationLead):
//     an absence cannot be a boolean requirement
//   . at most 4 groups; concepts past the cap are not lost
//     silently, they are decided by the coverage computation
//     (resolveExpansionCoverage), which represents them as plain
//     term groups within its total budget or records them as
//     uncovered and cut in the search record
// Anything invalid, at any level, degrades toward [] and never throws.
export function validateExpansionGroups(raw, query) {
  let data = raw;
  if (typeof data === "string") {
    const cleaned = data.replace(/```json|```/g, "").trim();
    try {
      data = JSON.parse(cleaned);
    } catch {
      // Reasoning models sometimes wrap the array in prose. Recover
      // the outermost bracketed array when one exists; anything else
      // stays invalid.
      const lo = cleaned.indexOf("[");
      const hi = cleaned.lastIndexOf("]");
      if (lo === -1 || hi <= lo) return [];
      try { data = JSON.parse(cleaned.slice(lo, hi + 1)); } catch { return []; }
    }
  }
  if (data && typeof data === "object" && !Array.isArray(data)) {
    // Tolerate an object wrapper ({"groups": [...]}) around the array.
    data = data.groups || data.expansions || data.concepts || null;
  }
  if (!Array.isArray(data)) return [];

  const q = String(query || "").toLowerCase().replace(/\s+/g, " ");
  if (!q) return [];

  const cleanPiece = (s) =>
    String(s || "").toLowerCase().trim().replace(/\s+/g, " ");
  const isCleanWording = isAcceptableExpansionWording;
  const inQuery = (term) => {
    const esc = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
    // The optional trailing s tolerates a plain plural only: the
    // model proposes "whole gut preparation" while the question says
    // "preparations" (2026-10-13). A longer continuation still fails,
    // so substring terms ("zorblax" inside "zorblaxin") stay rejected.
    // Boundaries are alphanumeric, not letters only, so a digit
    // bearing term ("6 hours") can be found in the question at all.
    return new RegExp("(^|[^a-z0-9])" + esc + "s?([^a-z0-9]|$)").test(q);
  };

  const out = [];
  const seenTerms = new Set();
  for (const entry of data) {
    if (out.length >= 4) break;
    if (!entry || typeof entry !== "object") continue;
    const term = cleanPiece(entry.term);
    if (!term || seenTerms.has(term)) continue;
    if (term.split(" ").length > 4 || !isCleanWording(term)) continue;
    if (EXPANSION_FRAMING_WORDS.has(term)) continue;
    // WAVE EIGHT (2026-10-14, Job 3a): a group whose term is
    // closed class scaffolding (every content token a gate
    // function word) is not a concept group: the model proposing
    // one for "while" gets the same refusal the deterministic
    // paths give, so no group of its own exists for it anywhere
    // it would gate.
    if (term.split(" ").every((w) => isGateFunctionWord(w))) continue;
    // An absence is not a searchable concept: a negation led group
    // can never become a boolean requirement (see hasNegationLead).
    if (hasNegationLead(term)) continue;
    if (!inQuery(term)) continue;
    if (!Array.isArray(entry.alternates)) continue;
    // An oversized list is trimmed to the cap below (the slice on
    // the push), never a reason to discard the whole group: the
    // first entries are the model's best equivalences, and dropping
    // the group lost the concept with them (2026-10-22, L1-2).
    const alts = [];
    const seenAlts = new Set();
    for (const a of entry.alternates) {
      if (typeof a !== "string") continue;
      const alt = cleanPiece(a);
      if (!alt || alt === term || seenAlts.has(alt)) continue;
      if (alt.split(" ").length > 4 || !isCleanWording(alt)) continue;
      if (EXPANSION_FRAMING_WORDS.has(alt)) continue;
      // Sense test (2026-10-23, L1-9): an unlabeled alternate is
      // claimed as the same thing in the same sense. For a term
      // with known rival senses, that claim must be evidenced
      // against the question's other concepts or the hand
      // tables before the alternate may drive retrieval. The
      // audit's specimen: "fine" bridged to the size sense
      // (small, tiny, minute) on a question whose sense was
      // okay, and "grow" to population growth on a larval
      // growth question, and both bridges drove retrieval.
      if (!expansionAlternatePassesSenseTest(term, alt, q)) continue;
      seenAlts.add(alt);
      alts.push(alt);
    }
    // Labeled alternate classes (2026-10-23, L1-9): expansion is
    // by concept, not by word. A concept's bridge to the
    // literature is often not a synonym at all: the outcome is
    // measured as vigilance lapses or closure time, the
    // activity as an absorbance change. Those forms arrive in
    // separately labeled classes (outcome measures,
    // instruments, study design vocabulary), each held to the
    // class test in expansionClassAlternatePasses, and they
    // ride the group's alternates so every existing consumer
    // sees them, with the labels preserved on the group.
    const classes = {};
    let classAltCount = 0;
    for (const [field, label] of [["outcomeMeasures", "outcomeMeasures"], ["instruments", "instruments"], ["studyDesign", "studyDesign"]]) {
      const rawList = Array.isArray(entry[field]) ? entry[field]
        : (entry.classes && Array.isArray(entry.classes[field]) ? entry.classes[field] : []);
      const kept = [];
      for (const a of rawList) {
        if (typeof a !== "string") continue;
        const alt = cleanPiece(a);
        if (!alt || alt === term || seenAlts.has(alt)) continue;
        if (alt.split(" ").length > 4 || !isCleanWording(alt)) continue;
        if (EXPANSION_FRAMING_WORDS.has(alt)) continue;
        if (!expansionClassAlternatePasses(alt)) continue;
        seenAlts.add(alt);
        kept.push(alt);
        alts.push(alt);
        classAltCount++;
      }
      if (kept.length > 0) classes[label] = kept.slice(0, 4);
    }
    if (alts.length === 0) continue;
    // The two alternate floor stands for ordinary concepts. A
    // stated quantity constraint keeps its single alternate: a
    // dose or duration often has exactly one equivalent wording
    // ("six hours" to "6 hours"), and dropping the group deleted
    // the constraint the question turns on.
    if (alts.length < 2 && !isQuantityConstraintTerm(term)) continue;
    seenTerms.add(term);
    const group = { term, alternates: alts.slice(0, 6) };
    if (classAltCount > 0) group.classes = classes;
    out.push(group);
  }
  return out;
}

// Terms with known rival senses (2026-10-23, L1-9): the
// ambiguity table's terms, plus the everyday outcome words the
// audit's specimen turned on. Only alternates proposed for
// these terms face the sense test; a technical term nobody has
// flagged keeps the validator's previous behavior, because for
// such a term the model's bridge is often the only one there
// is and a false rejection recreates the coverage failure.
const EXPANSION_SENSE_RISK_EXTRA = new Set([
  "fine", "grow", "grows", "grew", "growing", "growth",
  "strong", "weak", "active", "working", "check", "test",
]);
function expansionSenseRiskTerms() {
  const out = new Set(EXPANSION_SENSE_RISK_EXTRA);
  try {
    for (const e of AMBIGUOUS_QUERY_TERMS) if (e && e.term) out.add(e.term);
  } catch { /* the extra set stands alone */ }
  return out;
}

// The sense test for one proposed alternate (2026-10-23, L1-9).
// Passes when the alternate is anchored to the question as
// asked: it shares a content token with the term or with the
// question's other content words (co occurrence with the
// subject concept is the cheapest sense evidence there is), it
// is vocabulary the hand tables already carry for some concept
// in the question, or it carries a digit (a quantity
// equivalence, judged by L1-2's rules). Non risk terms pass
// unconditionally.
export function expansionAlternatePassesSenseTest(term, alt, query) {
  const t = String(term || "").toLowerCase().trim();
  if (!expansionSenseRiskTerms().has(t)) return true;
  const a = String(alt || "").toLowerCase().trim();
  if (!a) return false;
  if (/\d/.test(a)) return true;
  const q = String(query || "").toLowerCase();
  const altToks = a.split(/[^a-z0-9]+/).filter((w) => w.length > 2);
  const termToks = new Set(t.split(/[^a-z0-9]+/).filter(Boolean));
  const qToks = new Set(q.split(/[^a-z0-9]+/).filter((w) => w.length > 2));
  for (const tok of altToks) {
    if (termToks.has(tok)) return true;
    if (qToks.has(tok) && !termToks.has(tok)) return true;
  }
  // Hand table vocabulary: an alternate some curated group,
  // synonym entry, or MeSH expansion already names is anchored
  // by the tables, whatever its tokens.
  try {
    for (const set of CONCEPT_LOOKUP.values()) if (set.has(a)) return true;
  } catch { /* tables are evidence, not a requirement */ }
  try {
    for (const vals of Object.values(SYNONYMS)) {
      if (Array.isArray(vals) && vals.some((v) => String(v).toLowerCase() === a)) return true;
    }
  } catch { /* as above */ }
  return false;
}

// The class test for a labeled alternate (2026-10-23, L1-9):
// outcome measures, instruments, and study design vocabulary
// are field vocabulary by construction, so a labeled alternate
// passes when it is multi word (a named measure, instrument, or
// design is a phrase), when the hand tables carry it, or when
// it contains a token from the field vocabulary families the
// classes exist to name.
const EXPANSION_CLASS_FIELD_TOKENS = new Set([
  "survival", "mortality", "weight", "gain", "growth", "closure",
  "healing", "time", "rate", "vigilance", "lapses", "lapse",
  "performance", "absorbance", "wavelength", "assay", "assays",
  "spectrophotometric", "randomized", "randomised", "cohort",
  "trial", "placebo", "controlled", "restriction", "deprivation",
  "latency", "threshold", "score", "scores", "index", "scale",
]);
export function expansionClassAlternatePasses(alt) {
  const a = String(alt || "").toLowerCase().trim();
  if (!a) return false;
  if (a.includes(" ")) return true;
  try {
    for (const set of CONCEPT_LOOKUP.values()) if (set.has(a)) return true;
  } catch { /* as above */ }
  return a.split(/[^a-z0-9]+/).some((tok) => EXPANSION_CLASS_FIELD_TOKENS.has(tok));
}

// Build a lookup in exactly the CONCEPT_LOOKUP shape (term -> Set of
// the term plus its alternates) from validated groups, so every
// consumer written against CONCEPT_LOOKUP works unchanged.
export function buildDynLookup(groups) {
  const map = new Map();
  if (!Array.isArray(groups)) return map;
  for (const g of groups) {
    if (!g || typeof g.term !== "string" || !Array.isArray(g.alternates)) continue;
    map.set(g.term, new Set([g.term, ...g.alternates]));
  }
  // Provenance (2026-10-23, logic audit L3-13): a groups array
  // carrying a live provider via (openrouter, groq, gemini,
  // workers ai) marks its lookup as live model output. The
  // deterministic fallback's via ("fallback") and unmarked
  // caller built lookups carry no mark. gateDynLookup reads
  // the mark; retrieval consumers ignore it.
  const via = groups.via;
  const anyLiveGroup = groups.some((g) => g && g._liveModel === true);
  if ((typeof via === "string" && via && via !== "fallback") || anyLiveGroup) {
    try { map._liveModelVia = typeof via === "string" && via ? via : "model"; } catch { /* a frozen map keeps the old behavior */ }
  }
  return map;
}

/* ── Deterministic fallback expansion (2026-10-14, fourth panel) ──
 * The model leg above is one capped pool away from silence: on the
 * fourth panel's fresh questions it returned zero validated groups
 * on 4 of 5 probes, and every downstream consumer then ran with
 * the question's central vocabulary uncovered — the boolean rungs
 * lost their OR forms, the relevance matcher lost its bridge, and
 * the citation gate's resolution lost the very groups that would
 * have barred a keyword collision paper from being cited. The
 * fallback below builds groups for the uncovered central terms
 * from the codebase's OWN deterministic tables, no model involved:
 *   . a curated CONCEPT_GROUPS group the term inflects into
 *     (sleeping -> the sleep group), attached whole;
 *   . the SYNONYMS table in both directions: a key whose value
 *     list names the term contributes itself and its siblings,
 *     and a multi word key present in the question that contains
 *     the term contributes its values (soldier in "black soldier
 *     fly" -> Hermetia illucens, the organism bridge);
 *   . the term's own inflections (singular and plural forms),
 *     which guarantee the group can test membership at all.
 * Same output shape and caps as the validator's (at most 4 groups,
 * at most 6 alternates), same exclusions (framing words, negation
 * leads). It is recorded honestly wherever the model groups are:
 * the groups ride diag.llmExpanded with via "fallback", never a
 * provider name, and retrievalStrategiesTried names the fallback
 * as the fallback. It spends no subrequests, so gatherPapers runs
 * it even when the model leg was budget skipped. */

// The light inflection family of a single word: the forms a paper
// might use for the same word. Deliberately narrow (plural and
// singular swaps only): a wider stemmer would attach curated
// groups by prefix accidents (germ -> germination, creatine ->
// creatinine are different concepts, not inflections).
export function inflectionVariants(term) {
  const t = String(term || "").toLowerCase().trim();
  const out = new Set();
  if (!t || /\s/.test(t)) return out;
  if (t.endsWith("ies") && t.length > 3) out.add(t.slice(0, -3) + "y");
  else if (t.endsWith("es") && t.length > 3) out.add(t.slice(0, -2));
  // Singular strip, with a plausibility guard (2026-10-14, fifth
  // panel, Job 2a): words ending in "us", "is", or "ss" are not
  // plurals, and stripping their final s mints non words
  // ("analysis" -> "analysi", "status" -> "statu"). A real plural
  // strip also needs a stem worth keeping (length above 3).
  else if (t.endsWith("s") && t.length > 3 && !/(us|is|ss)$/.test(t)) out.add(t.slice(0, -1));
  if (!t.endsWith("s")) {
    // Plural formation plausibility (2026-10-14, sixth panel,
    // wave seven): the fallback's alternates shipped as literal
    // database query terms and user facing reformulation fodder,
    // and the unguarded +"s" minted non words — "sinces" (a
    // conjunction is not a noun and never pluralizes), "evers",
    // "looses". Two morphological rules now bound the plural:
    // no plural of a word ending in nce or rce (since, once,
    // source — function words and abstract nouns whose s forms
    // are not plurals), and no plural of a closed class or
    // framing word at all (STOPWORDS and EXPANSION_FRAMING_WORDS
    // are read at call time; both are module level by then). The
    // generation site in buildDeterministicFallbackGroups is
    // stricter still (plurals only for concept heads and key
    // phrase terms — see nounFormVariants); these guards are the
    // floor every caller gets.
    const pluralBlocked = /(nce|rce)$/.test(t)
      || STOPWORDS.has(t)
      || EXPANSION_FRAMING_WORDS.has(t)
      || CENTRAL_TERM_CLOSED_CLASS.has(t)
      // WAVE EIGHT (2026-10-14, Job 3a): the closed class list
      // is the full gate function predicate now — "while" passed
      // every list above and grew "whiles".
      || GATE_FUNCTION_WORDS.has(t);
    if (!pluralBlocked) {
      const consonantY = t.endsWith("y") && !/[aeiou]y$/.test(t);
      // Plural formation, same guard: a sibilant final (s, x, z, ch,
      // sh) takes ONLY the "es" plural. The old code added the bare
      // +"s" form as well, which is how "fix" grew the non word
      // "fixs" beside the real "fixes" — and a fallback group
      // carrying a non word bridges nothing.
      if (consonantY) out.add(t.slice(0, -1) + "ies");
      else if (/(s|x|z|ch|sh)$/.test(t)) out.add(t + "es");
      else out.add(t + "s");
    }
  }
  // Verb forms: "sleeping" and "slept" questions against a table
  // that carries "sleep". The stripped base is the variant (plus
  // its undoubled form for running -> run); no e restoration is
  // attempted, so make/making stays unmatched rather than risk a
  // junk reconstruction.
  if (t.endsWith("ing") && t.length > 5) {
    const b = t.slice(0, -3);
    out.add(b);
    if (b.length > 1 && b[b.length - 1] === b[b.length - 2]) out.add(b.slice(0, -1));
  } else if (t.endsWith("ed") && t.length > 4) {
    const b = t.slice(0, -2);
    out.add(b);
    if (b.length > 1 && b[b.length - 1] === b[b.length - 2]) out.add(b.slice(0, -1));
  }
  out.delete(t);
  return out;
}

// True when two single words are inflection forms of one another.
function sameInflection(a, b) {
  if (a === b) return true;
  return inflectionVariants(a).has(b) || inflectionVariants(b).has(a);
}

// KEYWORD PLAIN TERMS (2026-10-15, wave seventeen, citation
// depth diagnosis, stage 4). The terms a rung sends to the
// PLAIN keyword engines (the engines that receive a bare word
// string with no boolean structure to constrain it). Two rules:
//   . A term with a bridged concept group — the static table's
//     group or the model's, or a synonyms entry — is replaced
//     by the group's alternates (up to four, phrases and real
//     alternates first class, morphological variants and
//     closed class words dropped) INSTEAD of the bare term.
//     The bare collision token is what the plain engines
//     tokenize worst: "puff" alone pulled petroleum "huff and
//     puff" papers on the diagnosis's parent run because
//     nothing in the string told the engine which puff was
//     meant, while the bridged words (swelling, edema) name
//     the body's vocabulary directly.
//   . Closed class words never appear as rung terms at all.
// The bare term stays inside the boolean group, where the
// other groups constrain it — a static bridge that is wrong in
// another domain (puff pastry, an aerosol puff) costs the
// boolean nothing and the plain rungs only their unconstrained
// string. Terms with no bridge pass through untouched, and a
// multi word term (a constraint phrase, a quoted organism)
// passes through untouched.
export function keywordPlainTerms(terms, dynLookup) {
  const out = [];
  for (const raw of Array.isArray(terms) ? terms : []) {
    const t = String(raw || "");
    if (!t) continue;
    const key = t.toLowerCase();
    if (t.includes('"') || /\s/.test(key)) { out.push(t); continue; }
    if (isGateFunctionWord(key)) continue;
    let set = null;
    try { set = conceptSetFor(key, dynLookup); } catch { set = null; }
    if (!set) {
      const syns = SYNONYMS[key];
      if (Array.isArray(syns) && syns.length > 0) {
        set = new Set([key, ...syns.map((s) => String(s).toLowerCase())]);
      }
    }
    if (set) {
      const alts = [...set]
        .map((m) => String(m).toLowerCase())
        .filter((m) => m && m !== key)
        .filter((m) => m.indexOf(" ") !== -1 || !isGateFunctionWord(m))
        .filter((m) => m.indexOf(" ") !== -1 || !sameInflection(key, m));
      if (alts.length > 0) { out.push(...alts.slice(0, 4)); continue; }
    }
    out.push(t);
  }
  return out;
}

// Plausible NOUN forms of a single word, for GENERATION (the
// fallback builder's alternates become database query terms and
// feed user facing reformulations, so a generated non word is a
// shipped defect, not a private approximation). Two halves:
//   . Singular recovery is always plausible: a question word in
//     plural form ("cultures", "flies") has a singular the
//     literature indexes ("culture", "fly"), recovered with the
//     same guards as inflectionVariants' strips.
//   . A plural is generated ONLY through pluralFormOf, and the
//     caller adds it only for a term that appears as a concept
//     group head or inside one of the question's key phrases —
//     a term the question is demonstrably ABOUT. The bare verb
//     inflection path is dropped entirely: no ing or ed forms
//     are generated, so a verb or adjective the tokenizer
//     uncovered ("loose", "runny", "alive", "thaw") can no
//     longer grow "looses", "runnies", "alives", or "thaws".
// Stemming and the full inflection family stay where they
// belong: internal matching (sameInflection, the scorer's
// matcher), never generation.
export function nounFormVariants(term) {
  const t = String(term || "").toLowerCase().trim();
  const out = new Set();
  if (!t || /\s/.test(t)) return out;
  if (t.endsWith("ies") && t.length > 3) out.add(t.slice(0, -3) + "y");
  else if (t.endsWith("es") && t.length > 3) out.add(t.slice(0, -2));
  else if (t.endsWith("s") && t.length > 3 && !/(us|is|ss)$/.test(t)) out.add(t.slice(0, -1));
  out.delete(t);
  return out;
}

// The plural of a noun, or null when no plausible plural exists:
// closed class and framing words never pluralize, and neither do
// words ending in nce or rce (see inflectionVariants).
const PLURAL_NUMBER_WORDS = new Set([
  "one", "two", "three", "four", "five", "six", "seven", "eight",
  "nine", "ten", "eleven", "twelve", "dozen", "hundred", "thousand",
]);
export function pluralFormOf(term) {
  const t = String(term || "").toLowerCase().trim();
  if (!t || /\s/.test(t) || t.endsWith("s")) return null;
  if (/(nce|rce)$/.test(t)) return null;
  // An ing form is a gerund or participle, not a countable noun
  // head: "drinkings" is not a word this generator may mint.
  if (t.endsWith("ing")) return null;
  // Number words are quantifiers, not nouns ("sixes" was one of
  // the panel's specimen non words in context).
  if (PLURAL_NUMBER_WORDS.has(t)) return null;
  if (STOPWORDS.has(t) || EXPANSION_FRAMING_WORDS.has(t) || CENTRAL_TERM_CLOSED_CLASS.has(t)) return null;
  // WAVE EIGHT (2026-10-14, Job 3a): "whiles" — the full gate
  // function predicate bars the rest of the closed class.
  if (GATE_FUNCTION_WORDS.has(t)) return null;
  if (t.endsWith("y") && !/[aeiou]y$/.test(t)) return t.slice(0, -1) + "ies";
  if (/(s|x|z|ch|sh)$/.test(t)) return t + "es";
  return t + "s";
}

export function buildDeterministicFallbackGroups(query, uncoveredTerms, opts = {}) {
  const q = String(query || "").toLowerCase().replace(/\s+/g, " ");
  const out = [];
  const seenTerms = new Set();
  // Group budget for this build (2026-10-22, L1-11). The default
  // stays at the historic cap of 4, so every existing caller gets
  // exactly the groups it got before. The coverage computation
  // (resolveExpansionCoverage) passes a larger total budget when
  // it asks for the concepts the model and the validator caps
  // left past position 4, so a tail concept can still be
  // represented as a plain term group instead of vanishing.
  const groupLimit = opts && Number.isFinite(opts.limit) && opts.limit >= 0
    ? Math.floor(opts.limit) : 4;
  // The HEAD words of the question's own key phrases
  // (analyzeQuery): the last word of each key phrase, plus any
  // single word key phrase whole. A generated plural is allowed
  // only for a term in this set (or a concept group head — the
  // builder skips those above, so in practice this set is the
  // permission): the head slot of a noun phrase is where the
  // phrase's noun sits, while an adjective or adverb that
  // merely rides inside a phrase ("runny" in "runny nose",
  // "loose" in "loose skin") is not a noun and must not grow a
  // plural. Computed once per build.
  const fallbackKeyPhraseHeads = new Set();
  try {
    const analysis = analyzeQuery(query);
    for (const kp of (analysis && analysis.keyPhrases) || []) {
      const words = String(kp).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
      if (words.length === 1) fallbackKeyPhraseHeads.add(words[0]);
      else if (words.length > 1) fallbackKeyPhraseHeads.add(words[words.length - 1]);
    }
  } catch { /* key phrases are a permission, not a requirement */ }
  const cleanPiece = (s) => String(s || "").toLowerCase().trim().replace(/\s+/g, " ");
  // Same wording rule as the validator (2026-10-22, L1-2): a
  // digit bearing term such as a dose phrase is a real fallback
  // target, not junk to be skipped for its alphabet.
  const isCleanWording = isAcceptableExpansionWording;
  for (const rawTerm of Array.isArray(uncoveredTerms) ? uncoveredTerms : []) {
    if (out.length >= groupLimit) break;
    const term = cleanPiece(rawTerm);
    if (!term || seenTerms.has(term)) continue;
    if (term.split(" ").length > 4 || !isCleanWording(term)) continue;
    if (EXPANSION_FRAMING_WORDS.has(term) || hasNegationLead(term)) continue;
    // A term the hand table already covers needs no fallback.
    if (CONCEPT_LOOKUP.has(term)) continue;
    const alts = new Set();
    const addAlt = (a) => {
      const alt = cleanPiece(a);
      if (!alt || alt === term) return;
      if (alt.split(" ").length > 4 || !isCleanWording(alt)) return;
      if (EXPANSION_FRAMING_WORDS.has(alt)) return;
      alts.add(alt);
    };
    // 1. A curated concept group the term inflects into, whole.
    for (const set of new Set(CONCEPT_LOOKUP.values())) {
      let attach = false;
      for (const member of set) {
        if (member.indexOf(" ") === -1 && sameInflection(member, term)) { attach = true; break; }
      }
      if (attach) for (const member of set) addAlt(member);
    }
    // 2. The synonyms table, both directions, plus the multi word
    // keys the question itself speaks that contain the term.
    for (const [key, values] of Object.entries(SYNONYMS)) {
      if (!Array.isArray(values)) continue;
      // Forward: the term IS a key (the wave six bridges land
      // here: yogurt, caffeine, blood pressure). The handler's
      // uncovered computation normally keeps keyed terms out of
      // this builder, but the table's promise is both directions
      // and other consumers ask the builder directly.
      if (key === term) for (const v of values) addAlt(v);
      const keyNamesTerm = values.some((v) => {
        const vl = cleanPiece(v);
        return vl === term || (vl.indexOf(" ") === -1 && sameInflection(vl, term));
      });
      if (keyNamesTerm) {
        addAlt(key);
        for (const v of values) addAlt(v);
      }
      if (key.indexOf(" ") !== -1) {
        // Possessive folded matching (2026-10-14, wave eight
        // round three): the question this builder receives on
        // the live path is the pipeline's surface form, whose
        // tokenizer has already split "swimmer's" into
        // "swimmer" plus a dropped "s", so a bridged key that
        // carries an apostrophe ("swimmer's ear") can never be
        // found in it verbatim — the lay to clinical bridge
        // silently never fired for the handler's own groups
        // even though it fired for the raw string. Both sides
        // are compared with possessives folded away, the same
        // form the tokenizer produces.
        const foldPossessive = (s) => s.replace(/['’]s\b/g, "").replace(/['’]/g, "");
        if (foldPossessive(q).includes(foldPossessive(key))) {
          const words = foldPossessive(key).split(" ");
          if (words.includes(term)) for (const v of values) addAlt(v);
        }
      }
    }
    // 3. The term's own noun forms: the floor that keeps the
    // group a real membership test even when no table knows the
    // term at all (a substance nobody has curated yet). Wave
    // seven plausibility: singular recovery always; a plural
    // only when the term heads one of the question's key
    // phrases (fallbackKeyPhraseHeads) and pluralFormOf's
    // morphological rules allow it; verb forms never (see
    // nounFormVariants). The panel's specimens — since, loose,
    // ever, runny, alive, thaw — produce no alternates here.
    for (const v of nounFormVariants(term)) addAlt(v);
    if (fallbackKeyPhraseHeads.has(term)) {
      const pl = pluralFormOf(term);
      if (pl) addAlt(pl);
    }
    // A group with no alternates still ships (wave seven): the
    // lookup set carries the term itself, so the group remains
    // a real membership test for the gate — what it no longer
    // carries is a manufactured inflection alternate. (Before
    // this wave the builder dropped such groups, which is part
    // of why it manufactured plurals for everything instead.)
    seenTerms.add(term);
    out.push({ term, alternates: [...alts].slice(0, 6) });
  }
  return out;
}

/* ── Expansion coverage as a computed state (2026-10-22, L1-1) ──
 * Before this wave, coverage was a side effect of the model call:
 * if the model returned any groups at all, the question counted
 * as covered and the deterministic fallback ran only when it
 * returned none, so a partial thesaurus result silently certified
 * full coverage. The functions below make coverage a computed
 * state instead. The question's central concepts are derived
 * first, from the machinery the codebase already trusts for that
 * job (questionCentralConcepts for the subject and lead phrase
 * concepts, centralContentTerms for the specific content words,
 * and the gate's own quantity phrase predicate for dose and
 * duration phrases). Each concept is then marked covered or
 * uncovered after every expansion source, in source order: the
 * hand written concept table, the synonyms table, the groups a
 * caller supplies (the model's, tagged by their via), and finally
 * the deterministic fallback, which resolveExpansionCoverage
 * runs per uncovered concept, not per empty result. Whatever is
 * still uncovered after the last source is a decided state, not
 * an absence: it is returned in the coverage object, carried on
 * the gather diag as diag.expansionCoverage, and surfaced in the
 * search record (buildSearchRecord) and the response _expansion
 * field, so a reader can see exactly which concepts no source
 * covered. Quantity and duration concepts are tracked here even
 * though they never gate (the 2026-10-21 diagnosis fix stands):
 * coverage is about what was searched as a concept, and a dose
 * the question states must be decided here, covered by a fallback
 * group or recorded uncovered, never silently absent. */

// Total group budget across every expansion source for one
// question (2026-10-22, L1-11). The per source caps stand (the
// validator and a default fallback build still stop at 4), but a
// question with more central concepts than one source may hold
// gets its tail concepts represented as plain term groups inside
// this total, and only concepts past this total are cut, with
// the cut recorded in the coverage object.
export const EXPANSION_TOTAL_GROUP_BUDGET = 8;

const EXPANSION_NUMBER_WORD_VALUES = {
  one: "1", two: "2", three: "3", four: "4", five: "5", six: "6",
  seven: "7", eight: "8", nine: "9", ten: "10", eleven: "11",
  twelve: "12", thirteen: "13", fourteen: "14", fifteen: "15",
  sixteen: "16", seventeen: "17", eighteen: "18", nineteen: "19",
  twenty: "20", dozen: "12",
};

// Matching key for a concept, a group term, or an alternate:
// number words become digits and time units become singular, so
// "six hours", "6 hours" and "6 hour" are one key. Matching only;
// nothing generated ever uses this form.
function normalizeConceptKey(term) {
  const toks = String(term || "").toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  return toks.map((tok) => {
    if (EXPANSION_NUMBER_WORD_VALUES[tok]) return EXPANSION_NUMBER_WORD_VALUES[tok];
    if (tok.endsWith("s") && GATE_TIME_UNIT_TOKENS.has(tok)) return tok.slice(0, -1);
    return tok;
  }).join(" ");
}

// True when one group (its term or any alternate) names the
// concept: an exact normalized match, a phrase that contains
// every token of a phrase concept, a single word concept riding
// inside a phrase candidate ("thinking" inside the model's
// "worse thinking"), or a single word inflection of the concept.
function expansionGroupCoversConcept(conceptTerm, group) {
  if (!group) return false;
  const ck = normalizeConceptKey(conceptTerm);
  if (!ck) return false;
  const cToks = ck.split(" ").filter(Boolean);
  const candidates = [];
  if (typeof group.term === "string") candidates.push(group.term);
  if (Array.isArray(group.alternates)) candidates.push(...group.alternates);
  // A hand group arrives as a bare Set of members; its members
  // are the candidates and there is no separate term.
  if (group instanceof Set) candidates.push(...group);
  for (const cand of candidates) {
    if (typeof cand !== "string") continue;
    const nk = normalizeConceptKey(cand);
    if (!nk) continue;
    if (nk === ck) return true;
    const nToks = nk.split(" ").filter(Boolean);
    if (cToks.length === 1) {
      if (nToks.includes(ck)) return true;
      if (nToks.length === 1 && sameInflection(nToks[0], ck)) return true;
    } else if (cToks.every((t) => nToks.includes(t))) {
      return true;
    }
  }
  return false;
}

// True when the hand written tables already cover the concept:
// a concept table key (exact or by inflection), a synonyms entry,
// or membership of one of the question's resolved hand groups.
function expansionHandCoversConcept(query, conceptTerm) {
  const ct = String(conceptTerm || "").toLowerCase().trim();
  if (!ct) return false;
  if (CONCEPT_LOOKUP.has(ct)) return true;
  if (SYNONYMS[ct]) return true;
  if (!ct.includes(" ")) {
    for (const key of CONCEPT_LOOKUP.keys()) {
      if (!key.includes(" ") && sameInflection(key, ct)) return true;
    }
    for (const key of Object.keys(SYNONYMS)) {
      if (!key.includes(" ") && sameInflection(key, ct)) return true;
    }
  }
  try {
    for (const set of questionConceptGroups(query, null)) {
      if (expansionGroupCoversConcept(ct, set)) return true;
    }
  } catch { /* hand groups are one source, not a requirement */ }
  return false;
}

// The question's central concepts for coverage, derived from the
// existing ranked and central term machinery (see the header):
// quantity phrases first (their number and unit words are
// constituents of the dose or duration, not separate concepts),
// then the central concepts questionCentralConcepts resolves,
// then the remaining central content terms. Filler words the
// filler set names (comparatives such as "worse", light verbs,
// pronouns) are never concepts on their own; the outcome word
// they modify ("thinking") still is, through centralContentTerms.
// Returns [{ term, quantity }] in derivation order.
export function expansionCentralConcepts(query) {
  const q = String(query || "");
  const out = [];
  const seenKeys = new Set();
  const constituents = new Set();
  const push = (rawTerm, quantity) => {
    const term = String(rawTerm || "").toLowerCase().trim().replace(/\s+/g, " ");
    if (!term) return;
    const key = normalizeConceptKey(term);
    if (!key || seenKeys.has(key)) return;
    if (!term.includes(" ")) {
      if (constituents.has(term)) return;
      try { if (isGateFunctionWord(term)) return; } catch { /* keep the term */ }
      if (QUERY_FILLER_WORDS.has(term)) return;
      if (EXPANSION_FRAMING_WORDS.has(term)) return;
    }
    seenKeys.add(key);
    out.push({ term, quantity: !!quantity });
  };
  // Quantity phrases: a number word or digit directly beside a
  // time unit, read off the question's own tokens. The unit set
  // and the quantity predicate are the gate's (GATE_TIME_UNIT_TOKENS
  // and isQuantityPhraseKey are read at call time).
  try {
    const toks = q.toLowerCase().replace(/[^\w\s-]/g, " ").split(/[\s-]+/).filter(Boolean);
    for (let i = 0; i < toks.length; i++) {
      const tok = toks[i];
      const singular = tok.endsWith("s") ? tok.slice(0, -1) : tok;
      const isUnit = GATE_TIME_UNIT_TOKENS.has(tok) || GATE_TIME_UNIT_TOKENS.has(singular + "s");
      if (!isUnit) continue;
      const prev = toks[i - 1];
      if (prev && (EXPANSION_NUMBER_WORD_VALUES[prev] || /^\d+$/.test(prev))) {
        push(prev + " " + tok, true);
        constituents.add(prev);
        constituents.add(tok);
      }
    }
  } catch { /* quantity phrases are an addition, not a requirement */ }
  try {
    for (const c of questionCentralConcepts(q, null)) {
      if (c && c.term) push(c.term, isQuantityConstraintTerm(c.term));
    }
  } catch { /* central concepts fall back to content terms below */ }
  try {
    for (const t of centralContentTerms(q)) push(t, false);
  } catch { /* no content terms, no further concepts */ }
  return out;
}

// Coverage of a set of supplied groups against the question's
// central concepts. `central` may be passed to reuse one
// derivation; otherwise it is derived here. Each supplied group
// may carry a `source` tag (or the array a `via` tag, the shape
// llmConceptGroups returns); the covering source is reported per
// concept as hand, synonyms, the group's source, or the array
// via, defaulting to model for untagged supplied groups.
// Returns { central, covered, uncovered, cut } where covered is
// [{ term, via }], uncovered is the list of concept terms no
// source covered, and cut is that same uncovered list when the
// supplied groups already fill the total budget (the concepts
// were cut by a cap, not merely missed), else empty.
export function computeExpansionCoverage(query, groups, central) {
  const concepts = Array.isArray(central) && central.length > 0
    ? central : expansionCentralConcepts(query);
  const groupList = Array.isArray(groups) ? groups : [];
  const arrayVia = (groups && groups.via) || null;
  const covered = [];
  const uncovered = [];
  for (const c of concepts) {
    const term = typeof c === "string" ? c : c && c.term;
    if (!term) continue;
    let via = null;
    try {
      if (CONCEPT_LOOKUP.has(String(term).toLowerCase())) via = "hand";
      else if (SYNONYMS[String(term).toLowerCase()]) via = "synonyms";
      else if (expansionHandCoversConcept(query, term)) via = "hand";
    } catch { via = null; }
    if (!via) {
      for (const g of groupList) {
        if (expansionGroupCoversConcept(term, g)) {
          via = (g && g.source) || arrayVia || "model";
          if (via !== "fallback" && via !== "plain") via = "model";
          break;
        }
      }
    }
    if (via) covered.push({ term, via });
    else uncovered.push(term);
  }
  const centralTerms = concepts
    .map((c) => (typeof c === "string" ? c : c && c.term))
    .filter(Boolean);
  return {
    central: centralTerms,
    covered,
    uncovered,
    cut: groupList.length >= EXPANSION_TOTAL_GROUP_BUDGET ? [...uncovered] : [],
  };
}

// ── Coverage scored by retrievability (2026-10-23, logic
// audit L1-10) ───────────────────────────────────────────────
// Key presence used to settle coverage: if the hand tables
// contained a term, its vocabulary problem counted as solved,
// and the model trigger never proposed a bridge for it. But a
// group can be present and still unable to retrieve the field
// for this question's shape: the sleep group stood for years
// with no restriction or outcome vocabulary in it, while
// "sleep" being covered was the reason no bridge was ever
// requested on its behalf. Adequacy is scored per question
// shape instead. A measurement question needs method vocabulary
// in the group (assay, determination, spectrophotometric, and
// kin). An outcome question (the question states an outcome or
// a comparison of outcomes) needs outcome or study design
// vocabulary (restriction, deprivation, vigilance, closure,
// mortality, and kin). A question with neither shape asks
// nothing of a group beyond existing. A central term whose
// group fails its shape's test is inadequate: expansion may
// SUPPLEMENT that group, not only originate groups for terms
// nobody has tabled.
const EXPANSION_METHOD_VOCAB = new Set([
  "assay", "assays", "determination", "measurement", "measuring",
  "quantification", "spectrophotometric", "spectrophotometry",
  "colorimetric", "absorbance", "protocol", "method", "methods",
]);
const EXPANSION_OUTCOME_VOCAB = new Set([
  "restriction", "deprivation", "loss", "vigilance", "lapses",
  "closure", "mortality", "survival", "impairment", "decline",
  "performance", "deficit", "deficits", "outcome", "outcomes",
]);
function groupMembersContainVocab(members, vocab) {
  for (const m of members || []) {
    for (const tok of String(m || "").toLowerCase().split(/[^a-z0-9]+/)) {
      if (vocab.has(tok)) return true;
    }
  }
  return false;
}

export function expansionGroupAdequacy(term, query, members) {
  const t = String(term || "").toLowerCase().trim();
  let group = members || null;
  if (!group) {
    try { group = conceptSetFor(t, null); } catch { group = null; }
    if (!group && SYNONYMS[t]) group = new Set([t, ...SYNONYMS[t]]);
  }
  if (!group) return { covered: false, adequate: false, missing: ["group"] };
  const list = [...group];
  const missing = [];
  if (detectMeasurementIntent(query) && !groupMembersContainVocab(list, EXPANSION_METHOD_VOCAB)) {
    missing.push("method vocabulary");
  }
  const q = String(query || "").toLowerCase();
  const outcomeShaped = /\b(?:worse|better|improve|improves|improved|decline|impair|affect|effect|effects|outcome|happen|happens|change|changes)\b/.test(q);
  if (outcomeShaped && !groupMembersContainVocab(list, EXPANSION_OUTCOME_VOCAB)) {
    missing.push("outcome or study design vocabulary");
  }
  return { covered: true, adequate: missing.length === 0, missing };
}

export function isExpansionGroupInadequate(term, query) {
  const a = expansionGroupAdequacy(term, query, null);
  return a.covered && !a.adequate;
}

// Decide coverage concept by concept (2026-10-22, L1-1 and
// L1-11). Takes the groups one source already produced (in
// gatherPapers, the model's validated groups, possibly none),
// computes which central concepts they leave uncovered, and runs
// the deterministic fallback for exactly those concepts, within
// the total group budget. A concept the fallback builder cannot
// group (a hand table term it skips, a phrase it refuses) is
// still represented as a plain term group while budget remains:
// the lookup set carries the term itself, so the concept reaches
// the retrieval consumers as a plain term. Concepts past the
// total budget stay uncovered and are recorded as cut.
// Returns { groups, fallbackGroups, coverage }: groups is the
// merged clean list ({ term, alternates } only, the shape every
// existing consumer takes), fallbackGroups the clean groups the
// fallback and plain representation added, and coverage the
// final computed state from computeExpansionCoverage, whose
// uncovered and cut lists the caller records on the diag.
export function resolveExpansionCoverage(query, proposedGroups, opts = {}) {
  const totalBudget = opts && Number.isFinite(opts.totalBudget) && opts.totalBudget > 0
    ? Math.floor(opts.totalBudget) : EXPANSION_TOTAL_GROUP_BUDGET;
  const baseVia = (proposedGroups && proposedGroups.via) || "model";
  const base = [];
  const seenBase = new Set();
  for (const g of Array.isArray(proposedGroups) ? proposedGroups : []) {
    if (!g || typeof g.term !== "string" || !Array.isArray(g.alternates)) continue;
    const term = g.term.toLowerCase().trim();
    if (!term || seenBase.has(term)) continue;
    seenBase.add(term);
    base.push({
      term,
      alternates: g.alternates.map((a) => String(a || "").toLowerCase()).filter(Boolean),
      ...(g.classes ? { classes: g.classes } : {}),
      source: baseVia === "fallback" ? "fallback" : "model",
    });
  }
  const central = expansionCentralConcepts(query);
  const before = computeExpansionCoverage(query, base, central);
  const added = [];
  if (before.uncovered.length > 0) {
    const room = Math.max(0, totalBudget - base.length);
    if (room > 0) {
      let rawFallback = [];
      try {
        rawFallback = buildDeterministicFallbackGroups(query, before.uncovered, { limit: room });
      } catch { rawFallback = []; }
      const have = new Set(base.map((g) => normalizeConceptKey(g.term)));
      for (const g of rawFallback) {
        if (added.length >= room) break;
        const key = normalizeConceptKey(g.term);
        if (!key || have.has(key)) continue;
        have.add(key);
        added.push({ term: g.term, alternates: g.alternates || [], source: "fallback" });
      }
      // Plain term representation for uncovered concepts the
      // fallback builder emitted nothing for, while budget
      // remains (L1-11: a tail concept is at least a plain term
      // in the lookup, or it is recorded, never just dropped).
      for (const term of before.uncovered) {
        if (added.length >= room) break;
        const key = normalizeConceptKey(term);
        if (!key || have.has(key)) continue;
        if (!isAcceptableExpansionWording(term)) continue;
        if (EXPANSION_FRAMING_WORDS.has(term) || hasNegationLead(term)) continue;
        try { if (term.split(" ").every((w) => isGateFunctionWord(w))) continue; } catch { /* keep */ }
        have.add(key);
        added.push({ term, alternates: [], source: "plain" });
      }
    }
  }
  const tagged = [...base, ...added];
  const coverage = computeExpansionCoverage(query, tagged, central);
  // Any concept still uncovered after every source ran while the
  // merged groups fill the total budget was cut by the budget;
  // when budget remained, an uncovered concept is a coverage
  // failure of every source, which is also an explicit
  // limitation. Either way the final uncovered list is the
  // recorded limitation, so cut mirrors it whenever it is
  // non empty and at least one source produced groups or the
  // budget was reached. An entirely group less run keeps cut
  // empty and lets uncovered speak for itself.
  if (coverage.uncovered.length > 0 && (tagged.length > 0)) {
    coverage.cut = [...coverage.uncovered];
  }
  // Labeled alternate classes ride through (2026-10-23, L1-9):
  // the coverage merge must not strip the labels the validator
  // kept, or the record loses which alternates were outcome
  // measures, instruments, or study design vocabulary.
  const clean = (g) => (g && g.classes
    ? { term: g.term, alternates: g.alternates, classes: g.classes }
    : { term: g.term, alternates: g.alternates });
  return {
    groups: tagged.map(clean),
    fallbackGroups: added.map(clean),
    coverage,
  };
}

/* clampStageLegTimeout: the synthesis stage's clampLegTimeout
 * treatment, generalized for the two sequential two leg stages
 * (expansion and validation). Each leg's timeout is clamped against
 * the stage's REMAINING budget, holding back a reserve for every leg
 * still to come plus a small final reserve, so a hung first leg can
 * no longer consume the whole stage and starve the second leg of its
 * shot. Pure arithmetic (callers pass the clock readings), exported
 * for tests. The floor keeps a leg's allowance from going negative
 * or zero when the stage is already over budget; the stage backstop
 * (the caller's own race) still bounds the total. */
export function clampStageLegTimeout({ startedAt, now, budgetMs, wantMs, legsAfter = 0, reservePerLegMs = 1750, finalReserveMs = 250, floorMs = 500 }) {
  const remaining = budgetMs - (now - startedAt);
  const reserve = Math.max(0, legsAfter) * reservePerLegMs + finalReserveMs;
  return Math.max(floorMs, Math.min(wantMs, remaining - reserve));
}

// The model call behind llmConceptGroups, following the same pattern
// as llmGenerateSearchQueries / selfReason: a small fast model, a
// whole-operation AbortController timeout armed through the body
// read, strict JSON out. Returns the raw reply text (or null);
// validation happens in llmConceptGroups.
//
// Two legs, tried in order. The first is the OR_VALIDATE model on
// OpenRouter, whose free pool has a daily cap; on the day that cap is
// hit, EVERY expansion would silently fail open and the feature would
// look broken in exactly the conditions where the fleet is already
// limping. The second leg is Groq's small gpt-oss-20b (the same model
// the synthesis wave 2 roster uses), so the expansion does not depend
// on a single capped pool. diag.llmExpandedVia records which leg
// answered, so a live check can prove the mechanism ran.
/* AUXILIARY STAGE LEG HEALTH (2026-10-14, wave ten, item 15):
 * the expansion and validation stages fire some of the same
 * models the synthesis waves race (the gemma validation model
 * is also the fastpath lead), but only the race path read or
 * wrote the leg health store — so an expansion leg could prove
 * a model daily capped at minute one and the synthesis fastpath
 * would still lead with it at minute two and take the same 429
 * (measured live on the wave nine CRISPR probe, in a single
 * request). These helpers give the auxiliary legs the same
 * labels the race uses, so park checks and outcome records are
 * shared in both directions. Skipped legs cost nothing and the
 * stages fail open exactly as before. */
export function auxLegHealthLabel(leg) {
  if (!leg || !leg.model) return null;
  if (leg.cf) return leg.model;
  if (leg.via === "groq") return "groq:" + leg.model;
  if (leg.via === "gemini") return "gemini:" + leg.model;
  if (leg.via === "workers-ai") return leg.model;
  return leg.model;
}
export function auxLegParked(leg) {
  const label = auxLegHealthLabel(leg);
  if (!label) return false;
  // Only LONG parks skip an auxiliary leg: a daily cap or a
  // provider restriction is the failure that will still be true
  // when synthesis runs seconds later, and it is the measured
  // harm (an auxiliary leg proves the cap, synthesis leads with
  // the capped model anyway). A 60 second rate limit cooldown
  // or a timeout park is the race path's concern; the auxiliary
  // stages are sequential and already fall through a sick leg
  // on their own, and skipping on short parks would let one
  // stage's transient failure starve the other's first leg.
  const park = legParkInfo(label) || bucketParkInfo(label);
  return !!(park && (park.parkClass === "daily-cap" || park.parkClass === "model-restricted"));
}
async function auxLegHttpError(leg, r) {
  let body = "";
  try { if (r && typeof r.text === "function") body = String(await r.text()).slice(0, 200); } catch { /* body is diagnostic only */ }
  return new Error(String(leg && leg.model || "leg") + ": HTTP " + (r ? r.status : "?") + " . " + body);
}

export async function defaultConceptGroupCall(query, env, timing, ledger = null) {
  // Stage budget: llmConceptGroups races this whole call against
  // 6500ms. Legs are clamped against that remaining budget (see
  // clampStageLegTimeout): a hung OpenRouter leg used to hold its
  // full 6000ms abort and leave the Groq leg 500ms before the race
  // discarded its answer. `timing` lets tests scale the stage down;
  // production uses the defaults.
  const stageBudgetMs = (timing && timing.budgetMs) || 6500;
  const legWantMs = (timing && timing.wantMs) || 6000;
  const stageStartedAt = Date.now();
  const messages = [
    {
      role: "system",
      content:
        "You are a scientific literature search specialist. A researcher's question sometimes words a concept differently from the papers that answer it: the question says one thing, the literature says the same thing in its standard technical wording. Your job is to propose alternate wording ONLY for concepts already present in the question.\n" +
        "Rules:\n" +
        "- Alternates must be synonyms or the standard wording the literature uses for the SAME thing, in the SAME sense the question uses: method preparations, technical terms, species names. A word with several senses (fine, grow, cold) takes the sense the question's other concepts fix, never another sense of the same spelling.\n" +
        "- The bridge is not always a synonym. When the literature measures the concept's outcome, names an instrument for it, or studies it under a standard design, add those forms in the separate labeled lists outcomeMeasures, instruments, and studyDesign instead of calling them synonyms.\n" +
        "- Never drop a constraint of the question.\n" +
        "- Never introduce a new topic or organism that the question does not name. A method may be named only in the instruments list, and only when the question asks how something is measured or tested.\n" +
        "- Only include a concept when a wording mismatch is plausible. If the question already uses the literature's wording, return an empty array.\n" +
        "- Output ONLY a JSON array of objects shaped {\"term\": \"wording from the question, lowercased\", \"alternates\": [\"alternate wording\", \"...\"], \"outcomeMeasures\": [\"...\"], \"instruments\": [\"...\"], \"studyDesign\": [\"...\"]} with 2 to 6 alternates per term and at most 4 terms. The three labeled lists are optional. No markdown, no explanation.",
    },
    { role: "user", content: String(query || "") },
  ];
  const legs = [];
  const orToken = env ? openRouterKey(env) : "";
  if (orToken) legs.push({
    via: "openrouter",
    url: "https://openrouter.ai/api/v1/chat/completions",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + orToken,
      "HTTP-Referer": "https://askcerebrum.org",
      "X-Title": "Cerebrum",
    },
    model: OR_VALIDATE,
  });
  const groqKey = env ? (env.GROQ_KEY || env.GROQ_API_KEY || "") : "";
  if (groqKey) legs.push({
    via: "groq",
    url: "https://api.groq.com/openai/v1/chat/completions",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + groqKey,
    },
    model: "openai/gpt-oss-20b",
  });
  for (let li = 0; li < legs.length; li++) {
    const leg = legs[li];
    // Wave ten (item 15): a leg the shared health store has
    // parked (its own park, or its shared bucket's) is skipped,
    // not fired into a known cap.
    if (auxLegParked(leg)) continue;
    // Subrequest budget: a leg that cannot be afforded is not fired
    // at all . the stage fails open exactly as if the leg had errored,
    // and the caller records the budget as the reason.
    if (ledger && ledger.remaining() <= 0) return null;
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), clampStageLegTimeout({
      startedAt: stageStartedAt, now: Date.now(), budgetMs: stageBudgetMs,
      wantMs: legWantMs, legsAfter: legs.length - li - 1,
      ...(timing && timing.reservePerLegMs != null ? { reservePerLegMs: timing.reservePerLegMs } : {}),
      ...(timing && timing.finalReserveMs != null ? { finalReserveMs: timing.finalReserveMs } : {}),
      ...(timing && timing.floorMs != null ? { floorMs: timing.floorMs } : {}),
    }));
    try {
      if (ledger) ledger.spend();
      const r = await fetch(leg.url, {
        method: "POST",
        headers: leg.headers,
        body: JSON.stringify({
          model: leg.model,
          temperature: 0.1,
          max_tokens: 600,
          ...(leg.via === "groq" ? { reasoning_effort: "low" } : {}),
          messages,
        }),
        signal: c.signal,
      });
      if (!r.ok) {
        recordLegOutcome(auxLegHealthLabel(leg), false, await auxLegHttpError(leg, r));
        continue;
      }
      const j = await r.json();
      const text = (j?.choices?.[0]?.message?.content || "").trim();
      if (text) {
        recordLegOutcome(auxLegHealthLabel(leg), true);
        return { text, via: leg.via };
      }
    } catch (e) {
      recordLegOutcome(auxLegHealthLabel(leg), false, e);
      // fall through to the next leg
    } finally {
      clearTimeout(t);
    }
  }
  return null;
}

// Ask the model for concept groups covering this question's wording,
// then pass whatever it said through the strict validator. callImpl is
// injectable for tests; it receives (query, env) and may return the
// reply as raw text or an already-parsed value. Fails open to [] on
// any error, timeout, or rate limit. Never throws.
export async function llmConceptGroups(query, env, callImpl, ledger = null) {
  let timer = null;
  try {
    const doCall = typeof callImpl === "function" ? callImpl : defaultConceptGroupCall;
    const timeout = new Promise((resolve) => {
      timer = setTimeout(() => resolve(null), 6500);
    });
    const raw = await Promise.race([
      Promise.resolve().then(() => doCall(query, env, undefined, ledger)),
      timeout,
    ]);
    if (raw == null) return [];
    // The default call reports which leg answered as { text, via };
    // injected calls may return raw text or a parsed value instead.
    const isLegResult = raw && typeof raw === "object" && !Array.isArray(raw) && typeof raw.text === "string";
    const groups = validateExpansionGroups(isLegResult ? raw.text : raw, query);
    if (groups.length && isLegResult && raw.via) {
      groups.via = raw.via;
      // Per group provenance (2026-10-23, L3-13): the array
      // level via is lost when a caller spreads the groups
      // into a new array, so each group carries the mark too,
      // and buildDynLookup honors either.
      for (const g of groups) { try { g._liveModel = true; } catch { /* plain objects in practice */ } }
    }
    return groups;
  } catch {
    return [];
  } finally {
    if (timer) clearTimeout(timer);
  }
}

// Score how specific/informative a term is. Higher = more worth gating on.
function termSpecificity(term) {
  if (GENERIC_SCIENCE_WORDS.has(term)) return 0.15;
  // Intent verbs ("raise", "caution", "using") describe what the user WANTS
  // but not what the paper is ABOUT. Score below the anchor threshold so they
  // never dominate the top-4 rung.
  if (INTENT_WORDS.has(term)) return 0.2;
  let score = 0.5;
  // Longer words are usually more technical
  if (term.length >= 10) score += 0.3;
  else if (term.length >= 7) score += 0.2;
  else if (term.length <= 4) score -= 0.1;
  // Being part of a known concept group means it's a real topic anchor
  if (CONCEPT_LOOKUP.has(term)) score += 0.35;
  // Scientific morphology markers
  if (/(ase|ome|itis|osis|genic|troph|phyll|plast|cyte|blast|lysis|philic|phobic)$/.test(term)) score += 0.3;
  // Short technical identifiers are highly specific despite being short:
  // gene/protein names (p53, tau, myc), acronyms (mRNA, TNF, PCR), and
  // alphanumeric designators (CD4, IL6, BRCA1). Without this, a query like
  // "p53 mutations in glioma" would treat p53 as filler.
  if (/\d/.test(term) && /[a-z]/.test(term)) score += 0.4;   // alphanumeric: p53, il6, cd4
  if (SYNONYMS[term]) score += 0.4;                            // known scientific acronym
  if (term.length <= 5 && !COMMON_SHORT_WORDS.has(term)) score += 0.25;
  return Math.min(1, score);
}

// ── Structural centrality (2026-10-23, logic audit L1-7) ─────
// termSpecificity scores a word by its length, suffix, and
// table presence. That proxy used to be the single ranking
// that decided which concepts hold AND rungs, which get
// expansion, and which count as central at the gate, so its
// errors were the question's official meaning: the plain sleep
// question ANDed the framing adverb "clearly", and the assay
// question ANDed the generic modifier "standard" while the
// operative noun "assay" held no rung at all. Centrality is
// now derived from the question's structure first: the subject
// and lead key phrase words are the top class, stated
// constraints (quantity phrases, learned constraints) and
// operative nouns (the method nouns of a measurement ask) are
// the next, ordinary content words follow, and framing adverbs
// and generic modifiers are the bottom class. Specificity
// remains only as the tie breaker inside a class (the anchor
// race below still sorts by it within the eligible set). The
// standing rule the builder enforces with this: no bottom
// class term may hold an AND rung while a stated subject,
// substrate, quantity, or operative noun holds none.
const STRUCTURAL_FRAMING_ADVERBS = new Set([
  "clearly", "actually", "really", "barely", "still", "just",
  "even", "also", "very", "quite", "rather", "simply", "merely",
  "exactly", "probably", "possibly", "mainly", "mostly",
]);
const STRUCTURAL_GENERIC_MODIFIERS = new Set([
  "standard", "general", "normal", "common", "typical",
  "regular", "basic", "various", "different",
]);
const STRUCTURAL_OPERATIVE_NOUNS = new Set([
  "assay", "assays", "method", "methods", "test", "tests",
  "protocol", "protocols", "procedure", "procedures",
  "measurement", "measurements", "determination", "quantification",
]);
const STRUCTURAL_NUMBER_WORDS = new Set([
  "one", "two", "three", "four", "five", "six", "seven", "eight",
  "nine", "ten", "eleven", "twelve", "dozen",
]);

export function structuralTermClass(term, query) {
  const t = String(term || "").toLowerCase().trim();
  if (!t) return 1;
  if (STRUCTURAL_FRAMING_ADVERBS.has(t) || STRUCTURAL_GENERIC_MODIFIERS.has(t)) return 0;
  // Subject class: the lead key phrase's words and the resolved
  // organism's words, the same subject judgment the builder's
  // subject representation pass already makes.
  try {
    const analysis = analyzeQuery(query);
    if (analysis) {
      const kp = (analysis.keyPhrases || [])[0];
      if (kp && String(kp).toLowerCase().split(/[^a-z0-9]+/).includes(t)) return 3;
      if (analysis.organism
        && String(analysis.organism).toLowerCase().split(/[^a-z0-9]+/).includes(t)) return 3;
      for (const p of analysis.organismPhrases || []) {
        if (String(p).toLowerCase().split(/[^a-z0-9]+/).includes(t)) return 3;
      }
      // Stated constraints: every word of a required constraint
      // is a class 2 term by the grading in analyzeQuery.
      for (const c of analysis.constraints || []) {
        if (c.level === "required"
          && String(c.phrase || "").toLowerCase().split(/[^a-z0-9]+/).includes(t)) return 2;
      }
    }
  } catch { /* no analysis, structural classes below still apply */ }
  if (STRUCTURAL_OPERATIVE_NOUNS.has(t)) return 2;
  if (STRUCTURAL_NUMBER_WORDS.has(t) || /\d/.test(t)) return 2;
  try { if (GATE_TIME_UNIT_TOKENS.has(t)) return 2; } catch { /* unit set unavailable */ }
  try { if (isQuantityPhraseKey(t)) return 2; } catch { /* quantity predicate unavailable */ }
  return 1;
}

/* Whether a term's structural standing comes from being an
 * operative noun or a quantity (a number word, a digit term, a
 * time unit, a quantity phrase): the two named classes the
 * L1-7 displacement below may seat over a plain content anchor.
 * A required constraint word's standing is NOT this (its phrase
 * is already a constraint of the question, judged elsewhere),
 * and neither is a subject word's (the subject pass above owns
 * subject representation). */
export function structuralTermIsOperativeOrQuantity(term, query) {
  const t = String(term || "").toLowerCase().trim();
  if (!t) return false;
  if (STRUCTURAL_OPERATIVE_NOUNS.has(t)) return true;
  if (STRUCTURAL_NUMBER_WORDS.has(t) || /\d/.test(t)) return true;
  // A bare time unit word is not a stated quantity: "night" in
  // the sea turtle question is when the turtles come, not a
  // duration the question states. A unit counts only when the
  // question attaches a quantity to its units somewhere (a
  // digit or a number word: "six hours", "two weeks").
  try {
    if (GATE_TIME_UNIT_TOKENS.has(t)) {
      const q = String(query || "").toLowerCase();
      if (/\d/.test(q) || q.split(/[^a-z0-9]+/).some((w) => STRUCTURAL_NUMBER_WORDS.has(w))) return true;
    }
  } catch { /* unit set unavailable */ }
  try { if (isQuantityPhraseKey(t)) return true; } catch { /* quantity predicate unavailable */ }
  return false;
}

