// Every two-word Latin binomial this app already knows about (derived from
// SYNONYMS' values, so it stays in sync automatically as that list grows).
// NOTE: this MUST be defined after SYNONYMS above, not before . it reads
// SYNONYMS at module-evaluation time.
const KNOWN_BINOMIALS = [...new Set(
  Object.values(SYNONYMS).flat().filter((s) => /^[a-z]+ [a-z]+$/i.test(s))
)];

// A NARROWER, hand-curated subset of KNOWN_BINOMIALS restricted to entries
// that are genuinely organism species names. KNOWN_BINOMIALS above is fine
// for typo-correction (correctBinomialTypos gates on length >= 5 AND a close
// fuzzy match on BOTH words, which a generic phrase like "gene editing"
// virtually never survives), but it also picks up non-organism two-word
// SYNONYMS values purely because they happen to be two lowercase words .
// "gene editing" (from crispr), "mass spectrometry", "flow cytometry", etc.
// Anything doing a bare membership check for "is this actually a species" .
// like the multi-organism comparison detection below . must use this list
// instead, or a query mentioning CRISPR alongside a real organism triggers a
// bogus extra search for "Gene editing" as if it were a second species.
const ORGANISM_BINOMIALS = new Set([
  "hermetia illucens", "drosophila melanogaster", "mus musculus",
  "rattus norvegicus", "caenorhabditis elegans", "danio rerio",
  "saccharomyces cerevisiae", "escherichia coli", "staphylococcus aureus",
  "mycobacterium tuberculosis", "plasmodium falciparum", "apis mellifera",
  // Plants
  "arabidopsis thaliana", "oryza sativa", "zea mays", "triticum aestivum",
  "nicotiana tabacum", "solanum lycopersicum", "solanum tuberosum",
  "glycine max", "gossypium hirsutum",
  // Insects & invertebrates
  "bombyx mori", "aedes aegypti", "anopheles gambiae", "tenebrio molitor",
  "zophobas morio", "galleria mellonella", "tribolium castaneum",
  "manduca sexta", "spodoptera frugiperda", "locusta migratoria",
  // Vertebrate model organisms
  "xenopus laevis", "xenopus tropicalis", "gallus gallus", "sus scrofa",
  "bos taurus", "ovis aries", "canis lupus familiaris", "felis catus",
  "pan troglodytes", "macaca mulatta", "oryzias latipes",
  // Microorganisms
  "bacillus subtilis", "pseudomonas aeruginosa", "salmonella typhimurium",
  "vibrio cholerae", "clostridioides difficile", "helicobacter pylori",
  "streptococcus pneumoniae", "candida albicans", "aspergillus niger",
  "neurospora crassa", "schizosaccharomyces pombe",
]);

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost);
    }
  }
  return dp[m][n];
}

// Correct voice-dictation / typo mangling of a known scientific binomial .
// e.g. "Hermetia illucens" transcribed as "Hermia illusions" . by finding
// two ADJACENT query words that are each independently close (within ~1 edit
// per 3 characters) to a known genus and species word. Deliberately requires
// BOTH words to match: a single fuzzy word match alone is far too easy to
// collide with an unrelated real English word ("illusions" is a real word on
// its own . a lone match would corrupt a genuine query about, say, optical
// illusions . but "genus-shaped word" immediately followed by
// "species-shaped word", both close to a real binomial, is a strong signal
// nothing else produces by coincidence).
function correctBinomialTypos(query) {
  const toks = query.split(/\s+/);
  const clean = toks.map((t) => t.toLowerCase().replace(/[^a-z]/g, ""));
  for (const binomial of KNOWN_BINOMIALS) {
    const [genus, species] = binomial.split(" ");
    if (genus.length < 5 || species.length < 5) continue; // too short to fuzzy-match safely
    // ceil, not floor: floor(8/3)=2 rejects the actual repro case ("illusions"
    // is edit-distance 3 from "illucens") . verified numerically against the
    // real voice-dictation mangling this function exists to catch.
    const gThresh = Math.max(1, Math.ceil(genus.length / 3));
    const sThresh = Math.max(1, Math.ceil(species.length / 3));
    for (let i = 0; i + 1 < clean.length; i++) {
      const w1 = clean[i], w2 = clean[i + 1];
      if (w1.length < 4 || w2.length < 4) continue;
      const dG = levenshtein(w1, genus), dS = levenshtein(w2, species);
      // Already an exact match . leave the original text (and the user's own
      // capitalization) untouched. Rewriting a correctly-typed "Hermetia
      // illucens" down to a lowercase canonical form served no purpose here
      // and had a real side effect: it stripped the capitalization that
      // extractBinomial() elsewhere relies on to recognize a deliberately-
      // typed scientific name.
      if (dG === 0 && dS === 0) continue;
      if (dG <= gThresh && dS <= sThresh) {
        const before = toks.slice(0, i).join(" ");
        const after = toks.slice(i + 2).join(" ");
        return [before, genus + " " + species, after].filter(Boolean).join(" ");
      }
    }
  }
  return query;
}

function expansionsFor(tokens) {
  const out = [];
  const joined = tokens.join(" ").toLowerCase();
  // Multi word phrases first (e.g. "black soldier fly" is 3 tokens but
  // one SYNONYMS key; without this, common name organism queries never
  // resolve to their scientific name during expansion). A matched
  // phrase also CLAIMS its words: "wood frog" matching must stop the
  // bare token "frog" from expanding to a different animal entirely
  // (it resolved a wood frog question to Xenopus laevis, 2026-10-13).
  const claimed = new Set();
  for (const key of Object.keys(SYNONYMS)) {
    if (key.includes(" ") && joined.includes(key)) {
      out.push(...SYNONYMS[key]);
      for (const w of key.split(" ")) claimed.add(w);
    }
  }
  // Then individual tokens the phrases did not claim.
  for (const t of tokens) {
    const key = t.toLowerCase();
    if (claimed.has(key)) continue;
    if (SYNONYMS[key]) out.push(...SYNONYMS[key]);
  }
  return [...new Set(out)]; // deduplicate
}

const ORGANISM_PHRASES = [
  "black soldier fly larvae",
  "black soldier fly",
  "hermetia illucens",
  // Comparison queries ("BSFL vs honey bee gut microbiome") are the most
  // common real-world use case that names a second organism alongside BSFL,
  // so it's the first one wired in below. See the multi-organism retrieval
  // block in gatherPapers() for how a second named organism gets its own
  // search pass instead of being silently dropped.
  "honey bee",
  "honey bees",
  // Additional organisms that users commonly search by common name
  "fruit fly", "fruit flies",
  "lab rat", "lab mouse",
  "guinea pig",
  "house mouse",
  "baker's yeast", "brewer's yeast",
  "thale cress",
  "rhesus macaque",
  "zebra fish", "zebrafish",
  "roundworm", "nematode",
  "silk worm", "silkworm",
  "mealworm", "meal worm",
  "wax worm", "waxworm",
];
const ORGANISM_WORDS = new Set([
  "black", "soldier", "fly", "larvae", "larva", "larval", "hermetia", "illucens",
  "honey", "bee", "bees", "honeybee", "honeybees", "apis", "mellifera",
  "fruit", "flies", "drosophila", "melanogaster",
  "mouse", "mice", "mus", "musculus",
  "rat", "rats", "rattus", "norvegicus",
  "zebrafish", "danio", "rerio",
  "roundworm", "nematode", "caenorhabditis", "elegans",
  "silkworm", "bombyx", "mori",
  "mealworm", "tenebrio", "molitor",
  "waxworm", "galleria", "mellonella",
  "mosquito", "aedes", "aegypti", "anopheles", "gambiae",
  "arabidopsis", "thaliana",
  "yeast", "saccharomyces", "cerevisiae",
]);

function splitOrganismTopic(query) {
  const q = query.toLowerCase();
  const toks = q.split(/\s+/).filter((t) => t.length > 2);
  const exp = expansionsFor(toks);
  const orgPhrases = new Set(exp);
  // Matched multi word names (from either list) claim their words, so
  // a shorter name inside them ("frog" inside "wood frog") cannot pull
  // in a second, wrong organism alongside the right one.
  const phraseMatches = new Set(ORGANISM_PHRASES.filter((p) => q.includes(p)));
  for (const key of Object.keys(SYNONYMS)) {
    if (key.includes(" ") && q.includes(key)) phraseMatches.add(key);
  }
  const claimed = new Set();
  for (const p of phraseMatches) {
    if (p.includes(" ")) for (const w of p.split(" ")) claimed.add(w);
  }
  for (const phrase of phraseMatches) {
    if (!phrase.includes(" ") && claimed.has(phrase)) continue;
    orgPhrases.add(phrase);
    // Also resolve the phrase to its scientific name immediately
    const syns = SYNONYMS[phrase] || [];
    for (const s of syns) orgPhrases.add(s);
  }
  for (const t of toks) {
    if (claimed.has(t)) continue;
    if (SYNONYMS[t]) {
      orgPhrases.add(t);
      // Add expansions of individual tokens too
      for (const s of (SYNONYMS[t] || [])) orgPhrases.add(s);
    }
  }
  // 2026-10-13: the topic side of the organism branch used to take
  // every leftover token verbatim, so "Why do grain mills grind wheat
  // berries into flour for baking?" shipped the topic list (why OR
  // grain OR mills OR grind OR berries OR into OR flour OR for OR
  // baking?) — interrogatives, prepositions, and half the sentence,
  // punctuation still attached, ANDed against a precise organism
  // phrase. The organism side was exact and the topic side was noise.
  // Filter the topic through the same word sets the rest of the file
  // already trusts for "this word frames the question rather than
  // naming the topic": STOPWORDS, QUERY_FRAMING_WORDS, and
  // EXPANSION_FRAMING_WORDS. (All three sets are module level consts;
  // like buildStructuredQuery's own use of STOPWORDS above, they are
  // only read at call time, after the module has loaded.) Membership
  // is checked on the raw token and on its punctuation stripped form,
  // so "how?" is caught by "how" and "doesn't" by "doesn't", and the
  // topic carries the stripped form ("baking?" becomes "baking").
  const topic = [];
  for (const raw of toks) {
    const t = raw.replace(/[^\w-]/g, "");
    if (!t) continue;
    if (ORGANISM_WORDS.has(raw) || ORGANISM_WORDS.has(t)) continue;
    if (SYNONYMS[raw] || SYNONYMS[t]) continue;
    if (STOPWORDS.has(raw) || STOPWORDS.has(t)) continue;
    if (QUERY_FRAMING_WORDS.has(raw) || QUERY_FRAMING_WORDS.has(t)) continue;
    if (EXPANSION_FRAMING_WORDS.has(raw) || EXPANSION_FRAMING_WORDS.has(t)) continue;
    topic.push(t);
  }
  return {
    orgPhrases: [...orgPhrases],
    topic,
    hasOrganism: orgPhrases.size > 0,
  };
}

// ════════════════════════════════════════════════════════════════════
// STRUCTURED QUERY HYGIENE SCREEN (2026-10-14)
//
// The boolean this pipeline ships is authored from pieces a model
// or a tokenizer proposed: expansion groups keyed by glued lay
// phrases, anchors chosen by a specificity race over the cleaned
// question's surviving words. Neither author can tell a topic word
// from the question's own scaffolding, so filler kept becoming
// REQUIRED terms. Live trace (production, corrected ledger build):
// the question "does not sleeping enough make it easier to catch
// a cold" shipped the structured query
//   ("easier catch cold" OR "increased susceptibility to colds" OR
//    "elevated cold incidence") AND sleep AND enough
// — "enough", a quantity word, as a mandatory AND term. The
// primary retrieval starved on it, every fallback round fired,
// the fallback nets spent the answer reserve, validation and
// synthesis both skipped as budget exhausted, and the extractive
// tier cited collision papers about the words catch and easier.
// The third panel rescore had already named the class: literal
// AND queries built from lay words (its probe required the word
// "leftover").
//
// The screen is deterministic and runs where the authored query
// is assembled (gatherPapers) and where the analysis key phrases
// are minted (analyzeQuery), before either drives retrieval:
//   . A required term or phrase is admissible only if it CARRIES
//     CONTENT: at least one word that is not filler, not a
//     stopword, and not question framing. A phrase whose words are
//     all filler fails; a bare single word that is filler fails.
//   . When the authored boolean fails, it is not shipped. The
//     boolean is rebuilt from the resolved concept groups — the
//     gate's own resolution (questionConceptGroups over
//     gateDynLookup), so the rebuilt query and the gates that
//     judge its results are looking at the same concepts. When no
//     group resolves, the failed rungs are dropped and the
//     surviving rungs ship; when nothing survives, the authored
//     query ships after all, because a flawed boolean beats none.
//   . Either way the failure is RECORDED (the record's
//     structuredQueryProvenance): a degraded query is visible in
//     the search record, never silent.
// Verbs get suspicion, not a blanket ban: the light verbs of the
// asking (make, get, take, catch in its verb sense) are filler,
// but a content verb (degrade, survive, crack) is a topic word
// and passes — one that resolves to a concept group renders as an
// OR group in the first place, so the bare verb rung the screen
// judges is the exception, not the rule.
// ════════════════════════════════════════════════════════════════════

// Filler for requirement purposes: quantity and degree words,
// remainder words, degree comparatives, the light verbs, pronouns
// and person words, negation, and question scaffolding. A word is
// ALSO filler when a set the file already trusts for "this word
// frames the question" claims it (STOPWORDS, QUERY_FRAMING_WORDS,
// EXPANSION_FRAMING_WORDS) — those are module level consts defined
// later in the file and only read here at call time, the same
// arrangement buildStructuredQuery's own STOPWORDS use documents.
export const QUERY_FILLER_WORDS = new Set([
  // Quantity and degree: how much or how strong, never the topic.
  "enough", "much", "many", "more", "most", "less", "fewer", "very",
  "really", "quite", "rather", "too", "almost", "nearly", "mostly",
  "mainly", "fully", "partly", "well",
  "sufficient", "sufficiently", "insufficient", "insufficiently",
  // Remainder words: what is left over is a circumstance of the
  // asking, not a literature concept (the panel's "leftover" rung).
  "leftover", "leftovers", "remaining",
  // Degree comparatives: they grade the property the question asks
  // about; no paper is required to phrase the comparison.
  "easier", "harder", "better", "worse", "greater", "higher",
  "lower", "stronger", "weaker", "faster", "slower", "bigger",
  "smaller", "larger",
  // Light verbs: the asking's own verbs of doing. "catch" is the
  // proven trap (catch a cold); in its verb sense it names the
  // asking, not a topic. Content verbs are deliberately absent.
  "make", "makes", "making", "made", "get", "gets", "getting",
  "got", "take", "takes", "taking", "took", "catch", "catches",
  "catching", "caught", "keep", "keeps", "keeping", "kept", "let",
  "lets", "letting", "allow", "allows", "allowing", "help",
  "helps", "helping", "helped", "give", "gives", "giving", "put",
  "puts", "putting", "come", "comes", "coming", "came", "become",
  "becomes", "becoming", "became", "tend", "tends", "tended",
  "seem", "seems", "seemed",
  // Pronouns and person words: who is asking is never a concept.
  "anyone", "someone", "everyone", "anybody", "somebody",
  "everybody", "nobody", "whoever", "people", "person",
  // Possessives (2026-10-14, wave ten): the asker's possession
  // is the asker's, not a concept — "your" survived screening
  // and glued itself to the question's verb, minting the
  // constraint "eating your", a phrase no paper contains,
  // which the constraint filter then used to zero a healthy
  // yogurt shelf.
  "your", "yours", "my", "mine", "his", "hers", "its", "our", "ours", "their", "theirs",
  // Negation and scaffolding.
  "not", "no", "never", "without", "whether",
]);

function isQueryFillerWord(w) {
  return QUERY_FILLER_WORDS.has(w)
    || STOPWORDS.has(w)
    || QUERY_FRAMING_WORDS.has(w)
    || EXPANSION_FRAMING_WORDS.has(w);
}

// The content words of a term or phrase: what would remain if the
// question's scaffolding were stripped out of it. Empty means the
// term carries nothing a paper could be required to say.
export function queryTermContentWords(term) {
  return String(term || "")
    .toLowerCase()
    .replace(/[^\w\s-]/g, " ")
    .split(/[\s-]+/)
    .filter((w) => w && !isQueryFillerWord(w));
}

// Screen one analysis key phrase: the phrase with its filler words
// removed, or "" when nothing content bearing remains (the caller
// drops it). A phrase that survives keeps its content words in
// order, so "not sleeping enough" screens to "sleeping" and
// "easier catch cold" to "cold", while a real constraint phrase
// ("waste oil", "whole gut preparations") passes through word for
// word unchanged.
export function screenKeyPhrase(phrase) {
  const words = normalizeConstraintText(phrase).split(" ").filter(Boolean);
  if (!words.length) return "";
  const content = words.filter((w) => !isQueryFillerWord(w));
  // A lone surviving gerund stays: "sleeping" is the genuine
  // topic of the sleep question (pinned by the query
  // expansion suite), so a verb form alone is not proof of
  // scaffolding. The yogurt specimen ("eating your") is
  // handled by the possessives in the filler set above plus
  // the constraint filter's never zero stand down at its
  // call site — the screen does not need to guess.
  return content.join(" ");
}

// Split a shipped boolean on its TOP LEVEL operator, respecting
// parentheses and quoted phrases. The grammar buildStructuredQuery
// produces is small: rungs joined by " AND ", each rung a quoted
// phrase, a parenthesized OR group, or a bare word; the loose
// fallback is a flat OR of words.
function splitTopLevelBoolean(q, op) {
  const parts = [];
  let depth = 0;
  let inQuote = false;
  let cur = "";
  const needle = " " + op + " ";
  for (let i = 0; i < q.length; i++) {
    const ch = q[i];
    if (ch === '"') inQuote = !inQuote;
    if (!inQuote) {
      if (ch === "(") depth++;
      else if (ch === ")") depth = Math.max(0, depth - 1);
      else if (depth === 0 && q.startsWith(needle, i)) {
        parts.push(cur);
        cur = "";
        i += needle.length - 1;
        continue;
      }
    }
    cur += ch;
  }
  if (cur.trim()) parts.push(cur);
  return parts.map((s) => s.trim()).filter(Boolean);
}

// The members of one rung: the quoted phrases and bare words of an
// OR group, the phrase of a quoted rung, or the word itself.
function booleanRungMembers(rung) {
  let r = String(rung || "").trim();
  if (r.startsWith("(") && r.endsWith(")")) r = r.slice(1, -1);
  return splitTopLevelBoolean(r, "OR")
    .map((m) => m.trim().replace(/^"|"$/g, ""))
    .filter(Boolean);
}

// Screen the authored structured query. Returns { ok, failedRungs }
// where failedRungs names each top level AND rung whose every
// member is filler only — a requirement no paper can be asked to
// satisfy. An OR rung (the organism branch's topic group, or the
// loose all-OR fallback shape) is judged as one rung: it fails
// only when every alternate is filler, because an OR asks for any
// one of them, not for the head alone.
export function screenStructuredQuery(structuredQuery) {
  const q = String(structuredQuery || "").trim();
  if (!q) return { ok: true, failedRungs: [] };
  const rungs = splitTopLevelBoolean(q, "AND");
  const failedRungs = [];
  for (const rung of rungs) {
    const members = booleanRungMembers(rung);
    if (!members.length) continue;
    const carries = members.some((m) => queryTermContentWords(m).length > 0);
    if (!carries) failedRungs.push(rung);
  }
  return { ok: failedRungs.length === 0, failedRungs };
}

// The screened boolean with its failed rungs removed, or null when
// no rung survives. Rungs are rejoined verbatim, so a query whose
// only defect is one filler rung loses exactly that rung.
export function dropFailedRungs(structuredQuery, failedRungs) {
  const failed = new Set(failedRungs || []);
  if (!failed.size) return String(structuredQuery || "");
  const kept = splitTopLevelBoolean(String(structuredQuery || ""), "AND")
    .filter((r) => !failed.has(r));
  return kept.length ? kept.join(" AND ") : null;
}

// Rebuild the boolean from the resolved concept groups — the
// gate's own resolution, gateDynLookup merged groups, so the
// rebuilt query and the concept gates are looking at the same
// concepts by construction. Each group renders the way
// buildStructuredQuery renders an anchored group (the member the
// question actually used first, phrases quoted, capped at 7
// members), and at most four groups are ANDed, the same anchor
// budget the builder uses. Returns null when no group resolves.
export function rebuildStructuredQueryFromGroups(query, dynLookup) {
  const groups = questionConceptGroups(query, gateDynLookup(query, dynLookup));
  if (!groups.length) return null;
  const qLower = String(query || "").toLowerCase();
  const renderGroup = (set) => {
    const members = [...set];
    const head = members.find((m) => qLower.includes(m)) || members[0];
    // 2026-10-22 (search diagnosis, sleep trace): after the head,
    // multi word members render before single word members, the
    // same phrase first rule expandQueryTerms applies — under
    // the cap of 7, table order alone dropped the sleep group's
    // tail phrases ("sleep restriction" and family) out of every
    // rebuilt boolean, so the restriction literature was never
    // asked for by name. Cap and head rule unchanged.
    const rest = members.filter((m) => m !== head);
    const ordered = [
      head,
      ...rest.filter((m) => m.indexOf(" ") !== -1),
      ...rest.filter((m) => m.indexOf(" ") === -1),
    ].slice(0, 7);
    if (ordered.length === 1) {
      return ordered[0].includes(" ") ? '"' + ordered[0] + '"' : ordered[0];
    }
    return "(" + ordered.map((m) => (m.includes(" ") ? '"' + m + '"' : m)).join(" OR ") + ")";
  };
  const rungs = groups.slice(0, 4).map(renderGroup);
  // Overflow representation (2026-10-23, L1-11, closing the
  // part Wave 2 left standing): groups past the AND budget of
  // four used to be sliced off silently, so a fifth central
  // concept had no representation in the rebuilt boolean at
  // all. ANDing every group would starve the boolean, so the
  // overflow groups are represented as one OR rung of their
  // head terms: the tail concepts are present in the query, as
  // alternates of one rung, instead of absent. The AND budget
  // itself stands at four for the reason it always stood:
  // each additional mandatory group multiplies the chance the
  // boolean matches nothing, and the coverage state (L1-1)
  // already records any concept no source represented.
  if (groups.length > 4) {
    const overflowHeads = groups.slice(4).map((set) => {
      const members = [...set];
      return members.find((m) => qLower.includes(m)) || members[0];
    }).filter(Boolean);
    if (overflowHeads.length === 1) {
      rungs.push(overflowHeads[0].includes(" ") ? '"' + overflowHeads[0] + '"' : overflowHeads[0]);
    } else if (overflowHeads.length > 1) {
      rungs.push("(" + overflowHeads.map((m) => (m.includes(" ") ? '"' + m + '"' : m)).join(" OR ") + ")");
    }
  }
  return rungs.length ? rungs.join(" AND ") : null;
}

export function buildStructuredQuery(query, dynLookup) {
  // If the query names a scientific binomial, wrap it in quotes so search engines
  // treat it as a required phrase. This is what prevents "Populus deltoides"
  // papers from swamping a "Populus angustifolia" search.
  const bin = extractBinomial(query);
  if (bin) {
    // Extract the other topic words (not the binomial itself)
    const rest = query.toLowerCase().replace(new RegExp(bin.full, "gi"), "").replace(/\s+/g, " ").trim();
    // Wave seventeen (2026-10-15, citation depth diagnosis,
    // stage 4): closed class words stay out of the topic
    // alternates here too — the gate's own screen, the same one
    // the natural language path's anchors already pass. A
    // binomial question's leftover words are ORed as required
    // alternates, and a closed class word among them ("not",
    // "else") makes the group match nearly anything.
    const restTerms = rest.split(/\s+/).filter((t) => t.length > 2 && !STOPWORDS.has(t) && !isGateFunctionWord(t));
    if (restTerms.length) {
      return '"' + bin.full + '" AND (' + restTerms.join(" OR ") + ')';
    }
    return '"' + bin.full + '"';
  }
  const { orgPhrases, topic, hasOrganism } = splitOrganismTopic(query);
  // Anchor discipline (2026-10-14, sixth panel, wave seven):
  // orgPhrases mixes EVERY organism the question mentions with
  // each one's expansions. A feed question ("black soldier fly
  // larvae in chicken feed") resolved the word chicken through
  // the synonyms table to Gallus gallus and ORed it into the
  // organism group beside Hermetia illucens, so the boolean's
  // subject anchor named the feed target instead of the fly.
  // Anchors must come from the question's own subject and
  // organism (analyzeQuery): the primary organism is the
  // analysis's organism, and its family is the name itself plus
  // the source phrases that resolve to it. Any OTHER organism
  // phrase the question literally speaks is not an anchor; it
  // joins the topic side, where a feed target belongs. When the
  // analysis names no organism, the authored behavior stands.
  let anchorPhrases = orgPhrases;
  let anchorTopic = topic;
  if (hasOrganism) {
    try {
      const analysis = analyzeQuery(query);
      const primary = analysis && analysis.organism ? String(analysis.organism).toLowerCase() : null;
      if (primary) {
        const qLow = String(query).toLowerCase();
        // The primary organism's family, by SOURCE phrase: a
        // phrase the question literally speaks whose expansion
        // set contains the primary name contributes itself and
        // its whole expansion set — so the wood frog's two
        // binomials (Rana sylvatica and Lithobates sylvaticus,
        // alternate names of the ONE animal the question names)
        // both anchor, while the chicken's family (a different
        // source phrase entirely) does not.
        let fam = [];
        for (const sp of orgPhrases) {
          const spl = String(sp).toLowerCase();
          if (!qLow.includes(spl)) continue;
          const members = new Set([spl, ...(SYNONYMS[spl] || []).map((s) => String(s).toLowerCase())]);
          if (!members.has(primary)) continue;
          // Close over the whole family: every detected phrase
          // that IS a member, or whose own expansion set reaches
          // a member (the sibling common names "black soldier
          // fly" and "black soldier fly larva" expand to the same
          // Hermetia illucens and are the same animal).
          fam = orgPhrases.filter((p) => {
            const pl = String(p).toLowerCase();
            if (members.has(pl)) return true;
            return (SYNONYMS[pl] || []).some((s) => members.has(String(s).toLowerCase()));
          });
          break;
        }
        if (fam.length === 0) {
          fam = orgPhrases.filter((p) => {
            const pl = String(p).toLowerCase();
            if (pl === primary) return true;
            return (SYNONYMS[pl] || []).some((s) => String(s).toLowerCase() === primary);
          });
        }
        if (fam.length > 0) {
          anchorPhrases = fam;
          const extraTopic = orgPhrases.filter(
            (p) => !fam.includes(p) && qLow.includes(String(p).toLowerCase())
          );
          if (extraTopic.length) anchorTopic = [...topic, ...extraTopic];
        }
      }
    } catch { /* anchors fall back to every detected phrase */ }
  }
  if (hasOrganism) {
    // Wave seventeen (2026-10-15, citation depth diagnosis,
    // stage 4): closed class words never ride the topic side of
    // the organism boolean. The diagnosis run's structured
    // query was (...) AND (maggots OR fryer OR oil OR not OR
    // else): "not" and "else" as alternates made the topic
    // group nearly vacuous — any paper mentioning either word
    // satisfied it. Single word topic entries pass the gate's
    // own screen; phrases are kept whole (a phrase carries its
    // own meaning, and the screen judges words).
    anchorTopic = anchorTopic.filter((e) => {
      const s = String(e || "").toLowerCase().trim();
      return s.includes(" ") || !isGateFunctionWord(s);
    });
  }
  if (hasOrganism && (anchorTopic.length || !orgPhrases.length)) {
    // Resolve common names to scientific names for the boolean query.
    // "black soldier fly" alone is 3 common English words . PubMed will
    // match papers about black spruce or soldier beetles. The scientific
    // name as a quoted phrase is unambiguous.
    const resolvedOrg = new Set();
    for (const phrase of anchorPhrases) {
      const syns = SYNONYMS[phrase.toLowerCase()] || [];
      const sciRaw = syns.find((s) => /^[a-z]+ [a-z]+$/i.test(s) && s.split(" ").length === 2);
      if (sciRaw) {
        const parts = sciRaw.split(" ");
        resolvedOrg.add(parts[0][0].toUpperCase() + parts[0].slice(1).toLowerCase() + " " + parts[1].toLowerCase());
      }
      // Always keep the original phrase too for broader recall
      resolvedOrg.add(phrase);
    }
    const orgStr = [...resolvedOrg]
      .map((e) => (e.includes(" ") ? '"' + e + '"' : e))
      .join(" OR ");
    if (anchorTopic.length) {
      return "(" + orgStr + ") AND (" + anchorTopic.join(" OR ") + ")";
    }
    return orgStr;
  }
  if (hasOrganism) {
    return anchorPhrases
      .map((e) => (e.includes(" ") ? '"' + e + '"' : e))
      .join(" OR ");
  }

  // ---- Natural-language questions ----
  // Previously this returned the query verbatim. A question like "What types of
  // enzymes do insects have to degrade plastic compounds, and how do gut
  // microbes capitalize from them?" became a 9-word string, which PubMed and
  // Europe PMC treat as an implicit AND across every word. No paper contains
  // all nine, so retrieval returned ZERO and the answer fell back to the
  // model's memory . which is where the invented studies came from.
  //
  // Instead: keep only the most topic-bearing terms, expand each with its
  // concept group as an OR set, and AND the groups together. That turns the
  // question into (enzyme OR oxidase OR hydrolase...) AND (plastic OR
  // polyethylene OR PET...) AND (insect OR larvae OR Galleria...), which
  // actually retrieves the relevant literature.
  //
  // Split on hyphens as well as whitespace. A query like "insect-microbe
  // associations" previously kept "insect-microbe" as ONE opaque token that
  // matched neither the "insect" concept group nor the "microbe" one . so it
  // scored no better than an unrelated word, while "genetic" (a real,
  // single-word CONCEPT_LOOKUP hit) won the anchor race instead and dragged
  // in unrelated genome/transcriptome papers. Splitting "insect-microbe" into
  // "insect" + "microbe" lets both halves hit their correct concept groups.
  const qTerms = query
    .toLowerCase()
    .replace(/[^\w\s-]/g, " ")
    .split(/[\s-]+/)
    .filter((t) => t.length > 2 && !STOPWORDS.has(t));
  if (!qTerms.length) return query;

  // 2026-10-13: model-proposed PHRASE groups were structurally invisible
  // here. dynLookup keys can be multi-word ("whole gut preparations"),
  // but qTerms is single words and conceptSetFor below is only ever
  // called with one word, so no anchor could ever match a phrase key and
  // the group never became a rung. Live probe: "Has anyone assayed
  // digestive enzymes in whole gut preparations from insects without
  // isolating the enzymes?" carried a validated group for the
  // preparation phrase (alternates include "whole intestinal
  // homogenate"), yet the shipped boolean query had no preparation
  // group at all and the run ended at 0 cited. Mirror the phrase scan
  // topicOverlapFilter already does for the same lookup: a multi-word
  // dynLookup key that literally appears in the question becomes an
  // anchor itself, ahead of the word anchors, and its component words
  // stop competing for anchor slots (the phrase group replaces them,
  // so the total stays inside the two-to-four group budget below).
  const qLower = query.toLowerCase();
  const phraseAnchors = [];
  if (dynLookup) {
    for (const key of dynLookup.keys()) {
      if (key.indexOf(" ") !== -1 && qLower.includes(key)) phraseAnchors.push(key);
    }
  }
  // 2026-10-13: the HAND WRITTEN table had the same blind spot, and it
  // is the deterministic half of the homogenate failure. CONCEPT_GROUPS
  // carries multi word members (the preparation phrasings added to the
  // homogenate group: "whole gut preparation", "gut homogenate", ...),
  // and topicOverlapFilter already scans the raw question for them,
  // but this builder never did, so with no model call (or a model group
  // whose alternates missed the field's vocabulary) the shipped query
  // had no preparation rung at all. Live evidence, build 7b06b0a: the
  // whole gut preparations question shipped a preparation rung only
  // because the model proposed one, and its alternates ("whole gut
  // extract", "entire gut preparation", "whole gut lysate") contained
  // no MIDGUT form, while the sibling question whose wording keyed
  // the hand group ("insect midgut homogenate") retrieved the real
  // shelf (88 gathered, 4 cited). Midgut is the dominant word for
  // insect gut preparations in print, so the deterministic rung must
  // carry it. Mirror the filter's scan here: a multi word CONCEPT_GROUPS
  // member literally present in the question becomes a phrase anchor,
  // longest match per group, behind any model phrase for the same
  // string (conceptSetFor already prefers dynLookup, so a duplicate
  // anchor would only waste budget).
  // One guard keeps this from duplicating a rung a word anchor already
  // produces: when a component word of the phrase resolves to the very
  // same group ("gut homogenate" is claimed by "homogenate"), the word
  // anchor below brings the group in on its own and the phrase adds
  // nothing, so it is skipped. That is what leaves questions that
  // already key the group by a single word byte identical.
  {
    const seenPhrases = new Set(phraseAnchors);
    for (const group of CONCEPT_GROUPS) {
      let best = null;
      for (const member of group) {
        if (member.indexOf(" ") === -1 || !qLower.includes(member)) continue;
        const memberSet = CONCEPT_LOOKUP.get(member);
        const claimed = member
          .split(" ")
          .some((w) => CONCEPT_LOOKUP.get(w) && CONCEPT_LOOKUP.get(w) === memberSet);
        if (claimed) continue;
        if (!best || member.length > best.length) best = member;
      }
      if (best && !seenPhrases.has(best)) {
        phraseAnchors.push(best);
        seenPhrases.add(best);
      }
    }
  }
  // 2026-10-13: a negation led phrase ("without isolat enzyme") is an
  // absence, not a concept, and can never be an AND rung: papers do
  // not phrase absences, so the rung starves the boolean (live probe,
  // build 553caa4: gathered fell from 80 to 42 and the answer was a
  // scoped No). The validator already rejects these groups; this is
  // the defensive second line so hand written groups and future
  // callers that bypass the validator get the same protection. The
  // component words are NOT covered by a skipped phrase, so they stay
  // eligible as ordinary anchors below.
  const usablePhraseAnchors = phraseAnchors.filter((k) => !hasNegationLead(k));
  const coveredWords = new Set(usablePhraseAnchors.flatMap((p) => p.split(" ")));

  const ranked = qTerms
    .map((t) => ({ t, spec: termSpecificity(t) }))
    .sort((a, b) => b.spec - a.spec);
  // Two to four anchors. More than four AND-ed groups over-constrains again.
  // 2026-10-13 (fleet and coverage pass): framing words are barred from
  // the anchor race. qTerms above filters STOPWORDS only, but "has"
  // scores 0.65 in termSpecificity (the short word boost; it sits in
  // neither STOPWORDS nor COMMON_SHORT_WORDS) and "anyone" scores 0.5,
  // so on a short or resolver rewritten question they took the spare
  // AND slots: the live homogenate probe on build 2197a8f shipped a
  // structured query ending "AND has AND anyone". QUERY_FRAMING_WORDS
  // is the set analyzeQuery already uses to strip the asking from the
  // science. An anchor is a load bearing constraint, so the asking can
  // never be one. The loose OR fallback below still ranks unfiltered:
  // those terms are a recall aid, not a gate.
  const eligible = ranked.filter(
    (x) => x.spec >= 0.5 && !QUERY_FRAMING_WORDS.has(x.t) && !isGateFunctionWord(x.t)
  );
  const anchors = eligible.slice(0, 4).map((x) => x.t);
  // 2026-10-13 (rescore panel, Search retrieval 635 to 545): subject
  // representation. The race above ranks on termSpecificity alone,
  // and termSpecificity hands a +0.25 "short technical term" boost to
  // ANY word of five letters or fewer that is missing from the small
  // COMMON_SHORT_WORDS list. Everyday words are mostly short, so on
  // plain language questions they score 0.75 and take required AND
  // slots while the words the question is actually ABOUT score less:
  // the panel's seven mismatched probes (build 65ba977) promoted
  // break, grind, whole, carry, while, and sandy into rungs, and the
  // sea turtle probe's shipped query never anchored "turtles" at all
  // (sandy, beach, and crawl took the slots at 0.75 against its
  // 0.70). With expansion and validation healthy the damage is
  // masked; when the free fleet caps out, these deterministic anchors
  // ARE the query, and they were wrong.
  //
  // The rule: a term whose race standing comes ONLY from that boost
  // (short, not in COMMON_SHORT_WORDS, and carrying no independent
  // topic evidence: no concept group, no synonym entry, no digit, no
  // scientific morphology) is boost reliant, and a boost reliant
  // anchor may hold its slot only while no eligible subject term
  // stands outside. A subject term is any other eligible term: one
  // the tables know ("sea", "gut", "tree" all carry concept groups
  // despite their length), or one long enough to earn its score
  // without the boost. Each shut out subject term, in race order,
  // displaces the weakest boost reliant anchor in place, preferring
  // an anchor the token filter below discards anyway (a negation
  // lead like "not", whose slot was pure waste) over a real word.
  // Standing anchors are never displaced, eligibility and the slot
  // count are unchanged, and questions whose anchors already carry
  // their subjects (the homogenate pair among them) ship byte
  // identical queries.
  const boostReliant = (t) =>
    t.length <= 5 &&
    !COMMON_SHORT_WORDS.has(t) &&
    !CONCEPT_LOOKUP.has(t) &&
    !SYNONYMS[t] &&
    !/\d/.test(t) &&
    !/(ase|ome|itis|osis|genic|troph|phyll|plast|cyte|blast|lysis|philic|phobic)$/.test(t);
  {
    const anchored = new Set(anchors);
    for (const x of eligible) {
      if (anchored.has(x.t) || boostReliant(x.t)) continue;
      // A phrase covered word gains nothing here (the token filter
      // below drops it), and a negation lead is discarded there too;
      // neither may spend a displacement.
      if (coveredWords.has(x.t) || hasNegationLead(x.t)) continue;
      let victim = -1;
      for (let i = anchors.length - 1; i >= 0; i--) {
        if (!boostReliant(anchors[i])) continue;
        if (hasNegationLead(anchors[i])) { victim = i; break; }
        if (victim === -1) victim = i;
      }
      // WAVE EIGHT (2026-10-14, Job 3a arbitration): among the
      // remaining boost reliant victims, evict the one whose
      // specificity is HIGHEST, the last in race order on a tie.
      // The pure race order rule seated the subject by evicting
      // whichever reliant word happened to hold the final slot;
      // once closed class words stopped occupying slots (Job 3a),
      // that slot held a genuinely weak word ("prey") and the
      // displacement left "whole" — a boost reliant everyday
      // word, one of the panel's named rung squatters — LEADING
      // the snake query while "snakes" sat last. The boost
      // reliant word with the highest score is the one
      // masquerading as an anchor; it is the correct eviction.
      // On a tie the last in race order goes, as before: the sea
      // turtle race ties sandy and crawl at 0.75, and crawl (the
      // later, weaker standing word) is the one that must yield.
      if (victim === -1 || !hasNegationLead(anchors[victim])) {
        let bestSpec = -1;
        for (let i = 0; i < anchors.length; i++) {
          if (!boostReliant(anchors[i]) || hasNegationLead(anchors[i])) continue;
          const entry = ranked.find((r) => r.t === anchors[i]);
          const aSpec = entry ? entry.spec : 0;
          if (aSpec >= bestSpec) { bestSpec = aSpec; victim = i; }
        }
      }
      if (victim === -1) break;
      anchored.delete(anchors[victim]);
      anchors[victim] = x.t;
      anchored.add(x.t);
    }
  }
  // Subject representation (2026-10-14, sixth panel, wave seven):
  // the race and the displacement above rank on specificity
  // alone, and specificity cannot tell an adjective from the
  // question's subject — the panel measured a structured query
  // anchored on "brown" while the organism the question was
  // about held no rung. Anchors must come from the question's
  // own subject and organism (analyzeQuery): the words of the
  // lead key phrase and of the resolved organism are subject
  // terms, and an eligible subject term standing outside the
  // anchors displaces the weakest anchor that is not itself a
  // subject term (a boost reliant victim first, as above).
  // Subject terms already anchored are never displaced, and a
  // question whose analysis names neither a key phrase nor an
  // organism keeps the race exactly as it ran.
  {
    const subjectTerms = new Set();
    try {
      const analysis = analyzeQuery(query);
      if (analysis) {
        const kp = (analysis.keyPhrases || [])[0];
        if (kp) {
          for (const w of String(kp).toLowerCase().split(/[^a-z0-9]+/)) {
            if (w.length > 2) subjectTerms.add(w);
          }
        }
        if (analysis.organism) {
          for (const w of String(analysis.organism).toLowerCase().split(/[^a-z0-9]+/)) {
            if (w.length > 2) subjectTerms.add(w);
          }
        }
        for (const p of analysis.organismPhrases || []) {
          for (const w of String(p).toLowerCase().split(/[^a-z0-9]+/)) {
            if (w.length > 2) subjectTerms.add(w);
          }
        }
      }
    } catch { /* no analysis, no displacement */ }
    if (subjectTerms.size > 0) {
      const anchoredNow = new Set(anchors);
      for (const x of eligible) {
        if (!subjectTerms.has(x.t) || anchoredNow.has(x.t)) continue;
        if (coveredWords.has(x.t) || hasNegationLead(x.t)) continue;
        // A boost reliant candidate is never promoted: an
        // everyday word glued inside a key phrase ("break" in
        // "dry branches break") is not the subject, and promoting
        // it would evict a real subject term the race above
        // seated — the exact failure this rule exists to prevent,
        // run in reverse.
        if (boostReliant(x.t)) continue;
        // Victim: a boost reliant non subject anchor first (the
        // class the race already distrusts); otherwise the
        // weakest non subject anchor, and only when the incoming
        // subject term strictly outranks it — a subject term
        // never evicts a stronger anchor.
        let victim = -1;
        for (let i = anchors.length - 1; i >= 0; i--) {
          if (subjectTerms.has(anchors[i])) continue;
          if (boostReliant(anchors[i])) { victim = i; break; }
        }
        if (victim === -1) {
          let weakest = Infinity;
          for (let i = 0; i < anchors.length; i++) {
            if (subjectTerms.has(anchors[i])) continue;
            const entry = ranked.find((r) => r.t === anchors[i]);
            const aSpec = entry ? entry.spec : 0;
            if (aSpec < x.spec && aSpec < weakest) { weakest = aSpec; victim = i; }
          }
        }
        if (victim === -1) break;
        anchoredNow.delete(anchors[victim]);
        anchors[victim] = x.t;
        anchoredNow.add(x.t);
      }
    }
  }
  // Structural centrality pass (2026-10-23, L1-7): the standing
  // rule, enforced last so it sees the final anchor set. A
  // framing adverb or generic modifier (structural class 0) may
  // not hold an AND rung while a stated subject, quantity, or
  // operative noun (class 2 or 3) stands outside the anchors:
  // each such outside term, in race order, evicts the weakest
  // class 0 anchor in place. This is the exact pair the audit
  // measured: "clearly" ANDed on the sleep question while the
  // duration held no rung, and "standard" ANDed on the assay
  // question while "assay" itself held none. One step down,
  // the two classes the audit names outright, a stated quantity
  // and an operative noun, may also displace a plain content
  // anchor (class 1) that is not a subject term: the sleep
  // question's "night" over its stated duration "weeks", the
  // assay question's "measured" over "assay". Nothing else
  // about the arbitrated race changes: subject representation
  // stays with the pass above, and no anchor of the incoming
  // term's own class or better is ever evicted here.
  {
    const anchoredNow = new Set(anchors);
    // The builder's own subject definition, the same one the
    // subject representation pass above uses: the lead key
    // phrase's words and the resolved organism's words.
    const subjectSet = new Set();
    try {
      const analysis = analyzeQuery(query);
      if (analysis) {
        const kp = (analysis.keyPhrases || [])[0];
        if (kp) for (const w of String(kp).toLowerCase().split(/[^a-z0-9]+/)) if (w.length > 2) subjectSet.add(w);
        if (analysis.organism) for (const w of String(analysis.organism).toLowerCase().split(/[^a-z0-9]+/)) if (w.length > 2) subjectSet.add(w);
        for (const p of analysis.organismPhrases || []) {
          for (const w of String(p).toLowerCase().split(/[^a-z0-9]+/)) if (w.length > 2) subjectSet.add(w);
        }
      }
    } catch { /* no analysis, class order alone decides */ }
    const classOf = (t) => {
      try { return structuralTermClass(t, query); } catch { return 1; }
    };
    for (const x of eligible) {
      if (anchoredNow.has(x.t) || coveredWords.has(x.t) || hasNegationLead(x.t)) continue;
      const cls = classOf(x.t);
      if (cls < 2) continue;
      let victim = -1;
      for (let i = anchors.length - 1; i >= 0; i--) {
        if (classOf(anchors[i]) === 0) { victim = i; break; }
      }
      if (victim === -1) break;
      anchoredNow.delete(anchors[victim]);
      anchors[victim] = x.t;
      anchoredNow.add(x.t);
    }
    // The operative and quantity step reads the full ranked
    // list, not only the eligible anchors: a stated duration
    // can score under the anchor floor on specificity alone
    // ("weeks" on the sleep question), and a term the race
    // cannot see is a term this rule cannot seat.
    for (const x of ranked) {
      if (anchoredNow.has(x.t) || coveredWords.has(x.t) || hasNegationLead(x.t)) continue;
      if (QUERY_FRAMING_WORDS.has(x.t) || isGateFunctionWord(x.t)) continue;
      if (!structuralTermIsOperativeOrQuantity(x.t, query)) continue;
      let victim = -1;
      for (let i = anchors.length - 1; i >= 0; i--) {
        if (subjectSet.has(anchors[i])) continue;
        const aCls = classOf(anchors[i]);
        if (aCls === 0 || aCls === 1) { victim = i; break; }
      }
      if (victim === -1) break;
      anchoredNow.delete(anchors[victim]);
      anchors[victim] = x.t;
      anchoredNow.add(x.t);
    }
  }
  if (!usablePhraseAnchors.length && anchors.length < 2) {
    // Not enough specific terms to build groups . OR the best few so we still
    // get recall rather than an over-narrow AND.
    // WAVE EIGHT (2026-10-14, Job 3a): the loose OR path obeys
    // the same rung discipline as the anchor race — closed class
    // words hold no slot, and the question's subject and lead key
    // phrase head terms lead the list, so a thin question's only
    // rung still carries what the question is about.
    const looseTerms = ranked.filter((x) => !isGateFunctionWord(x.t)).map((x) => x.t);
    const leadTerms = [];
    try {
      for (const c of questionCentralConcepts(query, dynLookup)) {
        if (c && c.term && c.term.indexOf(" ") === -1 && looseTerms.includes(c.term) && !leadTerms.includes(c.term)) {
          leadTerms.push(c.term);
        }
      }
    } catch { /* race order stands */ }
    const leadSet = new Set(leadTerms);
    return [...leadTerms, ...looseTerms.filter((t) => !leadSet.has(t))].slice(0, 4).join(" OR ");
  }

  const tokenAnchors = anchors
    .filter((t) => !coveredWords.has(t) && !hasNegationLead(t))
    .slice(0, Math.max(0, 4 - usablePhraseAnchors.length));
  const groups = [...usablePhraseAnchors, ...tokenAnchors].map((t) => {
    let set = conceptSetFor(t, dynLookup);
    // 2026-10-13 (phrase merge): a phrase anchor can resolve in BOTH
    // lookups at once — the model proposed a group for the phrase and
    // the phrase is also a member of a hand written group.
    // conceptSetFor prefers the model set outright, so the hand
    // group's curated field vocabulary vanished on exactly the path
    // production takes: live, the model's alternates for "whole gut
    // preparations" ("whole gut extract", "entire gut preparation",
    // "whole gut lysate", ...) carried no midgut form, and the
    // deterministic midgut rung above only fired when the model was
    // absent or failed. Merge instead: hand written multi word
    // members first (the concept's names in print), then the model's
    // alternates that are not already present, then the hand group's
    // single word members; the member cap below trims the tail as
    // before. Phrase anchors only — word anchored rungs keep
    // conceptSetFor's precedence untouched, and a phrase present in
    // just one lookup keeps that lookup's set exactly as before.
    if (set && t.indexOf(" ") !== -1 && dynLookup && dynLookup.has(t) && CONCEPT_LOOKUP.has(t)) {
      const hand = CONCEPT_LOOKUP.get(t);
      const merged = new Set();
      for (const m of hand) if (m.indexOf(" ") !== -1) merged.add(m);
      for (const m of dynLookup.get(t)) merged.add(m);
      for (const m of hand) merged.add(m);
      set = merged;
    }
    if (!set) return t;
    // Cap expansion so the request URL stays reasonable, and keep the original
    // term first so it carries the most weight in relevance-ranked engines.
    // Wave seventeen (2026-10-15, citation depth diagnosis,
    // stage 4): closed class single words never ride a group as
    // alternates. A model proposed group can absorb the
    // question's framing words as members ("not" and "else"
    // rode the waste oil question's topic group on the
    // diagnosis run), and an OR alternate that common makes the
    // group match nearly anything. Phrases keep their words —
    // the screen judges single words only, as everywhere else
    // in this builder.
    const others = [...set].filter((m) => m !== t && (m.indexOf(" ") !== -1 || !isGateFunctionWord(m)));
    // 2026-10-13: a PHRASE anchored rung renders its multi word members
    // first. The phrases are the concept's actual names in print
    // ("midgut homogenate", "gut extract"); the single word members are
    // mostly morphological variants of the head noun (homogenized,
    // homogenised) that the engines stem anyway, and under the cap
    // they crowded the field vocabulary out of the preparation rung
    // entirely. Word anchored rungs keep the table order untouched.
    // 2026-10-22 (search diagnosis, sleep trace): the phrase first
    // ordering now applies to word anchored rungs too. The sleep
    // group's restriction vocabulary ("sleep restriction",
    // "chronic sleep restriction", "sleep loss", "short sleep")
    // rides the tail as phrases behind four single word members,
    // so under the cap of 7 every rendered rung carried the head
    // forms and NONE of the restriction phrases the 2026-10-21
    // bridge added — the bridge existed in the table and in no
    // executed query (proven by the instrumented trace: the
    // Europe PMC clause for the two weeks question rendered
    // exactly the seven pre bridge members). Phrases are the
    // field's names in print in both anchor shapes; the cap and
    // the head first rule are unchanged.
    const ordered = [
      ...others.filter((m) => m.indexOf(" ") !== -1),
      ...others.filter((m) => m.indexOf(" ") === -1),
    ];
    const members = [t, ...ordered].slice(0, 7);
    return "(" + members.map((m) => (m.includes(" ") ? '"' + m + '"' : m)).join(" OR ") + ")";
  });
  return groups.join(" AND ");
}

const STOPWORDS = new Set([
  "what","whats","how","does","do","did","is","are","was","were","the","a","an",
  "of","in","on","for","to","and","or","with","by","about","tell","me","explain",
  "why","when","where","which","who","can","you","please","give","show","find",
  "search","look","up","that","this","these","those","it","its","work","works",
  "happen","happens","mean","means","between","into","from","as","at","be","been",
  "get","got","i","my","we","our","use","used","using","there","their","they",
  "responding","respond","level","levels","basis","role","effect","effects",
  "each","every","change","changes","through","throughout","section","sections",
  "different","part","parts","type","types","kind","example","within",
  "some","other","most","many","much","very","just","also","still","really",
  "would","could","should","might","may","will","shall","must","need",
  // 2026-09-14: question-framing meta-words. "Is it true that X?" was
  // cleaned to "true X" . databases searched for the literal word "true"
  // and returned 0 papers. These words describe the question, not the
  // science, and must not pollute the database query.
  "true","false","truly","actually","fact","facts",
  // 2026-10-10: query-framing words from QUERY_FRAMING_WORDS. "Studies
  // involving BSFL waste oil" was scoring 0 sources while "BSFL waste oil"
  // returned 3, because "studies"/"involving" polluted the term lists.
  // analyzeQuery already strips these via QUERY_FRAMING_WORDS; the scorer
  // must too.
  "studies","study","involving","involved","involves","involve",
  "papers","paper","research","researching","regarding",
  // 2026-10-13: light verbs that frame questions. "What lets a wood
  // frog survive..." ranked "lets" as a content term, so the boolean
  // query ANDed the organism against (lets OR wood) and the expansion
  // trigger wasted its one call proposing groups for "lets". These
  // verbs carry no scientific content in a question.
  "let","lets","make","makes","made","allow","allows","allowed",
  "help","helps","helped","keep","keeps","kept","take","takes","took",
  "become","becomes","became","come","comes","came",
  // Contraction fragments: tokenizers split on the apostrophe, so
  // "doesn't" leaves "doesn" behind. It ranked as a content term on a
  // live probe (2026-10-13) and ANDed itself into the structured
  // query.
  "doesn","didn","isn","aren","wasn","weren","wouldn","couldn",
  "shouldn","hasn","haven","ain","don",
  "doesn't","don't","isn't","aren't","wasn't","weren't","didn't",
  "won't","wouldn't","couldn't","shouldn't","hasn't","haven't",
  "can't","cannot",
]);

// Verb lemmatization for search terms (2026-10-08 search reliability fix).
// Natural-language questions contain conjugated verbs ("dries", "cracks",
// "forms") but papers are indexed under base/noun forms ("dry", "drying",
// "crack", "formation"). Sending the conjugated form to keyword APIs is a
// recall killer . "dries" matches almost nothing, "dry" matches "drying",
// "desiccation", etc. via the engines' own stemming. This maps common
// conjugations to base form before the terms reach any API.
// Conservative: only strips unambiguous verb suffixes, never touches short
// words or words where stripping would create a non-word.
// The SURFACE form of the cleaned query (2026-10-14, sixth
// panel, wave seven): the same stopword and punctuation
// cleaning as cleanQuery, WITHOUT lemmatization. cleanQuery's
// lemmatized output is an internal matching device — its stems
// ("rais" from raising, "flie" from flies) are not words, and
// they leaked into database queries (PubMed, which does not
// stem boolean fragments, returned zero on seven of seven panel
// probes) and into user facing reformulations. Every fetcher
// query and every user facing string is built from surface
// terms; stemming stays inside the matchers that consume it.
export function cleanSurfaceQuery(raw) {
  const sanitized = String(raw || "")
    .replace(/[^\w\s-]/g, " ")
    .toLowerCase();
  const cleaned = sanitized
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w))
    .join(" ")
    .trim();
  return cleaned || String(raw || "").trim().slice(0, 500);
}

function lemmatizeTerm(w) {
  if (!w || w.length <= 4) return w;
  // Irregular verbs and common mappings first
  const IRREGULAR = {
    "dries": "dry", "dried": "dry",
    "dies": "die", "died": "die",
    "lies": "lie", "lied": "lie", "lying": "lie",
    "ties": "tie", "tied": "tie",
    "goes": "go", "went": "go", "going": "go",
    "does": "do",
    "has": "have", "had": "have", "having": "have",
    "is": "be", "are": "be", "was": "be", "were": "be", "being": "be", "been": "be",
  };
  const lower = w.toLowerCase();
  if (IRREGULAR[lower]) return IRREGULAR[lower];
  // Regular conjugations: -ies → -y (dries→dry, carries→carry)
  if (/ies$/.test(lower) && lower.length > 5) return lower.slice(0, -3) + "y";
  // -ing → base (drying→dry, cracking→crack) . but not if it leaves <3 chars
  // and not for words where -ing is part of the root (king, ring, spring)
  if (/ing$/.test(lower) && lower.length > 5 && !/^(king|ring|spring|thing|bring|sing|wing|string)$/.test(lower)) {
    const base = lower.slice(0, -3);
    // Handle doubled consonant: running→run, but cracking→crack (no double)
    if (base.length >= 3) return base.replace(/([^aeiou])\1$/, "$1");
  }
  // -ed → base (dried→dry, cracked→crack)
  if (/ied$/.test(lower) && lower.length > 5) return lower.slice(0, -3) + "y";
  if (/ed$/.test(lower) && lower.length > 5 && !/(ted|ded|eed|ood)$/.test(lower)) {
    const base = lower.slice(0, -2);
    if (base.length >= 4) return base.replace(/([^aeiou])\1$/, "$1");
  }
  // -es → base (watches→watch, fixes→fix, goes→go handled above)
  if (/es$/.test(lower) && lower.length > 5 && /(ches|shes|sses|xes|zes|oes)$/.test(lower)) {
    return lower.slice(0, -2);
  }
  // -s → base (cracks→crack, forms→form, patterns→pattern)
  // Careful: don't strip from words ending in -ss, -us, -is (class, virus, crisis)
  if (/s$/.test(lower) && lower.length > 4 && !/(ss|us|is|os)$/.test(lower)) {
    return lower.slice(0, -1);
  }
  return w;
}

function cleanQuery(raw) {
  // Strip potential prompt injection attempts
  let sanitized = raw
    .replace(/\b(ignore|disregard|forget)\s+(all\s+)?(previous|above|prior)\s+(instructions?|prompts?|rules?|context)\b/gi, "")
    .replace(/\b(system|assistant|user)\s*:/gi, "")
    .replace(/```[\s\S]*?```/g, "")
    .replace(/<[^>]+>/g, "")
    .slice(0, 500); // Hard cap query length

  const cleaned = sanitized
    .toLowerCase()
    .replace(/[^\w\s-]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w))
    .map((w) => lemmatizeTerm(w))
    .join(" ")
    .trim();
  return cleaned || raw.trim().slice(0, 500);
}


// ============ SCHOLARLY DATABASE SOURCES ============
// Each source returns [] on any failure, never throws. Timeouts keep them fast.

/* Fetcher internal fallback signal (2026-10-22, L2-3). Inside
 * europePMC and pubmed the structured and organism fallback forms
 * used to fire only when the first form returned exactly zero
 * rows, so a first form returning only off topic rows blocked the
 * better query form. The fetchers receive only a query string:
 * no dynLookup and no gate context rides along, so the full
 * citable signal (countOnTopicPapers, judged by the citation
 * gate) is not reachable there. The cheaper documented proxy used
 * instead: a row is on topic when its title or abstract touches
 * at least two distinct content terms of the sent query (at
 * least one when the query carries a single content term), judged
 * by the same stem aware term hit the gate uses
 * (termStemHitInText). Rows may be raw Europe PMC records
 * (abstractText) or mapped papers (abstract); both are read.
 * fetcherRowsNeedFallback is the decision both fetchers consult:
 * true when there are no rows at all, or when rows exist and none
 * of them is on topic under the proxy. */
export function fetcherQueryContentTerms(query) {
  const raw = String(query || "").toLowerCase()
    .replace(/\b(and|or|not)\b/g, " ")
    .replace(/[a-z_]+:/g, " ")
    .replace(/[^a-z0-9\s-]+/g, " ");
  const terms = [];
  for (const t of raw.split(/[\s-]+/)) {
    if (t.length > 2 && !STOPWORDS.has(t) && !terms.includes(t)) terms.push(t);
  }
  return terms;
}
export function fetcherRowsOnTopicCount(rows, query) {
  const list = Array.isArray(rows) ? rows : [];
  if (list.length === 0) return 0;
  const terms = fetcherQueryContentTerms(query);
  if (terms.length === 0) return list.length;
  const need = terms.length === 1 ? 1 : 2;
  let n = 0;
  for (const r of list) {
    if (!r) continue;
    const hay = (String(r.title || "") + " " + String(r.abstractText || r.abstract || "")).toLowerCase();
    if (!hay.trim()) continue;
    let hits = 0;
    for (const t of terms) {
      try { if (termStemHitInText(hay, t)) hits++; } catch { if (hay.includes(t)) hits++; }
    }
    if (hits >= need) n++;
  }
  return n;
}
export function fetcherRowsNeedFallback(rows, query) {
  const list = Array.isArray(rows) ? rows : [];
  if (list.length === 0) return true;
  return fetcherRowsOnTopicCount(list, query) === 0;
}

/* The fetcher structured fallback form (2026-10-23, logic
 * audit L1-17). The structured query is computed ONCE by the
 * pipeline, in its final form (the boolean built from the
 * surface query with the run's dynLookup), and passed down as
 * data through opts.structuredQuery. Fetchers use that form
 * verbatim for their internal fallback and never reconstruct
 * query meaning from whatever string they were handed: the old
 * rebuild called buildStructuredQuery(query) with no dynLookup,
 * which dropped every model proposed and fallback concept
 * group, and for europePMC tokenized the already built boolean
 * it had been given instead of the user's question. Only a
 * caller that passes no form at all (a direct call outside the
 * pipeline) takes the legacy rebuild. */
export function fetcherStructuredFallback(query, opts) {
  if (opts && typeof opts.structuredQuery === "string" && opts.structuredQuery) {
    return opts.structuredQuery;
  }
  return buildStructuredQuery(query);
}

export async function europePMC(query, limit = 8, ledger = null, opts = {}) {
  // Trust the query we were given. The retrieval ladder passes progressively
  // simpler forms . if this function silently rebuilds them, the ladder can't
  // work. Fall back to the structured/organism forms when the given query
  // returns nothing, or when everything it returns scores off topic under
  // the fetcher proxy above (fetcherRowsNeedFallback, 2026-10-22, L2-3):
  // volume alone no longer blocks the better form. A fallback form's rows
  // replace the current rows only when they score more on topic papers, or
  // when the current rows are empty; a failed fallback call keeps the rows
  // already in hand instead of losing them to the outer catch.
  const runSearch = async (qs) => {
    // No server side language filter (2026-10-23, logic audit
    // L2-14): this leg used to append a LANG eng clause to every query,
    // the same class of filter the OpenAlex leg removed in 2026-10
    // for silently deleting exactly on topic papers whose language
    // metadata is missing. The reasoning applies here unchanged:
    // a record with missing or incomplete language indexing is
    // unreachable through a server side filter and its removal is
    // invisible in the funnel, while the post fetch language
    // screen downstream counts what it removes. The query ships
    // as the caller built it.
    const params = {
      query: qs,
      resultType: "core",
      pageSize: String(limit),
      format: "json",
      // Commit 94 . the `sort` parameter was removed here. Europe PMC
      // documents CITED / P_PDATE_D / AUTH_FIRST as sort values; "relevance"
      // is not one of them, and relevance IS the default when sort is
      // omitted. Passing an undocumented value risked a 400 that this
      // function's bare catch would have turned into an empty result set .
      // i.e. a whole source silently contributing nothing.
    };
    // Wave twelve (item 2): a caller may still ask for one of the
    // DOCUMENTED sort values by name. The foundational lane does:
    // its whole job is the field's most cited first descriptions,
    // and the default order demonstrably does not return them
    // (probed live 2026-10-14: the lane query's default first page
    // was 2026 papers with zero citations, while sort=CITED desc
    // returned the 2012 founding paper first with 11,954).
    if (opts && typeof opts.sort === "string" && opts.sort) params.sort = opts.sort;
    // Page shifting (2026-10-23, L2-5): Europe PMC paginates by
    // cursor mark. A caller working past the first page (the
    // shifted form requery in the gather) passes the cursor it
    // was handed; the first page's response carries it as
    // nextCursorMark, read by the caller off the raw rows.
    if (opts && typeof opts.cursorMark === "string" && opts.cursorMark) params.cursorMark = opts.cursorMark;
    const url =
      "https://www.ebi.ac.uk/europepmc/webservices/rest/search?" +
      new URLSearchParams(params);
    const data = await getJSON(url, {}, 4000, 1, ledger);
    return data && data.resultList && data.resultList.result ? data.resultList.result : [];
  };
  try {
    let rows = await runSearch(query);
    if (fetcherRowsNeedFallback(rows, query)) {
      const structured = fetcherStructuredFallback(query, opts);
      if (structured && structured !== query) {
        const structuredRows = await runSearch(structured).catch(() => null);
        if (structuredRows && structuredRows.length
          && (rows.length === 0 || fetcherRowsOnTopicCount(structuredRows, query) > fetcherRowsOnTopicCount(rows, query))) {
          rows = structuredRows;
        }
      }
    }
    if (fetcherRowsNeedFallback(rows, query)) {
      const { orgPhrases, hasOrganism } = splitOrganismTopic(query);
      if (hasOrganism) {
        const orgRows = await runSearch(
          orgPhrases.map((e) => (e.includes(" ") ? '"' + e + '"' : e)).join(" OR ")
        ).catch(() => null);
        if (orgRows && orgRows.length
          && (rows.length === 0 || fetcherRowsOnTopicCount(orgRows, query) > fetcherRowsOnTopicCount(rows, query))) {
          rows = orgRows;
        }
      }
    }
    return rows
      .filter((r) => r.title)
      .map((r) => ({
        title: r.title || "Untitled",
        url: r.doi
          ? "https://doi.org/" + r.doi
          : "https://europepmc.org/article/" + r.source + "/" + r.id,
        year: r.pubYear || "",
        citations: typeof r.citedByCount === "number" ? r.citedByCount : null,
        authors: r.authorString || "",
        _allAuthors: r.authorString || "",
        journal: r.journalTitle || "",
        abstract: stripTags(r.abstractText),
        pmcid: r.pmcid || (r.source === "PMC" ? r.id : "") || "",
        // Europe PMC is not a major dataset-leak vector . it indexes literature,
        // not deposits . but `pubType`/`pubTypeList.pubType` are on the record
        // when present, so carry them through for the universal reject filter
        // (isNonLiterature, below) to inspect defense-in-depth rather than
        // trusting this source blindly just because it's usually clean.
        _rawType: (r.pubTypeList && Array.isArray(r.pubTypeList.pubType) ? r.pubTypeList.pubType.join(",") : "") || r.pubType || "",
      }));
  } catch (e) {
    // Marked failure (2026-10-23, L2-1): a swallowed error must
    // never read as a source that answered with zero.
    return fetchFailed(e);
  }
}

function firstMatch(block, re) {
  const m = block.match(re);
  return m ? m[1] : "";
}

function parsePubmedXML(xmlText) {
  const arts = xmlText.match(/<PubmedArticle\b[\s\S]*?<\/PubmedArticle>/g) || [];
  return arts.map((a) => {
    const pmid = firstMatch(a, /<PMID[^>]*>(\d+)<\/PMID>/);
    const title = stripTags(
      firstMatch(a, /<ArticleTitle[^>]*>([\s\S]*?)<\/ArticleTitle>/)
    );
    const absParts = a.match(/<AbstractText[^>]*>([\s\S]*?)<\/AbstractText>/g) || [];
    const abstract = stripTags(absParts.join(" "));
    const journal = stripTags(
      firstMatch(a, /<Title>([\s\S]*?)<\/Title>/) ||
        firstMatch(a, /<ISOAbbreviation>([\s\S]*?)<\/ISOAbbreviation>/)
    );
    const year = firstMatch(a, /<PubDate>[\s\S]*?<Year>(\d{4})<\/Year>/);
    const authorBlocks = a.match(/<Author\b[\s\S]*?<\/Author>/g) || [];
    const names = authorBlocks
      .map((b) => {
        const last = firstMatch(b, /<LastName>([\s\S]*?)<\/LastName>/);
        const ini = firstMatch(b, /<Initials>([\s\S]*?)<\/Initials>/);
        return [last, ini].filter(Boolean).join(" ");
      })
      .filter(Boolean);
    const authors =
      names.length > 1 ? names[0] + " et al." : names[0] || "";
    const doi = firstMatch(a, /<ArticleId IdType="doi">([\s\S]*?)<\/ArticleId>/);
    return {
      title: title || "Untitled",
      url: doi
        ? "https://doi.org/" + doi
        : "https://pubmed.ncbi.nlm.nih.gov/" + pmid + "/",
      year,
      citations: null,
      authors,
      // Full author list (2026-10-23, L2-13): the author branch
      // matches per individual author, which the truncated
      // display field cannot support. Every name efetch returned
      // rides here, the same field the other fetchers set.
      _allAuthors: names.join(", "),
      journal: journal || "",
      abstract,
      pmid,
    };
  });
}

export async function pubmed(query, limit = 10, apiKey = "", ledger = null, opts = {}) {
  const keyParam = apiKey ? "&api_key=" + apiKey : "";
  const tool = "&tool=cerebrum&email=contact@askcerebrum.org" + keyParam;
  try {
    let ids = [];

    const esUrl = (t) =>
      "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?" +
      new URLSearchParams({
        db: "pubmed",
        term: t,
        retmax: String(limit),
        retmode: "json",
        sort: "relevance",
      }) +
      tool;

    // Try the query we were given first (the ladder is calibrated for it).
    const es = await getJSON(esUrl(query), {}, 4000, 1, ledger).catch(() => null);
    ids = (es && es.esearchresult && es.esearchresult.idlist) || [];

    // Fallback ladder: structured, then organism-focused. The
    // structured form is the pipeline's, passed as data
    // (2026-10-23, L1-17), never rebuilt here without dynLookup.
    if (!ids.length) {
      const structured = fetcherStructuredFallback(query, opts);
      if (structured && structured !== query) {
        const es2 = await getJSON(esUrl(structured), {}, 4000, 1, ledger).catch(() => null);
        ids = (es2 && es2.esearchresult && es2.esearchresult.idlist) || [];
      }
    }
    if (!ids.length) {
      const { orgPhrases, hasOrganism } = splitOrganismTopic(query);
      if (hasOrganism) {
        const orgOnly = orgPhrases
          .map((e) => (e.includes(" ") ? '"' + e + '"' : e))
          .join(" OR ");
        const es3 = await getJSON(esUrl(orgOnly), {}, 4000, 1, ledger).catch(() => null);
        ids = (es3 && es3.esearchresult && es3.esearchresult.idlist) || [];
      }
    }
    if (!ids.length) return [];

    const fetchByIds = async (idList) => {
      const xml = await getText(
        "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?" +
          new URLSearchParams({ db: "pubmed", id: idList.join(","), retmode: "xml" }) +
          tool,
        {},
        4000,
        1,
        ledger
      ).catch(() => "");
      const fetched = xml ? parsePubmedXML(xml) : [];
      const byPmid = new Map(fetched.map((p) => [p.pmid, p]));
      const out = [];
      for (const pmid of idList) {
        const rec = byPmid.get(pmid) || null;
        if (rec && rec.title) out.push(rec);
      }
      for (const p of fetched) {
        if (!out.some((m) => m.pmid === p.pmid)) out.push(p);
      }
      return out;
    };

    // Two logical calls on the success path (2026-10-14, wave
    // eight round three, Job 2): esearch, then efetch. The
    // esummary call that used to race efetch is gone: efetch's
    // XML already carries every field esummary was merged in
    // for (title, journal, year, authors, and the abstract
    // esummary never carried at all), so the third call bought
    // nothing but ledger exposure — this fetcher is the only
    // sequential multi call design in the fanout, and its late
    // calls were the first refused when the retrieval allowance
    // ran short (the seventh panel measured PubMed returning 0
    // in 6 of 6 probes). parsePubmedXML's records are the
    // records; a PMID efetch does not return a record for no
    // longer becomes an abstract free stub, which could never
    // clear the citation gate anyway.
    let merged = await fetchByIds(ids);

    // Off topic fallback (2026-10-22, L2-3): esearch returns
    // IDs only, so topicality cannot be judged until the
    // records are fetched. When every fetched record scores
    // off topic under the fetcher proxy (fetcherRowsNeedFallback),
    // the structured and organism forms run now, the same forms
    // the esearch stage already tried when the first form
    // returned no IDs at all. Volume with no on topic paper no
    // longer blocks them. A fallback form's papers are adopted
    // only when they carry on topic papers the current set
    // lacks; a failed fallback call keeps the papers in hand.
    if (fetcherRowsNeedFallback(merged, query)) {
      const tryFallbackForm = async (formQuery) => {
        if (!formQuery || formQuery === query) return;
        if (!fetcherRowsNeedFallback(merged, query)) return;
        try {
          const formData = await getJSON(esUrl(formQuery), {}, 4000, 1, ledger).catch(() => null);
          const formIds = (formData && formData.esearchresult && formData.esearchresult.idlist) || [];
          if (!formIds.length) return;
          const formPapers = await fetchByIds(formIds);
          if (fetcherRowsOnTopicCount(formPapers, query) > fetcherRowsOnTopicCount(merged, query)) {
            merged = formPapers;
          }
        } catch { /* keep the papers already in hand */ }
      };
      await tryFallbackForm(fetcherStructuredFallback(query, opts));
      if (fetcherRowsNeedFallback(merged, query)) {
        const { orgPhrases, hasOrganism } = splitOrganismTopic(query);
        if (hasOrganism) {
          await tryFallbackForm(
            orgPhrases.map((e) => (e.includes(" ") ? '"' + e + '"' : e)).join(" OR "));
        }
      }
    }
    return merged;
  } catch (e) {
    return fetchFailed(e);
  }
}

// Looks like a scientific binomial (Genus species): 2+ words, first capitalized,
// second lowercase, italic-ish structure. Examples: "Populus angustifolia",
// "populus angustifolia", "P. angustifolia", "Hermetia illucens".
// Returns {binomial: "populus angustifolia", genus, species} or null.
// Detects a Latin binomial nomenclature (genus + species) inside a query.
// e.g. "Populus angustifolia", "populus angustifolia", "Hermetia illucens"
// Returns the binomial object, or null. Used to enforce strict species matching:
// searches for one species must NOT surface papers about a sibling species in the
// same genus (huge source of false positives in taxonomic queries).
// Eponymous adjectives and field nouns are never a genus or an
// epithet, but they fit the binomial shape perfectly: "Bayesian
// statistics" is a topic, not a species. Returned as one, it gated
// evidence on the phrase and italicized it through the whole answer.
const NON_GENUS_FIRST_WORDS = new Set([
  "bayesian", "gaussian", "markovian", "newtonian", "euclidean",
  "cartesian", "boolean", "darwinian", "mendelian", "poisson",
  "bernoulli", "fourier", "laplacian", "hamiltonian",
]);
const NON_SPECIES_SECOND_WORDS = new Set([
  "statistics", "analysis", "regression", "probability", "inference",
  "theory", "method", "methods", "learning", "modeling", "modelling",
  "distribution", "estimation", "hypothesis", "dynamics",
]);

// Closed-class function words (2026-10-13, the "Has anyone" live
// failure). A genus is a Latin noun and a species epithet is a Latin
// adjective or genitive; neither slot can ever be filled by an English
// auxiliary, modal, interrogative, or pronoun. These classes are
// closed (English adds no new auxiliaries or pronouns), so listing
// them is complete in a way a topic word blocklist can never be.
// Without this guard, a question opening "Has anyone assayed..."
// extracted the phantom binomial {Has, anyone}: sentence-initial
// capitalization made "Has" look like a genus, and neither word is in
// STOPWORDS or the sets above. The binomial branch of the paper gate
// then required every candidate paper to contain the "species" word
// "anyone", silently deleting the entire real shelf (digestive enzyme
// papers on Mastotermes, Catopsilia, vine weevil were all in the
// pool) and leaving only the junk papers that happened to print the
// word "anyone". When the phantom second word is common ("the",
// "can") the same defect passes everything instead; severity varied,
// the misextraction was constant.
const NON_GENUS_QUESTION_WORDS = new Set([
  // auxiliaries and modals
  "has", "have", "had", "does", "did", "can", "could", "may", "might",
  "must", "shall", "should", "will", "would", "are", "was", "were",
  "been", "being",
  // interrogatives
  "how", "what", "why", "when", "where", "which", "who", "whom", "whose",
]);
const NON_SPECIES_FUNCTION_WORDS = new Set([
  // pronouns
  "anyone", "anybody", "someone", "somebody", "everyone", "everybody",
  "nobody", "anything", "something", "everything", "nothing",
  "they", "them", "him", "his", "her", "hers", "its", "one", "ones",
  // auxiliaries, modals, interrogatives: the same closed classes as
  // NON_GENUS_QUESTION_WORDS (pairs like "Plants can", "Studies show how")
  "has", "have", "had", "does", "did", "can", "could", "may", "might",
  "must", "shall", "should", "will", "would", "are", "was", "were",
  "been", "being",
  "how", "what", "why", "when", "where", "which", "who", "whom", "whose",
  // taxonomic rank words: the epithet is never the word for the rank
  "species", "genus",
]);

export function extractBinomial(raw) {
  const s = raw.trim();
  // Common non-taxonomic word pairs that fit the pattern
  const commonNonTaxonomic = new Set([
    "black soldier", "climate change", "gene expression", "cell division",
    "protein folding", "public health", "food security", "human genome",
    "narrow leafed", "cotton wood", "peer reviewed", "open source",
  ]);
  // Iterate through ALL matches, pick the first that looks taxonomic. This
  // means "Evolution of narrow leafed cotton wood trees Populus angustifolia"
  // correctly finds "Populus angustifolia" (title-cased), not "narrow leafed".
  const re = /\b([A-Z][a-z]{2,}|[a-z]{3,})\s+([a-z]{3,})\b/g;
  const hasTaxMarker = /\b(species|genus|subsp\.|var\.|cultivar|strain|clade|sp\.)\b/i.test(s);
  let m;
  while ((m = re.exec(s)) !== null) {
    const test = m[0].toLowerCase();
    if (commonNonTaxonomic.has(test)) continue;
    if (NON_GENUS_FIRST_WORDS.has(m[1].toLowerCase()) || NON_SPECIES_SECOND_WORDS.has(m[2].toLowerCase())) continue;
    if (NON_GENUS_QUESTION_WORDS.has(m[1].toLowerCase()) || NON_SPECIES_FUNCTION_WORDS.has(m[2].toLowerCase())) continue;
    // Reject ordinary English words even when sentence-initial capitalization
    // makes them LOOK taxonomic. Without this guard, every question starting
    // "Can you...", "Compare the...", "Does the..." etc. (i.e. nearly every
    // question a user types) matches the FIRST word pair, is treated as a
    // genus+species, and permanently hijacks organism detection before the
    // regex ever reaches the real binomial later in the sentence. This was a
    // live production bug: "Compare the microbial diversity ... in Hermetia
    // illucens ..." returned {genus:"Compare", species:"the"} and searched
    // every engine for the literal phrase "Compare the" instead of the
    // organism, then passed its own broken species-gate because "the"
    // appears in virtually every abstract ever written.
    if (STOPWORDS.has(m[1].toLowerCase()) || STOPWORDS.has(m[2].toLowerCase())) continue;
    const looksTaxonomic = /^[A-Z]/.test(m[1]) || hasTaxMarker;
    if (!looksTaxonomic) continue;
    const genus = m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase();
    return { genus, species: m[2], full: genus + " " + m[2] };
  }
  return null;
}

// Looks like a person's name: 2-3 capitalized-word tokens, all letters.
// Used to trigger author-specific search paths.
/* ══════════════════════════════════════════════════════════════════
   Commit 97 . "Nuclear Fission" was being searched as a person.

   This test was pure SHAPE: two to four capitalised tokens meant a name.
   "Nuclear Fission" fits that perfectly, and so does "Machine Learning",
   "Quantum Computing", "Black Holes", "Dark Matter", "Gene Editing" and a
   very large fraction of every topic anyone would actually type. The
   reported case returned "no papers authored by Nuclear Fission" and zero
   sources, which is about as broken as a search can look.

   The old defence was NAME_STOPWORDS, a hand-written list of a couple of
   dozen words. A blocklist can never cover the space of scientific topics,
   and every miss is a dead-end search.

   The real signal is much simpler: the FIRST token of a person's name is a
   given name, and given names are essentially never ordinary English nouns
   or adjectives. "Nuclear", "Machine", "Quantum", "Black", "Deep", "Green"
   all are. "Marie", "Reese", "Zachary", "Hiroshi" all are not. So instead
   of listing topics, list the far smaller and far more stable set of
   common words that can open a topic phrase, and reject on those.

   This deliberately also rejects "Green Chemistry" and "Bell Labs", which
   is correct: neither is a person. It keeps "John Miller" because the
   FIRST token is what is tested, and "john" is not a common noun. */
const TOPIC_OPENERS = new Set([
  // question and function words
  "how","what","why","when","where","who","which","does","do","is","are","can",
  "the","a","an","this","that","these","those","using","use","about","for","in",
  "on","of","with","and","or","not","new","recent","latest","best","top","any",
  // physical / chemical
  "nuclear","atomic","quantum","thermal","optical","magnetic","electric","electrical",
  "solar","plasma","laser","photonic","acoustic","seismic","fluid","particle",
  "fission","fusion","radiation","radioactive","superconducting","semiconductor",
  "chemical","organic","inorganic","polymer","catalytic","molecular","crystal",
  // life sciences
  "gene","genetic","genomic","protein","cell","cellular","stem","immune","neural",
  "microbial","bacterial","viral","fungal","enzyme","metabolic","clinical","dietary",
  "cancer","tumor","tumour","brain","heart","liver","kidney","lung","blood","bone",
  "gut","skin","muscle","plant","animal","insect","marine","soil","water","food",
  // computation
  "machine","deep","artificial","neural","computer","computational","digital","data",
  "algorithm","algorithmic","software","network","quantum","robotic","autonomous",
  // earth / environment
  "climate","environmental","ecological","atmospheric","oceanic","renewable",
  "sustainable","carbon","waste","energy","green","urban","agricultural",
  // general descriptors that open topics
  "black","white","red","blue","dark","light","high","low","large","small","long",
  "short","fast","slow","early","late","modern","ancient","human","social","public",
  "global","local","natural","artificial","advanced","basic","applied","general",
  "bell","big","open","closed","hot","cold","wet","dry","solid","liquid","gas",
]);

function looksLikePersonName(raw) {
  const s = raw.trim();
  if (!s) return false;
  // A Latin binomial has the shape of "Firstname Lastname" and is not a person.
  if (extractBinomial(raw)) return false;
  const toks = s.split(/\s+/);
  if (toks.length < 2 || toks.length > 4) return false;
  // Every token must look like a name part: capitalised letters, or an initial.
  const isNamey = toks.every((t) => /^[A-Z][a-zA-Z'\-]+\.?$/.test(t) || /^[A-Z]\.?$/.test(t));
  if (!isNamey) return false;
  // The decisive test: a given name is not an ordinary English word.
  if (TOPIC_OPENERS.has(toks[0].toLowerCase())) return false;
  // Nor is any later token, unless it is a plausible surname. A second token
  // that is a common topic word ("... Learning", "... Fission") means the
  // phrase is a subject, not a person.
  if (toks.some((t, i) => i > 0 && TOPIC_OPENERS.has(t.toLowerCase()))) return false;
  return true;
}

// Words that are NEVER person surnames or first names, even though they might
// appear capitalized in a query. Used to filter out topic words when hunting
// for a name embedded inside a longer sentence.
const NAME_STOPWORDS = new Set([
  "BSFL", "DNA", "RNA", "CRISPR", "PCR", "PhD", "MD", "UTK", "MIT", "NIH",
  "USA", "UK", "US", "EU", "FDA", "CDC", "WHO", "NASA", "The", "This", "That",
  "These", "Those", "Black", "Soldier", "Fly", "Larvae",
]);

// Try to extract a person's name from ANY query, even if wrapped in extra words.
// Classifies whether a user's message is a NEW topic search, a FOLLOW-UP
// about the previous answer, or a CORRECTION to a prior fact. This decides
// whether to fire a fresh scholarly search or reuse the previous turn's
// sources and just re-prompt the AI with the new user turn.
//
// Signals for FOLLOW-UP: pronouns/deictics referring back ("that paper",
// "this study", "the finding", "it", "they"), agreement/refinement openers
// ("yes", "actually", "no it's", "wait", "you said"), meta comments about
// the previous answer ("the main point was", "you missed", "focus on"),
// or short messages (<= 8 words) that don't introduce new proper nouns.
//
// Signals for CORRECTION: explicit corrections ("that's wrong", "actually
// she's at", "not X but Y", "you got X wrong", "correction:"), or a
// short message negating something in the previous answer.
//
// Signals for NEW: introduces a new proper noun or Latin binomial not in
// history, starts with a fresh question word ("what/how/why/when/where"),
// or is long enough (>10 words) with clear new topic content.
function classifyIntent(query, history) {
  const q = (query || "").trim();
  if (!q) return { kind: "new" };
  const lc = q.toLowerCase();
  const wc = q.split(/\s+/).length;
  const hasHistory = Array.isArray(history) && history.length > 0;
  if (!hasHistory) return { kind: "new" };

  // Explicit correction phrases
  const correctionPatterns = [
    /^(that|this|it)['']?s\s+(wrong|incorrect|not right|false)/i,
    /^(actually|no,?\s+it['']?s|no,?\s+they['']?re|correction[:,])/i,
    /you\s+(got|had|were)\s+(that|this|it)\s+wrong/i,
    /^wrong\b/i,
    /^not\s+\w+,?\s+(it['']?s|they['']?re|but)\s+/i,
    /\bthat['']?s\s+not\s+(right|correct|true|him|her|them)/i,
    /\bnot\s+\w+\s+but\s+/i,
    /you\s+(said|mentioned|wrote)\s+.+\s+(but|however|actually)\s+/i,
  ];
  for (const re of correctionPatterns) {
    if (re.test(q)) return { kind: "correction" };
  }

  // Follow-up indicators
  const followupOpeners = /^(yes|no|but|and|so|okay|ok|right|hmm|well|wait|hey)\b/i;
  const backReferences = /\b(that\s+(papers?|stud(?:y|ies)|research|works?|findings?|results?|authors?|persons?|one)|this\s+(papers?|stud(?:y|ies)|research|works?|findings?|results?)|the\s+(papers?|stud(?:y|ies)|research|works?|findings?|results?|authors?|persons?|one|main\s+point|main\s+finding|sources?|citations?|references?)|it|its|they|them|their|he|she|his|her|him)\b/i;
  const metaAboutPrevious = /\b(you\s+(said|mentioned|wrote|missed|forgot|focused|talked)|main\s+point|main\s+finding|focus\s+on|more\s+about|tell\s+me\s+more|expand|elaborate|clarify|what\s+about|and\s+what|what\s+does|what\s+did|explain\s+more|dig\s+deeper|go\s+deeper|where\s+(are|were)\s+the\s+(papers?|sources?|stud(?:y|ies)|citations?|references?)|show\s+me\s+the\s+(papers?|sources?|citations?)|list\s+the\s+(papers?|sources?|citations?)|what\s+(papers?|sources?|citations?)\s+(did|do|were|are))\b/i;
  const shortReply = wc <= 8;

  const hasBackRef = backReferences.test(q);
  const isFollowupOpener = followupOpeners.test(q);
  const isMeta = metaAboutPrevious.test(q);

  // Check whether the message introduces significant new proper nouns
  // (capitalized words the history doesn't contain). If it does, it's likely
  // a new topic even if it also has pronouns.
  const historyText = history
    .map((t) => (t && t.content) || "")
    .join(" ")
    .toLowerCase();
  const newProperNouns = q
    .split(/\s+/)
    .filter((w) => /^[A-Z][a-z]{2,}$/.test(w))
    .filter((w) => !historyText.includes(w.toLowerCase()));
  const introducesNewTopic = newProperNouns.length >= 2; // 2+ new capitalized words = probably new topic

  if (introducesNewTopic) return { kind: "new" };

  // `meta: true` marks the highest-confidence followup signal . the user is
  // explicitly commenting on the PREVIOUS turn ("you forgot...", "you
  // missed...", "focus on...", "tell me more"), not stating a new topic.
  // Downstream, this is used to stop a cruder word-overlap heuristic from
  // overriding this classification just because the complaint's wording
  // happens to share few words with the original query . which it usually
  // will, since "you forgot to provide BSFL papers" is ABOUT the omission,
  // not a restatement of the topic.
  if (isMeta || (hasBackRef && (isFollowupOpener || shortReply))) {
    return { kind: "followup", meta: isMeta };
  }
  if (isFollowupOpener && shortReply) return { kind: "followup", meta: false };

  return { kind: "new" };
}

// ── QUESTION-TYPE CLASSIFICATION (2026-10-07 search-intelligence upgrade) ──
// What KIND of answer does the user want? This is the missing layer between
// intent ("new search" vs "followup") and retrieval: a definition question
// ("what is CRISPR") needs a definition fast path, a comparison question
// ("X vs Y") needs side-by-side framing, a methods question needs protocols.
// Pattern-based and deterministic . runs before any LLM call, costs nothing,
// and feeds the definition fast path + smart follow-up suggestions.
// Returns { type, term } where term is the defined/compared entity when the
// type has one (definition, comparison).
// ═══════════════════════════════════════════════════════════════
// METHOD INTENT (2026-10-14): a measurement question asks HOW a
// quantity is measured . the operative verb is a measurement
// verb (measured, assayed, determined, quantified, estimated,
// detected, assessed), or the question names the method itself
// ("what is the assay for X"). Dusty's live manganese
// peroxidase answer was "completely wrong" because nothing in
// the pipeline knew this: the question "How can the activity of
// manganese peroxidase be measured?" classified as "general",
// the cited shelf filled with production and optimization
// papers that merely REPORT activity values, and the papers
// that actually answer it ("Improvements in the determination
// of manganese peroxidase activity", "Criteria for Estimation
// of ...") sat uncited in further reading or were cited
// without their content ever being used. A paper that reports
// a value of the quantity is not an answer to how the quantity
// is measured. The machinery below makes the intent a recorded
// fact (analyzeQuery's intent field), gives the method
// vocabulary a first class concept group of its own, and lets
// the shelf selection, the extractive builder, the limits, and
// the synthesis prompt all key off it.
// ═══════════════════════════════════════════════════════════════

// The method concept group: the vocabulary of ABOUTNESS for
// measurement. In CONCEPT_GROUPS style (a flat set of terms),
// but judged by paperMethodTier below rather than by raw
// membership: a production paper's abstract can mention an
// "assay" in passing, so membership alone is not aboutness —
// the strong sense is a title or abstract that is ABOUT
// measuring the quantity (determination of, estimation of,
// assay for, method for measuring).
export const METHOD_CONCEPT_GROUP = new Set([
  "assay", "assays", "determination", "estimation", "quantification",
  "measurement", "measuring", "spectrophotometric", "spectrophotometry",
  "colorimetric", "calibration", "absorbance", "protocol", "method",
]);

const MEASUREMENT_VERB_RE =
  "measured|measure|assayed|assay|determined|determine|quantified|quantify|estimated|estimate|detected|detect|assessed|assess|evaluated|evaluate|monitored|monitor";

// Deterministic measurement intent: the measurement verb is
// the question's operative verb. Patterns, in order:
//   "how is/are/can X measured ..." (any how question carrying
//     a measurement verb: "how do researchers quantify X" is
//     the same shape with the verb in base form);
//   "how to measure X";
//   "what/which method/assay/technique/protocol ...";
//   a bare methods topic ("measurement of X", "determination
//     of X", "quantification of X").
// ONE INTENT RESOLVER (2026-10-23, logic audit L1-3). The
// detector below used to be a list of textbook surface shapes:
// a measurement verb from a fixed list, in a fixed word order.
// Plain phrasings of the same ask (check, test, working, strong,
// active) fell outside the list, so the switch that makes method
// papers lead stayed off and a value reporting answer was the
// designed outcome. The resolver now reads the question's
// OPERATIVE RELATION instead: is a determination procedure for
// some quantity, activity, or state being requested? The
// signals, any one of which is enough, are: a determination
// verb (the textbook list plus check, test, tell, and know in
// their determination uses), a named method noun (assay, test,
// protocol, procedure, measurement) anywhere the question names
// it as the thing asked for, a quantity adjective in the asked
// position (how active, how strong, how effective), or a state
// check (whether or if some thing is working, active, alive,
// pure, or strong). detectMeasurementIntent is this resolver's
// boolean, and every consumer (the analysis, the question type,
// the shelf order, the synthesis, the handler) reads that one
// function, so no consumer can hold a second private detector.
const MEASUREMENT_QUANTITY_WORDS =
  "working|works|active|activity|effective|effectiveness|potent|potency|strong|strength|alive|pure|purity|concentrated|concentration";
export function resolveMeasurementIntent(query) {
  const lc = String(query || "").toLowerCase().replace(/\s+/g, " ").trim();
  if (!lc) return { measurement: false, signal: null };
  if (new RegExp("\\bhow\\b[^?]*\\b(?:" + MEASUREMENT_VERB_RE + ")\\b").test(lc)) {
    return { measurement: true, signal: "measurement verb" };
  }
  if (/\bhow\s+to\s+(?:measure|assay|determine|quantify|estimate|detect|assess|check|test)\b/.test(lc)) {
    return { measurement: true, signal: "how to determination verb" };
  }
  if (/^(?:what|which)\s+(?:is\s+the\s+|are\s+the\s+)?(?:method|methods|technique|techniques|assay|assays|protocol|protocols|procedure|procedures)\b/.test(lc)) {
    return { measurement: true, signal: "named method" };
  }
  if (/\b(?:measurement|quantification|determination)\s+of\b/.test(lc)) {
    return { measurement: true, signal: "measurement of" };
  }
  // Plain phrasings (2026-10-21, search fix wave, Lane A): the
  // Oct 20 audit's two manganese peroxidase phrasings both
  // returned intent null, so the method lane never fired, the
  // cited shelf was never method ordered, and the answer cited
  // production papers only. Neither phrasing carries a listed
  // measurement verb: one asks "what test tells you how active
  // X is" (the word "test" is the asker's name for the assay,
  // and "active" is the quantity), the other asks "how do lab
  // people actually check if the enzyme is working" (the verb
  // is "check", the quantity is whether it is working). The
  // patterns below are that shape and only that shape: a what
  // or which TEST opening, a how question whose check, test,
  // tell, or know verb is paired with a working or active
  // outcome word, or a direct "how active is X" ask. A bare
  // "how does X work" carries none of the outcome words and
  // stays a mechanism question, untouched.
  if (/^(?:what|which)\s+(?:test|tests|assay|assays)\b/.test(lc)) {
    return { measurement: true, signal: "named test" };
  }
  if (new RegExp("\\bhow\\b[^?]*\\b(?:check|test|tell|know)\\b[^?]*\\b(?:" + MEASUREMENT_QUANTITY_WORDS + ")\\b").test(lc)) {
    return { measurement: true, signal: "check or test with quantity word" };
  }
  if (/\bhow\s+(?:active|effective|potent|strong)\s+is\b/.test(lc)) {
    return { measurement: true, signal: "how quantity adjective is" };
  }
  // The standard assay ask (2026-10-21, search fix wave, Lane A,
  // second pass on the completed before batch): probe 12, "what
  // is the standard lab assay for manganese peroxidase
  // activity", still returned intent null after the patterns
  // above. The method word is present but not adjacent to the
  // opening: "is the standard lab assay" puts three words
  // between "what" and "assay", so both the original method
  // opening (assay must follow "is the" directly) and the plain
  // test opening (test must follow "what" directly) miss it.
  // The question classified as a definition, the foundational
  // method lane never fired, one rung ran, and the pool filled
  // with nanozyme biosensing papers that match assay plus
  // manganese as loose words. The shape here is a what or which
  // opening whose question names an assay, method, test, or
  // protocol anywhere in it: that naming IS the method ask,
  // wherever in the sentence it sits. A what question naming
  // none of those words ("what is manganese peroxidase") is
  // untouched, exactly as before.
  if (/^(?:what|which)\b[^?]*\b(?:assay|assays|method|methods|test|tests|protocol|protocols|procedure|procedures)\b/.test(lc)) {
    return { measurement: true, signal: "named method anywhere" };
  }
  // Operative relation shapes (2026-10-23, L1-3): the plain
  // determination asks the verb lists still missed. A how
  // question whose operative verb is check or test asks for a
  // determination procedure by itself, whatever quantity word
  // follows ("how do you check if honey is pure", "how would
  // you test the water"). A check, test, tell, or know paired
  // with an if or whether clause naming a working state asks
  // the same thing ("how can you tell whether the enzyme still
  // works"). And a what or which CHECK opening names the
  // procedure the way the test opening does. The mechanism
  // controls stay safe: "how does a steam engine work" and
  // "how do bees make honey" carry no determination verb, no
  // method noun, and no quantity word in the asked position.
  if (/\bhow\b[^?]*\b(?:check|test|checking|testing|tested|checked)\b/.test(lc)) {
    return { measurement: true, signal: "how check or test" };
  }
  if (new RegExp("\\b(?:check|test|tell|know|determine|measure)\\b[^?]*\\b(?:if|whether)\\b[^?]*\\b(?:" + MEASUREMENT_QUANTITY_WORDS + ")\\b").test(lc)) {
    return { measurement: true, signal: "whether state check" };
  }
  if (/^(?:what|which)\s+(?:check|checks)\b/.test(lc)) {
    return { measurement: true, signal: "named check" };
  }
  return { measurement: false, signal: null };
}

export function detectMeasurementIntent(query) {
  // The one resolver (2026-10-23, L1-3): every consumer reads
  // this boolean, which is resolveMeasurementIntent's verdict
  // and nothing else.
  return resolveMeasurementIntent(query).measurement;
}

// MECHANISM SHAPE (2026-10-14, wave nine): a mechanism question
// asks HOW a process happens . what binds what, what changes,
// what is cut, built, released, or detected, and in what order.
// Grok's audit found this shape failing intermittently on live
// runs of "how does crispr cas9 actually cut dna": the
// foundational primary paper (Jinek 2012, the first description
// of the cutting mechanism) was never retrieved at all, and on
// a fresh run an application paper (lipid nanoparticle
// delivery) rotated into the mechanism answer's top sources.
// Nothing in the pipeline knew this shape the way the machinery
// above knows measurement, so nothing could prefer the papers
// that describe the process, keep application only papers out
// of the cited set, or tell the synthesis to open with the
// mechanism itself. The machinery below mirrors the measurement
// machinery: a recorded shape (analyzeQuery's mechanismShape
// field), an engagement tier judged on the paper, a citation
// standard term, a foundational lane in retrieval, a shelf
// order, and a synthesis contract.

// The mechanism concept vocabulary: the words of process
// aboutness. Judged by paperMechanismTier below rather than by
// raw membership, for the same reason METHOD_CONCEPT_GROUP is:
// a delivery paper's abstract can mention a "receptor" in
// passing, so membership alone is not aboutness.
export const MECHANISM_ENGAGEMENT_WORDS = [
  "mechanism", "cleavage", "cleave", "cut", "guide", "binding", "bind",
  "recognition", "unwind", "anneal", "denaturation", "amplify", "amplifies",
  "amplified", "amplification", "polymerase", "primer", "template", "strand",
  "nick", "nuclease", "endonuclease", "catalytic", "catalysis", "hydrolysis",
  "conformational", "domain", "structure", "structural", "detection",
  "detect", "detects", "antibody", "antigen", "transfer", "membrane",
  "signal", "signaling", "activation", "activate", "activates",
  "phosphorylation", "assembly", "folding", "secretion", "transport",
  "channel", "receptor", "enzyme", "reaction", "separation", "melting",
  "hybridization", "probe", "fragment", "step", "process",
];

// One regex over the vocabulary: word boundary, any listed
// word, an optional inflection suffix, then a word boundary
// again. The trailing boundary after the optional suffix is
// load bearing: without it "cut" would match inside
// "cutaneous" and "anneal" inside longer unrelated words, and
// the tier would credit engagement the paper never made.
export const MECHANISM_WORD_RE = new RegExp(
  "\\b(?:" + MECHANISM_ENGAGEMENT_WORDS.join("|") + ")(?:s|es|ed|ing|tion)?\\b",
  "gi");

// The distinct vocabulary words a text engages, canonicalized
// to the listed word each match came from (the longest listed
// prefix wins, so "signaling" counts as signaling and not also
// as signal). Distinctness is the unit paperMechanismTier
// counts at abstract level: two different process words are
// engagement; one word repeated is a mention.
function mechanismWordsIn(text) {
  const found = new Set();
  const src = String(text || "");
  if (!src) return found;
  MECHANISM_WORD_RE.lastIndex = 0;
  const matches = src.match(MECHANISM_WORD_RE) || [];
  for (const rawMatch of matches) {
    const m = String(rawMatch || "").toLowerCase();
    if (!m) continue;
    let best = null;
    for (const w of MECHANISM_ENGAGEMENT_WORDS) {
      if (m === w) { best = w; break; }
      if (m.startsWith(w)) {
        const rest = m.slice(w.length);
        if ((rest === "s" || rest === "es" || rest === "ed" || rest === "ing" || rest === "tion")
          && (!best || w.length > best.length)) best = w;
      }
    }
    if (best) found.add(best);
  }
  return found;
}

// Title level engagement (tier 2): the paper IS about a
// process . its title carries a mechanism word. Abstract level
// (tier 1): the abstract engages at least TWO DISTINCT
// mechanism words . a single passing mention is not
// engagement, mirroring paperMethodTier's reasoning that
// membership is not aboutness. Tier 0: no mechanism signal .
// the paper may apply, deliver, or report on the system, which
// for a mechanism question makes it background at best.
export function paperMechanismTier(paper) {
  const p = paper || {};
  if (mechanismWordsIn(p.title || "").size >= 1) return 2;
  const abs = usableAbstract(p) || "";
  if (abs && mechanismWordsIn(abs).size >= 2) return 1;
  return 0;
}

// The process verbs a how question carries when it is asking
// about a mechanism: the system DOES something (cuts, binds,
// unwinds, detects, pumps), and the question asks how.
// WAVE ELEVEN (2026-10-14, parent live probe on the wave ten
// build): the set also carries the COPYING family and the
// phrase "make more". The wave nine acceptance wording "how
// does pcr amplify dna" fired the foundational lane live,
// but the same question in plain mismatched words — "how
// does pcr make more copies of dna" — did not: no listed
// verb appears in it (make is not listed, copies is a noun
// there, amplify is the papers' word the asker did not use).
// The copying family (copy, replicate, duplicate, multiply)
// and "make(s) more" are how a person phrases a copying
// mechanism without the literature's vocabulary. Bare "make"
// stays unlisted on purpose: "how does the council make
// decisions" is not a mechanism question, and it still does
// not fire.
const MECHANISM_PROCESS_VERB_RE =
  "works?|cuts?|cutting|amplif(?:y|ies|ied)|detect(?:s|ed)?|trigger(?:s|ed)?|cleave(?:s|d)?|breaks? down|binds?|unwinds?|anneals?|denatures?|activates?|produces?|releases?|converts?|opens?|closes?|pumps?|fires?|makes? more|cop(?:y|ies|ied|ying)|replicat(?:e|es|ed|ing|ion)|duplicat(?:e|es|ed|ing|ion)|multipl(?:y|ies|ied|ying)";

// Deterministic mechanism shape: true when the question is a
// how question carrying a process verb ("how does crispr cas9
// actually cut dna", "how does pcr amplify dna", "how does the
// heart pump blood"), or it names the mechanism outright
// ("mechanism of dna replication", or a how, what, or why
// question containing the word mechanism). Not every how
// question qualifies: "what are the ethics of crispr gene
// editing" has no process verb and no mechanism word, "does
// crispr delivery work in patients" never pairs how with a
// process verb, and "how is manganese peroxidase activity
// measured" is measurement only . "measured" is deliberately
// not a mechanism verb. A question can be BOTH shapes: "how
// does a western blot detect proteins" is a mechanism question
// (detect is a process verb) and a measurement question, and
// neither detector suppresses the other.
export function isMechanismShapeQuery(query) {
  const lc = String(query || "").toLowerCase().replace(/\s+/g, " ").trim();
  if (!lc) return false;
  if (new RegExp("\\bhow\\b[^?]*\\b(?:" + MECHANISM_PROCESS_VERB_RE + ")\\b").test(lc)) return true;
  if (/\bmechanism of\b/.test(lc)) return true;
  if (/^(?:how|what|why)\b/.test(lc) && /\bmechanism\b/.test(lc)) return true;
  return false;
}

// APPLICATION AND DELIVERY VOCABULARY (2026-10-14, wave nine):
// the words of use, not of process . a paper speaking only this
// vocabulary is about delivering, treating with, or testing a
// system in patients, not about how the system works. Same
// construction as MECHANISM_WORD_RE above, trailing boundary
// included for the same reason.
export const APPLICATION_DELIVERY_WORDS = [
  "delivery", "deliver", "delivers", "delivered", "nanoparticle",
  "nanoparticles", "therapeutic", "therapeutics", "in vivo", "efficacy",
  "clinical", "patient", "patients", "pharmacokinetic", "toxicity",
  "transfection", "treatment", "treatments",
];

export const APPLICATION_DELIVERY_RE = new RegExp(
  "\\b(?:" + APPLICATION_DELIVERY_WORDS.map((w) => w.replace(/\s+/g, "\\s+")).join("|") + ")(?:s|es|ed|ing|tion)?\\b",
  "i");

// An application only paper: its title and abstract engage at
// least one application or delivery word AND its mechanism
// tier is 0 . no process engagement at all. The citation
// standard below uses this for tail discipline on mechanism
// questions: the measured failure was a lipid nanoparticle
// delivery paper, heavy on exactly this vocabulary and silent
// on cleavage, binding, and every other process word, rotating
// into a mechanism answer's cited set on concept touches
// alone.
export function paperApplicationOnly(paper) {
  const p = paper || {};
  const hay = String(p.title || "") + " " + (usableAbstract(p) || "");
  if (!APPLICATION_DELIVERY_RE.test(hay)) return false;
  if (paperMechanismTier(p) === 0) return true;
  // WAVE TEN (2026-10-14, item 4 evidence): the wave nine rule
  // let the live probe's lipid nanoparticle paper through,
  // cited at position 2, because its abstract mentions process
  // words while reporting the outcomes of what it delivered.
  // The narrower distinction the evidence supports: that
  // paper's TITLE is delivery framed AND states an application
  // purpose ("...delivery of CRISPR-Cas9 RNP versus mRNA/sgRNA
  // for gene editing") while carrying no mechanism word. A
  // delivery framed paper whose abstract genuinely engages the
  // mechanism (the wave nine binding and membrane fixture)
  // keeps its tier 1 rescue — only the purpose stated delivery
  // title is decisive.
  const title = String(p.title || "");
  if (APPLICATION_DELIVERY_RE.test(title) && mechanismWordsIn(title).size === 0 &&
      /\bfor\s+(?:\w+\s+){0,2}?(?:editing|therapy|therapeut\w*|treatment|delivery|clinical\s+use)\b/i.test(title)) return true;
  return false;
}

// Title level aboutness (tier 2): the paper IS a method paper .
// its title announces the determination, the estimation, the
// assay, or a method for measuring. Abstract level (tier 1):
// the method markers or an explicit "activity was measured /
// determined / assayed" procedure statement appear in the
// abstract . the paper describes measuring even when its
// headline is something else. Tier 0: no method signal . the
// paper may report the quantity's values, which for a
// measurement question makes it supporting at best.
const METHOD_TITLE_RE = new RegExp(
  "\\b(?:determination|estimation|quantification|measurement)\\s+of\\b" +
  "|\\bassays?\\b" +
  "|\\bmethods?\\s+(?:for|of|to)\\s+(?:measur|determin|estimat|quantif|assay)" +
  "|\\b(?:improvements?|advances?|criteria|comparison|evaluation|validation)\\s+(?:in|of|for)\\s+(?:the\\s+)?(?:determination|estimation|quantification|measurement|assays?)\\b" +
  "|\\b(?:measuring|determining|quantifying|assaying)\\b[^.]*\\b(?:activity|concentration|levels?)\\b",
  "i");
const METHOD_ABSTRACT_RE = new RegExp(
  "\\bactivity\\s+(?:was|were|is|has been)\\s+(?:measured|determined|assayed|estimated|quantified)\\b" +
  "|\\b(?:measured|determined|assayed|estimated|quantified)\\s+(?:by|using|via)\\b[^.]*\\b(?:spectrophotometr|absorbance|colorimetr)" +
  "|\\bassays?\\s+(?:was|were|is)\\s+(?:performed|carried out|based)\\b",
  "i");

export function paperMethodTier(paper) {
  const p = paper || {};
  if (METHOD_TITLE_RE.test(String(p.title || ""))) return 2;
  const abs = usableAbstract(p) || "";
  if (abs && (METHOD_TITLE_RE.test(abs) || METHOD_ABSTRACT_RE.test(abs))) return 1;
  return 0;
}

// The cited shelf for a measurement question: method papers
// lead. Papers the relevance gate already cleared but the
// maxEvidence slice left out are pulled in ahead of the
// shelf's non method tail (the shelf size does not grow, and
// nothing that failed the gate is ever pulled), then the
// whole shelf is stably ordered title method papers first,
// abstract method papers next, the rest in their ranked
// order . so citation [1] is a method paper whenever the
// pool holds one.
export function orderShelfForMeasurement(shelf, gatedPool) {
  const list = Array.isArray(shelf) ? shelf.slice() : [];
  if (list.length === 0) return list;
  if (Array.isArray(gatedPool)) {
    const inShelf = new Set(list);
    const extras = gatedPool.filter((p) => p && !inShelf.has(p) && paperMethodTier(p) > 0);
    // Title level pulls before abstract level; pool order
    // (the gate's ranked order) inside each level.
    extras.sort((a, b) => paperMethodTier(b) - paperMethodTier(a));
    for (const extra of extras) {
      let idx = -1;
      for (let i = list.length - 1; i >= 0; i--) {
        if (paperMethodTier(list[i]) === 0) { idx = i; break; }
      }
      if (idx < 0) break;
      list.splice(idx, 1);
      list.push(extra);
    }
  }
  const tiered = list.map((p, i) => ({ p, i, t: paperMethodTier(p) }));
  tiered.sort((a, b) => (b.t - a.t) || (a.i - b.i));
  return tiered.map((x) => x.p);
}

// FOUNDATIONAL PRIMARIES (2026-10-14, wave nine): the first
// description papers of a mechanism or a method . Jinek 2012
// for CRISPR cutting is the measured case. They are identified
// by signals, never by a hardcoded per topic list (a seed list
// would rot): the paper engages the mechanism or the method
// (either tier above 0), it is EARLY (2016 or before, the era
// of the canonical first descriptions this wave was measured
// against, or inside the earliest third of the pool's own
// years when the pool runs older or younger), and it is CITED
// at or above the pool's own median . a first description the
// field actually built on, not an obscure early note. The
// pool relative terms keep the standard honest on any topic:
// what counts as early and well cited is read off the papers
// actually gathered for the question.
export function foundationalPoolStats(papers) {
  const list = Array.isArray(papers) ? papers : [];
  const cites = list
    .map((p) => (p && typeof p.citations === "number" && Number.isFinite(p.citations) ? p.citations : 0))
    .sort((a, b) => a - b);
  let medianCitations = 0;
  if (cites.length > 0) {
    const mid = Math.floor(cites.length / 2);
    medianCitations = cites.length % 2 === 1
      ? cites[mid]
      : (cites[mid - 1] + cites[mid]) / 2;
  }
  const years = list
    .map((p) => {
      const m = String((p && p.year) || "").match(/(?:19|20)\d{2}/);
      return m ? parseInt(m[0], 10) : NaN;
    })
    .filter((y) => Number.isFinite(y))
    .sort((a, b) => a - b);
  const earlyYearCutoff = years.length > 0
    ? years[Math.min(years.length - 1, Math.floor(years.length / 3))]
    : 2016;
  return { medianCitations, earlyYearCutoff };
}

export function paperIsFoundationalPrimary(paper, stats) {
  const p = paper || {};
  if (paperMechanismTier(p) === 0 && paperMethodTier(p) === 0) return false;
  const yearMatch = String(p.year || "").match(/(?:19|20)\d{2}/);
  if (!yearMatch) return false;
  const year = parseInt(yearMatch[0], 10);
  const s = stats || { medianCitations: 0, earlyYearCutoff: 2016 };
  if (!(year <= 2016 || year <= s.earlyYearCutoff)) return false;
  const citations = typeof p.citations === "number" && Number.isFinite(p.citations) ? p.citations : 0;
  if (!(citations > 0)) return false;
  return citations >= Math.max(1, s.medianCitations);
}

// THE FOUNDING FORM (2026-10-14, wave fifteen): the lane's
// primary query is built for breadth — the expanded organism
// term, the top ranked terms, and the shape's vocabulary — and
// that breadth is exactly what the first descriptions cannot
// survive. Probed live on the lane's own legs for "how does
// crispr cas9 cut dna": the nine term query's Europe PMC match
// set holds 95 papers and the 2012 founding paper is not among
// them (its abstract says "cleave" and "guide"; it never says
// the expansion "Deoxyribonucleic acid", "mechanism", or
// "cut", and the engines match the loaded query against title
// and abstract), and OpenAlex's match set excludes it the same
// way. The paper is indexed under the system's own name, in
// the words the field itself used first. The founding form is
// that name as the asker wrote it, unexpanded: the question's
// subject concept (questionCentralConcepts' own subject
// judgment, the same one the gates trust), plus the surface
// token that follows it when that token is a content word and
// not a process verb — the system's name often runs to two
// words ("crispr cas9", "manganese peroxidase"), while the
// verb that follows it ("cut") is one of the words that
// excludes the first description. Both engines return the
// founding paper second under this form, citation sorted.
export function foundationalFormQuery(rawQuery, dynLookup) {
  try {
    const concepts = questionCentralConcepts(rawQuery, dynLookup);
    if (!Array.isArray(concepts) || concepts.length === 0) return null;
    const subject = concepts.find((c) => c && c.subject && c.term)
      || concepts.find((c) => c && c.term);
    if (!subject) return null;
    const term = String(subject.term || "").replace(/"/g, "").trim().toLowerCase();
    if (!term) return null;
    let form = term;
    // The adjacency scan reads the asker's own surface words,
    // not the preprocessed query: preprocessing rewrites and
    // compounds terms (it can fuse the system's name into a
    // hyphenated compound), which is expansion by another name.
    const tokens = cleanSurfaceQuery(rawQuery).split(/\s+/).filter(Boolean);
    const idx = tokens.indexOf(term);
    if (idx >= 0 && idx + 1 < tokens.length) {
      const next = tokens[idx + 1];
      if (next && next !== term && next.length > 2
        && !isGateFunctionWord(next)
        && !new RegExp("^(?:" + MECHANISM_PROCESS_VERB_RE + ")$").test(next)
        && !/^(?:measure|measured|measures|measuring|assay|assays|assayed|determine|determined|determines|quantify|quantified|activity)$/.test(next)) {
        form = term + " " + next;
      }
    }
    return form;
  } catch { return null; }
}

// The question's named subject phrase for the method leg
// (2026-10-21, search diagnosis): the longest multi word concept
// group member the question's own text contains. The concept
// groups already carry the subjects the literature phrases as
// phrases ("manganese peroxidase" rides the wood breakdown group
// precisely because it is the enzyme the asker's phrase
// describes), and the phrase scan is the same one
// questionConceptGroups runs — longest wins so a full subject
// phrase beats a shorter incidental member. Null when the
// question names no grouped subject phrase; the leg then falls
// back to the lane's core term query, exactly as before.
export function methodSubjectPhrase(rawQuery) {
  const lc = String(rawQuery || "").toLowerCase();
  if (!lc) return null;
  let best = null;
  for (const group of CONCEPT_GROUPS) {
    for (const member of group) {
      if (member.indexOf(" ") !== -1 && lc.includes(member)) {
        if (!best || member.length > best.length) best = member;
      }
    }
  }
  return best;
}

// The paired omics comparison shape (2026-10-22, search
// diagnosis): a question that names BOTH sequencing subjects —
// a metagenome side and a metatranscriptome side — and asks
// for their comparison (a ratio, a comparison, a relating).
// The founding case is the owner's metagenomics question: the
// literature that answers it (Franzosa 2014 relating the
// metatranscriptome and metagenome; the HUMAnN2 species level
// profiling of metagenomes and metatranscriptomes) is indexed
// everywhere and returned by no relevance ordered call the
// pipeline made, because no executed query ever required both
// subjects at once (see the concept group comment at the
// metagenome groups). Citation order is what surfaces the
// class: probed directly on 2026-10-22, a citation sorted
// Europe PMC call requiring both subjects returns the HUMAnN2
// paper ninth of twelve. The shape therefore opens the
// foundational lane, whose legs all sort by citations, with
// the pair as its core terms and the ratio as its vocabulary.
// The test is deliberately narrow — both subject stems and a
// comparison marker, in the question's own words — so an
// ordinary single subject omics question is judged exactly as
// before. Returns the pair in the literature's noun forms, or
// null. The noun forms are the point: the paired papers title
// themselves with the -ome nouns ("Species-level functional
// profiling of metagenomes and metatranscriptomes"), and the
// indexes do not stem the -omics adjectives onto them —
// probed directly on 2026-10-22, a citation sorted Europe PMC
// call on (metagenomics AND metatranscriptomics) returns a
// first page of reviews that merely mention both techniques
// and not one paired paper, while (metagenome AND
// metatranscriptome) returns the HUMAnN2 paper ninth, and
// with the ratio required, fifth.
export function pairedOmicsComparison(rawQuery) {
  const lc = String(rawQuery || "").toLowerCase();
  if (!lc) return null;
  if (!/metagenom\w*/.test(lc)) return null;
  if (!/metatranscriptom\w*/.test(lc)) return null;
  if (!/(ratio|compar|versus|\bvs\b|relating|relative)/.test(lc)) return null;
  return ["metagenome", "metatranscriptome"];
}

// The closed set of reasons a lane returned paper fails the
// foundational primary test (2026-10-14, wave fifteen). The
// first three mirror paperIsFoundationalPrimary property by
// property — the two must never drift, and the wave fifteen
// suite pins their agreement: a paper is a primary exactly
// when none of the first three reasons applies to it. The
// fourth names a property the test itself does not judge (a
// title alone can earn engagement) but the pipeline
// downstream does: the shelf rescues and the citation
// standard both read abstracts, so an abstractless record is
// a near miss the record should be able to name even when it
// is not the property that failed the test.
export const FOUNDATIONAL_NEAR_MISS_REASONS = [
  "no-engagement", "not-early", "citations-below-median", "no-usable-abstract",
];

export function foundationalPrimaryFailureReasons(paper, stats) {
  const p = paper || {};
  const s = stats || { medianCitations: 0, earlyYearCutoff: 2016 };
  const reasons = [];
  if (paperMechanismTier(p) === 0 && paperMethodTier(p) === 0) reasons.push("no-engagement");
  const yearMatch = String(p.year || "").match(/(?:19|20)\d{2}/);
  const year = yearMatch ? parseInt(yearMatch[0], 10) : NaN;
  if (!Number.isFinite(year) || !(year <= 2016 || year <= s.earlyYearCutoff)) reasons.push("not-early");
  const citations = typeof p.citations === "number" && Number.isFinite(p.citations) ? p.citations : 0;
  if (!(citations > 0) || citations < Math.max(1, s.medianCitations)) reasons.push("citations-below-median");
  if (!String(usableAbstract(p) || "").trim()) reasons.push("no-usable-abstract");
  return reasons;
}

// The near miss companion to gatherFoundationalFates (wave
// fifteen): the fates can only track a paper AFTER it passes
// the primary test, so a founding paper that never forms a
// primary was invisible to the record — the exact blind spot
// that let three waves of fixes pass their fixtures while
// the burial sat upstream of every tracked step. A near miss
// is a paper the lane's legs returned (lane tagged at
// gather, judged on its merged record the way the fates
// judge theirs) whose citation count is at or above the
// capture's median, or which stands in the lane's own top
// five by citations, but which fails the primary test. Each
// carries its failing properties from the closed set above.
// Bounded like the fates: cap five, highest cited first.
export function gatherFoundationalNearMisses(input) {
  const inp = input || {};
  const preDedupe = Array.isArray(inp.preDedupe) ? inp.preDedupe : [];
  const merged = Array.isArray(inp.merged) ? inp.merged : [];
  const scoredAllCapture = Array.isArray(inp.scoredAllCapture) ? inp.scoredAllCapture : [];
  const stats = foundationalPoolStats(scoredAllCapture);
  const median = Math.max(1, stats.medianCitations);
  const claimed = new Set();
  const judgedList = [];
  for (const cand of preDedupe) {
    if (!cand || !cand._foundationalLane) continue;
    const keys = paperDedupeKeys(cand);
    if (keys.some((k) => claimed.has(k))) continue;
    for (const k of keys) claimed.add(k);
    const judged = merged.find((p) => p && paperDedupeKeys(p).some((k) => keys.includes(k))) || cand;
    judgedList.push(judged);
  }
  const byCitations = [...judgedList].sort(
    (a, b) => (Number(b && b.citations) || 0) - (Number(a && a.citations) || 0));
  const topRankKeys = new Set();
  for (const p of byCitations.slice(0, 5)) {
    for (const k of paperDedupeKeys(p || {})) topRankKeys.add(k);
  }
  const out = [];
  for (const judged of judgedList) {
    if (paperIsFoundationalPrimary(judged, stats)) continue;
    const citations = typeof judged.citations === "number" && Number.isFinite(judged.citations)
      ? judged.citations : 0;
    const inTopRanks = paperDedupeKeys(judged).some((k) => topRankKeys.has(k));
    if (!(citations >= median || inTopRanks)) continue;
    const failing = foundationalPrimaryFailureReasons(judged, stats);
    if (failing.length === 0) continue;
    out.push({
      title: judged.title || "",
      year: judged.year || "",
      citations: typeof judged.citations === "number" && Number.isFinite(judged.citations)
        ? judged.citations : null,
      failing,
    });
  }
  out.sort((a, b) => (Number(b.citations) || 0) - (Number(a.citations) || 0));
  return out.slice(0, 5);
}

// WAVE FOURTEEN (2026-10-14, brief item 1): the gather level
// fate of every foundational primary the lane admitted. Three
// waves of fixes passed their fixtures while the 2012 CRISPR
// founding paper still buried live, because no surface could
// name the step that ended its path. This helper is pure and
// exported so the harness can pin it directly: given the
// pipeline's own lists at gather time (the pre dedupe pool,
// the merged records, the scorer's full capture, the post
// floor chain, the final shelf, and the returned shelf), it
// returns one bounded fate per admitted primary work (cap
// five, highest cited first), each naming the first gather
// step its path ended at, or no ending when it was returned.
// The language screen judged here is the chain's own test,
// copied verbatim: the chain's copy is local to the gather
// body, and the two must never drift, so any change to one is
// a change to both.
export function gatherFoundationalFates(input) {
  const inp = input || {};
  const preDedupe = Array.isArray(inp.preDedupe) ? inp.preDedupe : [];
  const merged = Array.isArray(inp.merged) ? inp.merged : [];
  const scoredAllCapture = Array.isArray(inp.scoredAllCapture) ? inp.scoredAllCapture : [];
  const scoredPostFloor = Array.isArray(inp.scoredPostFloor) ? inp.scoredPostFloor : [];
  const finalScored = Array.isArray(inp.finalScored) ? inp.finalScored : [];
  const returnedShelf = Array.isArray(inp.returnedShelf) ? inp.returnedShelf : [];
  const titlePassesLanguageScreen = (rawTitle) => {
    const title = String(rawTitle || "").trim();
    if (!title) return true;
    const nonLatinRatio = (title.match(/[^\u0000-\u024F\u1E00-\u1EFF\s\d\-.,;:()[\]{}'"!?@#$%^&*+=/<>]/g) || []).length / title.length;
    if (nonLatinRatio > 0.3) return false;
    const lowerTitle = title.toLowerCase();
    if (/^(les |une |des |étude |analyse |recherche |l'|la |le |du |de la )/.test(lowerTitle)) return false;
    if (/^(die |das |ein |eine |zur |über )/.test(lowerTitle)) return false;
    return true;
  };
  const keySetOf = (list) => {
    const s = new Set();
    for (const p of list) {
      if (!p) continue;
      for (const k of paperDedupeKeys(p)) s.add(k);
    }
    return s;
  };
  const mergedKeys = keySetOf(merged);
  const scoredKeys = keySetOf(scoredAllCapture);
  const postFloorKeys = keySetOf(scoredPostFloor);
  const shelfKeys = keySetOf(finalScored);
  const returnedKeys = keySetOf(returnedShelf);
  const stats = foundationalPoolStats(scoredAllCapture);
  const claimed = new Set();
  const candidates = [];
  for (const cand of preDedupe) {
    if (!cand || !cand._foundationalLane) continue;
    const keys = paperDedupeKeys(cand);
    if (keys.some((k) => claimed.has(k))) continue;
    for (const k of keys) claimed.add(k);
    const judged = merged.find((p) => p && paperDedupeKeys(p).some((k) => keys.includes(k))) || cand;
    if (!paperIsFoundationalPrimary(judged, stats)) continue;
    candidates.push({ keys, judged });
  }
  candidates.sort((a, b) => ((Number(b.judged.citations) || 0) - (Number(a.judged.citations) || 0)));
  return candidates.slice(0, 5).map(({ keys, judged }) => {
    const hasAny = (set) => keys.some((k) => set.has(k));
    const dedupe = hasAny(mergedKeys);
    const scored = hasAny(scoredKeys);
    const shelf = hasAny(shelfKeys);
    const returned = hasAny(returnedKeys);
    let shelfPosition = null;
    for (let i = 0; i < finalScored.length; i++) {
      if (paperDedupeKeys(finalScored[i] || {}).some((k) => keys.includes(k))) { shelfPosition = i; break; }
    }
    let endedAt = null;
    let endedDetail = null;
    if (!returned) {
      if (!dedupe) {
        endedAt = "dedupe";
      } else if (!hasAny(postFloorKeys)) {
        endedAt = titlePassesLanguageScreen(judged.title) ? "quality-floor" : "language-screen";
      } else if (!shelf) {
        endedAt = "shelf-cut";
        endedDetail = String(judged.abstract || "").trim().length > 0
          ? "below the shelf score cut and no rescue displaced for it"
          : "no abstract: the shelf rescues require one";
      } else {
        endedAt = hasRetractedTitleMarker(judged.title) ? "retraction-screen" : "rerank";
      }
    }
    return {
      title: judged.title || "",
      year: judged.year || "",
      keys,
      steps: { pool: true, dedupe, scored, shelf, returned },
      shelfPosition,
      endedAt,
      endedDetail,
    };
  });
}

// The handler continuation of a gather fate (wave fourteen):
// at each named checkpoint the fate records whether its paper
// is still present in the list that checkpoint judges, and a
// fate still open (endedAt null) that is absent ends there.
// A fate that already ended keeps its gather ending; the step
// is still recorded, so the record shows the full path.
export function advanceFoundationalFates(fates, step, papers) {
  if (!Array.isArray(fates) || fates.length === 0) return fates;
  const keys = new Set();
  if (Array.isArray(papers)) {
    for (const p of papers) {
      if (!p) continue;
      for (const k of paperDedupeKeys(p)) keys.add(k);
    }
  }
  for (const fate of fates) {
    if (!fate || typeof fate !== "object") continue;
    if (!fate.steps || typeof fate.steps !== "object") fate.steps = { pool: true };
    const present = Array.isArray(fate.keys) && fate.keys.some((k) => keys.has(k));
    fate.steps[step] = present;
    if (!present && fate.endedAt == null) fate.endedAt = step;
  }
  return fates;
}

// The completion of a gather fate (wave fourteen): the final
// shipped entry lists are the ground truth for presented. An
// entry is a source list object, not a paper, so its keys are
// built from the entry itself (its title key dominates, its
// DOI URL when it carries one). A fate in neither list that
// was still open ends as not-presented.
export function completeFoundationalFates(fates, evidenceEntries, tailEntries) {
  if (!Array.isArray(fates) || fates.length === 0) return fates;
  const keySetOf = (entries) => {
    const s = new Set();
    if (Array.isArray(entries)) {
      for (const e of entries) {
        if (!e) continue;
        for (const k of paperDedupeKeys(e)) s.add(k);
      }
    }
    return s;
  };
  const evidenceKeys = keySetOf(evidenceEntries);
  const tailKeys = keySetOf(tailEntries);
  for (const fate of fates) {
    if (!fate || typeof fate !== "object") continue;
    const fk = Array.isArray(fate.keys) ? fate.keys : [];
    if (fk.some((k) => evidenceKeys.has(k))) {
      fate.presented = true;
      fate.presentedVia = "evidence";
    } else if (fk.some((k) => tailKeys.has(k))) {
      fate.presented = true;
      fate.presentedVia = "tail";
    } else {
      fate.presented = false;
      fate.presentedVia = null;
      if (fate.endedAt == null) fate.endedAt = "not-presented";
    }
  }
  return fates;
}

// The cited shelf for a mechanism question: foundational
// primaries lead. Mirrors orderShelfForMeasurement exactly in
// structure: papers the relevance gate already cleared but the
// maxEvidence slice left out are pulled in ahead of the
// shelf's non primary tail (the shelf size does not grow, and
// nothing outside the gated pool is ever pulled), then the
// whole shelf is stably ordered primaries first . among
// primaries, higher mechanism tier first, then original order
// . while non primaries keep their original relative order
// untouched, so citation [1] is a foundational primary
// whenever the pool holds one.
export function orderShelfForMechanism(shelf, gatedPool) {
  const list = Array.isArray(shelf) ? shelf.slice() : [];
  if (list.length === 0) return list;
  const stats = foundationalPoolStats([
    ...list,
    ...(Array.isArray(gatedPool) ? gatedPool : []),
  ]);
  if (Array.isArray(gatedPool)) {
    const inShelf = new Set(list);
    const extras = gatedPool.filter((p) => p && !inShelf.has(p) && paperIsFoundationalPrimary(p, stats));
    // Higher mechanism tier pulls before lower; pool order
    // (the gate's ranked order) inside each level.
    extras.sort((a, b) => paperMechanismTier(b) - paperMechanismTier(a));
    for (const extra of extras) {
      let idx = -1;
      for (let i = list.length - 1; i >= 0; i--) {
        if (!paperIsFoundationalPrimary(list[i], stats)) { idx = i; break; }
      }
      if (idx < 0) break;
      list.splice(idx, 1);
      list.push(extra);
    }
  }
  const tiered = list.map((p, i) => ({
    p, i, t: paperMechanismTier(p), primary: paperIsFoundationalPrimary(p, stats),
  }));
  tiered.sort((a, b) => {
    if (a.primary !== b.primary) return a.primary ? -1 : 1;
    if (a.primary && b.primary) return (b.t - a.t) || (a.i - b.i);
    return a.i - b.i;
  });
  return tiered.map((x) => x.p);
}

/* ── Famous health questions (2026-10-14, wave ten, brief
 * item 5) ───────────────────────────────────────────────────
 * The audit's coffee question ("does coffee make you live
 * longer") returned only 2012 to 2017 newsletter commentary —
 * no cohort study, no systematic review — because nothing in
 * the pipeline prefers the designs that actually answer a
 * famous health benefit or harm question over the commentary
 * that surrounds it. The shape: a plain language yes or no
 * health question (an opener plus a health outcome word). The
 * prior: cohort studies, systematic reviews, and meta analyses
 * outrank newsletter and commentary pieces in the evidence
 * order, and the foundational lane runs a health vocabulary
 * variant so those designs are in the pool at all. */
export function isFamousHealthShapeQuery(query) {
  const lc = String(query || "").toLowerCase().replace(/\s+/g, " ").trim();
  if (!/^(does|do|did|is|are|can|will|should)\b/.test(lc)) return false;
  return /\b(help|helps|helpful|good for|bad for|hurt|hurts|harm|harms|harmful|benefit|benefits|beneficial|healthy|healthier|live longer|longevity|life expectancy|cause|causes)\b/.test(lc)
    && /\b(eat|eating|drink|drinking|take|taking|use|using|consume|consuming|food|diet|gut|kidney|kidneys|liver|heart|brain|body|health|sleep|weight|longer|life)\b/.test(lc);
}

const HEALTH_COMMENTARY_RE = /\b(health letter|health watch|newsletter|commentary|editorial|perspective|viewpoint|in my opinion)\b/i;
export function healthEvidenceTier(paper) {
  const p = paper || {};
  const title = String(p.title || "");
  const journal = String(p.journal || "");
  const pubTypes = Array.isArray(p.publicationTypes) ? p.publicationTypes.join(" ") : String(p.publicationType || "");
  const hay = title + " " + pubTypes;
  if (/\b(systematic review|meta[-\s]?analysis|meta[-\s]?analyses|umbrella review)\b/i.test(hay)) return 3;
  if (/\b(cohort|prospective stud|randomi[sz]ed controlled|controlled trial|mendelian randomization)\b/i.test(hay)) return 2;
  if (HEALTH_COMMENTARY_RE.test(journal) || HEALTH_COMMENTARY_RE.test(title)) return 0;
  return 1;
}

/* The cited shelf for a famous health question: the designs
 * that answer it lead. Mirrors orderShelfForMechanism: higher
 * tier papers the gate cleared but the slice left out are
 * pulled in ahead of the shelf's commentary tail (the shelf
 * size does not grow), then the shelf is stably ordered by
 * tier descending, original order inside a tier. */
export function orderShelfForHealth(shelf, gatedPool) {
  const list = Array.isArray(shelf) ? shelf.slice() : [];
  if (list.length === 0) return list;
  if (Array.isArray(gatedPool)) {
    const inShelf = new Set(list);
    const extras = gatedPool.filter((p) => p && !inShelf.has(p) && healthEvidenceTier(p) >= 2);
    extras.sort((a, b) => healthEvidenceTier(b) - healthEvidenceTier(a));
    for (const extra of extras) {
      let idx = -1;
      for (let i = list.length - 1; i >= 0; i--) {
        if (healthEvidenceTier(list[i]) === 0) { idx = i; break; }
      }
      if (idx < 0) break;
      list.splice(idx, 1);
      list.push(extra);
    }
  }
  const tiered = list.map((p, i) => ({ p, i, t: healthEvidenceTier(p) }));
  tiered.sort((a, b) => (b.t - a.t) || (a.i - b.i));
  return tiered.map((x) => x.p);
}

// Question type (2026-10-23, logic audit L1-15): the type used
// to be a fact about punctuation and opening formulas. The
// yes/no branch required a trailing question mark (the Oct 21
// probe set, written the way people type, has none, so every
// probe took the default path), and the definition branch
// claimed any "what are the ..." opening, including findings
// questions ("what are the effects of sleep loss" is not asking
// for a definition of effects). Type is now scored from the
// question's content words and operative verb, punctuation
// plays no part in any branch, a findings noun can never be a
// definition term, a method ask outranks a definition reading
// whenever the term names the method (2026-10-23, L1-3: the
// definition guard used to reject only a term that STARTS with
// a method noun, so "standard lab assay for X" defined the
// assay instead of asking for it), and a question no cue
// supports returns the explicit unknown state instead of a
// general default that pretends to know. Every return carries
// the confidence of the cues that produced it; consumers that
// key on type must handle "unknown" as no type knowledge, the
// way they already handle every non special type.
const DEFINITION_FINDINGS_HEADS = new Set([
  "effects", "effect", "outcomes", "outcome", "benefits", "benefit",
  "risks", "risk", "causes", "symptoms", "consequences", "impacts",
  "impact", "advantages", "disadvantages", "uses", "types", "kinds",
]);
const METHOD_NOUN_RE = /\b(?:method|methods|technique|techniques|assay|assays|test|tests|protocol|protocols|procedure|procedures|measurement|measurements|determination)\b/;

export function classifyQuestionType(query) {
  const q = String(query || "").trim();
  const lc = q.toLowerCase().replace(/\s+/g, " ");
  if (!lc) return { type: "unknown", term: null, confidence: 0 };

  // Definition: "what is X", "what are X", "define X", "what does X mean",
  // "meaning of X", "X definition", "what is meant by X"
  let m = lc.match(/^(?:what\s+(?:is|are|was|were)|whats)\s+(?:the\s+|a\s+|an\s+)?(.+?)[?.!]*$/)
    || lc.match(/^define\s+(?:the\s+|a\s+|an\s+)?(.+?)[?.!]*$/)
    || lc.match(/^what\s+does\s+(.+?)\s+mean[?.!]*$/)
    || lc.match(/^what\s+is\s+meant\s+by\s+(.+?)[?.!]*$/)
    || lc.match(/^(?:the\s+)?meaning\s+of\s+(.+?)[?.!]*$/)
    || lc.match(/^(.+?)\s+definition[?.!]*$/);
  if (m) {
    let term = m[1].trim()
      .replace(/^(the|a|an)\s+/i, "")
      .replace(/[?.!]+$/, "").trim();
    // Guard: "what is the best treatment for X" is not a definition.
    // Guard (2026-10-14, method intent): "what is the assay for X"
    // is not a definition either . the term IS a method noun, and
    // the question asks for the method, so it falls through to
    // the methods branch below instead of being answered as if
    // "assay for X" were a thing to define.
    if (term && !/^(best|most|latest|newest|first|main|primary)\b/.test(term)
      && !/^(method|methods|technique|techniques|assay|assays|protocol|protocols|procedure|procedures)\b/.test(term)
      // Findings guard (2026-10-23, L1-15): a term headed by a
      // findings noun names results the literature reports, not
      // a thing to define.
      && !DEFINITION_FINDINGS_HEADS.has(term.split(/\s+/)[0])
      // Method guard (2026-10-23, L1-3): when the operative
      // relation is measurement and the term names a method
      // noun anywhere ("standard lab assay for X"), the
      // question asks for the method, not for a definition.
      && !(detectMeasurementIntent(lc) && METHOD_NOUN_RE.test(term))
      && term.split(/\s+/).length <= 8) {
      return { type: "definition", term, confidence: 0.9 };
    }
  }
  // Comparison: "X vs Y", "X versus Y", "compare X and Y", "difference between X and Y"
  m = lc.match(/(.+?)\s+(?:vs\.?|versus)\s+(.+?)[?.!]*$/)
    || lc.match(/^compare\s+(.+?)\s+and\s+(.+?)[?.!]*$/)
    || lc.match(/^(?:what(?:'s| is) the )?difference between\s+(.+?)\s+and\s+(.+?)[?.!]*$/);
  if (m) {
    return { type: "comparison", term: (m[1] || "").trim(), termB: (m[2] || "").trim(), confidence: 0.9 };
  }
  // Method intent (2026-10-14) outranks the mechanism shape:
  // "how do researchers quantify X" opens like a mechanism
  // question ("how do ...") but its operative verb is the
  // measurement, so it is a methods question. The definition
  // and comparison branches above are untouched: a measurement
  // phrasing reaches here only when it is neither.
  if (detectMeasurementIntent(lc)) {
    return { type: "methods", term: null, confidence: 0.85 };
  }
  // Mechanism: "how does X work", "mechanism of X", "why does X cause Y"
  if (/^(how\s+does|how\s+do|mechanism\s+of|what(?:'s| is) the mechanism)/.test(lc)
    || /\bmechanism\b/.test(lc) && /^(how|what|why)/.test(lc)) {
    return { type: "mechanism", term: null, confidence: 0.8 };
  }
  // Methods: "how to X", "protocol for X", "method to X", and
  // measurement questions (2026-10-14, method intent): "how can
  // the activity of X be measured" is a methods question whose
  // operative verb is the measurement . it matched nothing here
  // before and fell through to "general", which is how a
  // measurement question ended up answered by value reporting
  // papers. detectMeasurementIntent carries the patterns.
  if (/^how\s+to\b/.test(lc) || /\bprotocol\b/.test(lc) || /^(what|which)\s+(method|methods|technique|assay)/.test(lc)
    || detectMeasurementIntent(lc)) {
    return { type: "methods", term: null, confidence: 0.8 };
  }
  // Yes/no (2026-10-23, L1-15): an auxiliary opening IS the
  // yes/no cue, with or without a trailing question mark. The
  // old pattern ended in a literal question mark, so the same
  // sentence typed without one fell through to the default.
  if (/^(is|are|was|were|does|do|did|can|could|has|have|will|would|should)\b/.test(lc)) {
    return { type: "yesno", term: null, confidence: 0.8 };
  }
  // List: "list ...", "what are the ...", "name the ..."
  if (/^(list|name|enumerate)\b/.test(lc) || /^what\s+are\s+(?:the\s+|some\s+)?(?:types|kinds|examples|causes|symptoms|treatments|effects|outcomes|benefits|risks)\b/.test(lc)) {
    return { type: "list", term: null, confidence: 0.75 };
  }
  // Findings (2026-10-23, L1-15): "what happens ...", "what
  // are the effects of ..." and their kin ask what the
  // literature found. No dedicated consumer keys on this type
  // yet; it is recorded so the type field stops calling these
  // questions definitions or unknowns.
  if (/^what\s+(?:happens|are\s+the\s+(?:effects|outcomes|benefits|risks|consequences))\b/.test(lc)
    || /\b(?:effects|outcomes|consequences)\s+of\b/.test(lc)) {
    return { type: "findings", term: null, confidence: 0.6 };
  }
  // Explicit unknown (2026-10-23, L1-15): no cue scored, so the
  // record says the type is not known instead of defaulting to
  // a general type that pretends it is.
  return { type: "unknown", term: null, confidence: 0 };
}

// ═══════════════════════════════════════════════════════════════════
// QUERY INTELLIGENCE (2026-10-09): "actual intelligence like it's teaching you"
// Dusty: the search is dumb. It matches keywords, applies bonuses, and hopes.
// When it fails (BSFL waste oil), it fails silently and confidently.
// This layer makes the system REASON about what it's doing:
//   1. analyzeQuery: parse the query, extract load-bearing constraints,
//      and state in plain English what it's looking for.
//   2. verifyPaperConstraints: check each retrieved paper against those
//      constraints (does it actually mention "waste oil"?).
//   3. assessExtractionQuality consumes the verdicts: zero papers satisfying
//      all constraints triggers the honest fallback, not a confident answer
//      about an adjacent question.
//   4. Constraint failures are logged to D1 for future learning.
// Pure functions, no I/O, fully testable. Incremental: nothing rewritten.
// ═══════════════════════════════════════════════════════════════════

// Words that frame a question but carry no constraint meaning. Stripped
// before phrase extraction so "Studies involving X" yields the constraint
// in X, not "studies involving" as a phrase.
const QUERY_FRAMING_WORDS = new Set([
  "studies", "study", "involving", "involved", "involves", "involve",
  "papers", "paper", "research", "researching", "regarding", "about",
  "on", "for", "with", "using", "use", "used", "what", "which", "who",
  "whom", "whose", "when", "where", "why", "how", "is", "are", "was",
  "were", "do", "does", "did", "can", "could", "has", "have", "had",
  "will", "would", "should", "the", "a", "an", "of", "in", "to", "and",
  "or", "vs", "versus", "between", "among", "per", "via", "from",
  "effect", "effects", "affect", "affects", "impact", "impacts", "role",
  "review", "reviews", "overview", "literature", "evidence", "findings",
  "results", "data", "report", "reported", "first", "new", "recent",
  "latest", "current", "there", "their", "they", "them", "this", "that",
  "these", "those", "it", "its", "as", "at", "by", "be", "been", "are",
  "any", "some", "all", "more", "most", "other", "such", "than", "then",
  "into", "over", "under", "after", "before", "between", "through",
  // 2026-10-09: question-property adjectives. "how deadly is the bubonic
  // plague" asks about the plague's lethality; "deadly" is the property
  // being asked about, not a phrase papers must contain. Without this,
  // "deadly bubonic plague" became a load-bearing constraint no paper
  // satisfies and the whole pool was capped below the relevance floor.
  "deadly", "dangerous", "lethal", "fatal", "safe", "effective",
  "common", "rare", "serious", "severe", "harmful",
  // 2026-10-11: substrate/feed role words. "waste oil substrates" means waste oil
  // USED AS substrate; papers about feeding waste oil don't need the literal word.
  "substrate", "substrates", "feed", "feeding", "fed", "diet", "diets",
  // 2026-10-11: culturability property. "what organisms would be culturable"
  // asks about a property, not a topic papers must mention.
  "culturable", "cultivable", "culturability",
  // 2026-10-10: question-framing nouns/verbs/adverbs. "What organisms are
  // commonly found in the black soldier fly larval gut microbiome" produced
  // the load-bearing constraints "organisms commonly found" /
  // "commonly found larval" / "found larval gut" . phrases no paper contains,
  // so the constraint filter dropped the entire pool and the answer was
  // "no citable literature surfaced" for a well-studied topic. The asked-about
  // thing ("organisms") and the asking ("commonly found") are framing, not
  // constraints; the constraint is "gut microbiome".
  "organism", "organisms", "commonly", "found", "find", "finds",
  // 2026-10-13: light verbs and "being". "What lets a wood frog survive
  // being frozen" built the load bearing phrases "lets wood being" and
  // "frozen months time", so the pool was gated on wording no paper
  // uses. These words frame the asking, never the science.
  "let", "lets", "being", "make", "makes", "made", "allow", "allows",
  "allowed", "help", "helps", "helped", "keep", "keeps", "kept",
  "take", "takes", "took", "become", "becomes", "became", "come",
  "comes", "came",
  // Contraction fragments, same reasoning as the STOPWORDS entry:
  // "doesn't" must not leave "doesn" as a load bearing term.
  "doesn", "didn", "isn", "aren", "wasn", "weren", "wouldn",
  "couldn", "shouldn", "hasn", "haven", "ain", "don",
  "doesn't", "don't", "isn't", "aren't", "wasn't", "weren't",
  "didn't", "won't", "wouldn't", "couldn't", "shouldn't",
  "hasn't", "haven't", "can't", "cannot",
  // 2026-10-13 (fleet and coverage pass): indefinite pronouns. "Has
  // anyone assayed..." shipped "anyone" as a load bearing AND rung in
  // the structured query. Who is asking never names a constraint;
  // EXPANSION_FRAMING_WORDS already bars these words as expansion
  // targets, and this set now bars them as anchors and phrase material
  // as well.
  "anyone", "someone", "everyone", "anybody", "somebody", "everybody",
  "nobody", "whoever",
]);

// Life-stage words describe the organism, not the topic. "What organisms are
// commonly found in the black soldier fly larval gut microbiome" is about
// the organism's gut microbiome; "larval" must not become a load-bearing
// topic constraint (it forced the phrase "larval gut microbiome", which
// papers titled "The Core Gut Microbiome of Black Soldier Fly Larvae"
// don't contain). Only excluded when an organism was identified; in an
// organism-free query ("mosquito larvae control") they can be load-bearing.
const LIFE_STAGE_WORDS = new Set([
  "larva", "larvae", "larval", "pupa", "pupae", "pupal",
  "nymph", "nymphs", "nymphal", "maggot", "maggots",
  "caterpillar", "caterpillars", "grub", "grubs",
]);

// Generic descriptors that modify a constraint but aren't constraints
// themselves. "waste oil substrates": "substrates" is the category,
// "waste oil" is the constraint.
const GENERIC_DESCRIPTORS = new Set([
  "substrates", "substrate", "sources", "source", "types", "type",
  "kinds", "kind", "forms", "form", "methods", "method", "techniques",
  "technique", "approaches", "approach", "systems", "system", "models",
  "model", "factors", "factor",
]);

// Normalize text for constraint matching: lowercase, hyphens to spaces,
// collapse whitespace. Plural tolerance is handled at match time.
function normalizeConstraintText(s) {
  return String(s || "").toLowerCase().replace(/[-‐‑]/g, " ").replace(/\s+/g, " ").trim();
}

// Build a regex that matches a phrase with plural tolerance on each word.
// "waste oil" matches "waste oil", "waste oils", "waste-oil".
function constraintPhraseRegex(phrase) {
  const words = normalizeConstraintText(phrase).split(" ").filter(Boolean);
  if (words.length === 0) return null;
  const wordPat = words.map((w) => {
    const base = w.replace(/s$/, "");
    const escaped = base.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return escaped + "(?:s)?";
  });
  return new RegExp("\\b" + wordPat.join("[\\s-]+") + "\\b", "i");
}

// Does the text mention this phrase? Checks the phrase itself plus any
// registered synonym expansions (e.g. "BSFL" via organism phrases).
// Two tiers: adjacent match ("waste oil") or proximity match ("waste
// cooking oil", "waste vegetable oil" — the constraint terms within 2
// words of each other). A human researcher counts "waste cooking oil"
// as waste oil; the system should too. Distant co-occurrence ("waste"
// in one sentence, "oil" three paragraphs later) does NOT count —
// that's how "municipal solid waste" papers with a passing "oil"
// mention used to slip through.
function textMentionsPhrase(text, phrase, synonymPhrases) {
  const norm = normalizeConstraintText(text);
  if (!norm) return false;
  const re = constraintPhraseRegex(phrase);
  if (re && re.test(norm)) return true;
  const pre = constraintProximityRegex(phrase);
  if (pre && pre.test(norm)) return true;
  for (const syn of (synonymPhrases || [])) {
    const sre = constraintPhraseRegex(syn);
    if (sre && sre.test(norm)) return true;
    const spre = constraintProximityRegex(syn);
    if (spre && spre.test(norm)) return true;
  }
  return false;
}

// Proximity variant: constraint words with at most 1 word between them.
// "waste cooking oil" matches "waste oil"; "waste from palm oil" does not
// (2+ words apart — a different concept: waste derived from oil
// production, not waste oil itself).
function constraintProximityRegex(phrase) {
  const words = normalizeConstraintText(phrase).split(" ").filter(Boolean);
  if (words.length < 2) return null;
  const wordPat = words.map((w) => {
    const base = w.replace(/s$/, "");
    const escaped = base.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return escaped + "(?:s)?";
  });
  return new RegExp("\\b" + wordPat.join("(?:[\\s-]+\\w+)?[\\s-]+") + "\\b", "i");
}

// Extract load-bearing multi-word phrases from a query. A phrase is
// load-bearing when 2+ content words appear adjacently after stripping
// framing words and organism terms. "waste oil substrates" -> ["waste oil"]
// ("substrates" is a generic descriptor, not part of the constraint).
// Question verbs are framing, not concepts (2026-10-12). A constraint
// phrase built around a verb ("insect gut degrade") can never match the
// papers it describes, because papers nominalize verbs: they write
// "conversion", "released from", "breakdown", never the question's verb
// form next to the subject. The discriminating concepts in a mechanism
// question are the subject and the object ("insect gut" +
// "lignocellulose"); the verb between them is how the user asked, not
// what a paper must say. Dropping these verbs from the token stream
// lets the window join subject and object into a matchable phrase.
// Noun forms (degradation, treatment, survival) are NOT in this set:
// they are different tokens and often the actual topic.
const QUESTION_VERBS = new Set([
  "degrade", "degrades", "degraded", "degrading",
  "survive", "survives", "survived", "surviving",
  "protect", "protects", "protected", "protecting",
  "cause", "causes", "caused", "causing",
  "affect", "affects", "affected", "affecting",
  "improve", "improves", "improved", "improving",
  "increase", "increases", "increased", "increasing",
  "decrease", "decreases", "decreased", "decreasing",
  "reduce", "reduces", "reduced", "reducing",
  "prevent", "prevents", "prevented", "preventing",
  "help", "helps", "helped", "helping",
  "happen", "happens", "happened",
  "occur", "occurs", "occurred", "occurring",
  "differ", "differs", "differed",
  "kill", "kills", "killed", "killing",
  "treat", "treats", "treated", "treating",
  "produce", "produces", "produced", "producing",
  "form", "forms", "formed", "forming",
  "grow", "grows", "grew", "growing",
  "develop", "develops", "developed", "developing",
  "become", "becomes", "became", "becoming",
  // "stop" (2026-10-14, wave eight round three): the swimmer's
  // ear question's "how do I stop it" made the bare verb a key
  // phrase head and then a central concept, so clinical otitis
  // externa papers engaging the bridged ear concept still failed
  // the two concept standard on a word that names the ask, not
  // the topic. Same class as prevent and treat above.
  "stop", "stops", "stopped", "stopping",
  // "fight" (2026-10-14, wave eight round three): "does
  // vitamin D help you fight off colds" made the outcome verb
  // a central concept while the illness word never resolved,
  // so the vitamin D cold trials engaged one real concept and
  // failed the standard on a verb. Same class as protect and
  // kill above.
  "fight", "fights", "fought", "fighting",
  // "wear" (2026-10-15, wave seventeen, citation depth
  // diagnosis): "my ankles puff up when i wear tight socks"
  // made the circumstance verb a key phrase head and then a
  // central concept — the diagnosis names it beside "else" as
  // a bare token that must never become a concept. The wearing
  // frames the question; the topic is the swelling. Same class
  // as stop and fight above.
  "wear", "wears", "wore", "worn", "wearing",
]);

// Span separators (2026-10-23, logic audit L1-6): the only
function extractKeyPhrases(query, organismPhrases) {
  const norm = normalizeConstraintText(query);
  const orgSet = new Set((organismPhrases || []).map(normalizeConstraintText));
  // Also index individual organism words so "black soldier fly larvae"
  // doesn't leak "fly larvae" as a key phrase.
  const orgWords = new Set();
  for (const p of orgSet) for (const w of p.split(" ")) orgWords.add(w);

  const tokens = norm.split(" ").filter((t) =>
    t.length > 2 && !QUERY_FRAMING_WORDS.has(t) && !QUESTION_VERBS.has(t) && !orgSet.has(t) && !orgWords.has(t)
    // 2026-10-10: life-stage words are organism descriptors, not topic
    // constraints, when the organism is already identified.
    && !(organismPhrases.length > 0 && LIFE_STAGE_WORDS.has(t))
  ).map((t) => t.replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, "")).filter((t) => t.length > 2);
  const phrases = [];
  // Sliding window: adjacent content words form candidate phrases.
  // Skip windows ending in a generic descriptor.
  // 2026-10-11: Use non-overlapping windows to avoid nonsense phrases.
  // "insect gut microbiome bile salt agar" should give ["insect gut microbiome", "bile salt agar"],
  // not ["insect gut microbiome", "gut microbiome bile", "microbiome bile salt"].
  for (let len = 3; len >= 2; len--) {
    for (let i = 0; i + len <= tokens.length; i += len) {
      const window = tokens.slice(i, i + len);
      const last = window[window.length - 1];
      const core = GENERIC_DESCRIPTORS.has(last) ? window.slice(0, -1) : window;
      if (core.length < 2) continue;
      const phrase = core.join(" ");
      if (!phrases.includes(phrase)) phrases.push(phrase);
    }
    // 2026-10-12: Handle trailing tokens (e.g. "media" in 7-token query)
    const consumed = Math.floor(tokens.length / len) * len;
    const trailing = tokens.slice(consumed);
    if (trailing.length >= 2) {
      const phrase = trailing.join(" ");
      if (!phrases.includes(phrase)) phrases.push(phrase);
    }
    // Prefer longer phrases: once we have 3-word phrases, 2-word
    // sub-phrases of them are redundant.
    if (phrases.length > 0 && len === 3) break;
  }
  return phrases.slice(0, 3);
}

// Learned from Dusty's corrections. These are not heuristics; they are
// recorded failures. Each entry: a query pattern and the constraint the
// system previously dropped.
// Format: { match: RegExp, constraint: "phrase", note: "..." }
const LEARNED_CONSTRAINT_RULES = [
  {
    // 2026-10-09: "Studies involving BSFL waste oil substrates" returned
    // general waste papers. The 'oil' constraint was dropped by the
    // minimum-results guarantee's organism_only strategy.
    match: /waste[\s-]*oil/i,
    constraint: "waste oil",
    note: "waste oil is one concept, not two keywords",
  },
  {
    // 2026-10-09: "Reese Saho" (name search) had papers classified as
    // "supporting the direction". Name searches have no direction.
    match: null, // handled via isNameSearch, kept here as documentation
    constraint: null,
    note: "name searches carry no stance; never classify papers as supporting/disputing",
  },
];

/**
 * Analyze a search query the way a researcher would read it: what is being
 * asked, what must a paper contain to count, and what would make the
 * search fail honestly.
 *
 * Returns:
 * {
 *   originalQuery, questionType, questionTerm, isNameSearch,
 *   intent: "measurement" | null,     // method intent (2026-10-14)
 *   mechanismShape: true | false,     // mechanism shape (2026-10-14, wave nine)
 *   organism: "Hermetia illucens" | null,
 *   organismPhrases: [...],
 *   keyPhrases: ["waste oil"],        // load-bearing multi-word concepts
 *   constraints: [{ phrase, terms }], // every paper must satisfy ALL
 *   plainEnglish: "Looking for ...",  // human-readable intent statement
 *   mustSatisfyAll: true,             // AND semantics, not OR
 * }
 */
/* Whether a screened key phrase's words occur in the question
 * only across a clause boundary (2026-10-23, logic audit L1-6).
 * The manufactured phrase class: "oil restaurants turn" (from
 * "cooking oil that restaurants turn into waste oil") crosses
 * the relativizer "that"; its words sit in different clauses,
 * the phrase means nothing, and as a constraint no paper could
 * satisfy it. The test runs on the SCREENED phrase against the
 * question's own token stream: a phrase whose surviving words
 * are one span ("creatine hair loss" crosses only "cause")
 * stands untouched. */
const KEY_PHRASE_CLAUSE_BOUNDARY_TOKENS = new Set(["that", "which", "who", "whom", "whose"]);
export function keyPhraseCrossesClause(phrase, queryText) {
  const words = String(phrase || "").split(" ").filter(Boolean);
  if (words.length < 2) return false;
  const normToks = normalizeConstraintText(String(queryText || ""))
    .split(" ")
    .map((t) => t.replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, ""));
  let wi = 0;
  let firstIdx = -1;
  let lastIdx = -1;
  for (let i = 0; i < normToks.length && wi < words.length; i++) {
    if (normToks[i] === words[wi]) {
      if (wi === 0) firstIdx = i;
      lastIdx = i;
      wi++;
    }
  }
  if (wi < words.length || firstIdx < 0) return false;
  for (let i = firstIdx + 1; i < lastIdx; i++) {
    if (KEY_PHRASE_CLAUSE_BOUNDARY_TOKENS.has(normToks[i])) return true;
  }
  return false;
}

export function analyzeQuery(rawQuery) {
  // 2026-10-09: analyze the TYPO-CORRECTED query, not the raw one. The
  // retrieval ladder searches the corrected form; constraint extraction
  // must agree with it. "how deadly is the bubonic plauge" must yield the
  // constraint "bubonic plague", not "deadly bubonic plauge". The raw
  // original is kept as originalQuery for display and learning signatures.
  const raw = String(rawQuery || "").trim();
  // Analysis input (2026-10-23, L1-12, scoped): the analysis
  // keeps reading the spelling corrected form, the input its
  // extraction and the gate standards were tuned on. The
  // canonical forms work (canonicalQueryForms) canonicalizes
  // the RETRIEVAL side and declares the paraphrase there;
  // feeding the paraphrased text into the analysis instead
  // demonstrably moved the gate standards off their fixtures
  // (the paraphrase's added words became key phrases and
  // central concepts for the honey safety and light questions),
  // so the shared representation stands for retrieval and the
  // analysis input stands as tuned. Recorded here so the
  // boundary is a decision, not a drift.
  const query = correctQuerySpelling(raw).trim();
  const qType = classifyQuestionType(query);
  // Method intent (2026-10-14): recorded on the analysis so the
  // shipped record shows it and every downstream consumer (the
  // shelf order, the extractive builder, the limits, the
  // synthesis prompt) reads the same fact. Null for every other
  // question shape.
  const intent = detectMeasurementIntent(query) ? "measurement" : null;
  // Mechanism shape (2026-10-14, wave nine): recorded on the
  // analysis alongside intent, as an additive field with no
  // consumer changes here — the citation standard, the
  // foundational lane, the shelf order, and the synthesis
  // prompt each detect the shape where they run, the way the
  // measurement consumers do. A question can carry both
  // shapes; neither field suppresses the other.
  const mechanismShape = isMechanismShapeQuery(query);
  // Name detection needs the user's original capitalization ("Reese Saho"
  // vs "reese saho"), so it runs on the raw query, not the lowercased one.
  const isNameSearch = looksLikePersonName(raw);
  let organism = null;
  let organismPhrases = [];
  try {
    const split = splitOrganismTopic(query);
    organismPhrases = split.orgPhrases || [];
    // Prefer the two-word latin binomial as the canonical organism name.
    organism = organismPhrases.find((s) => /^[a-z]+ [a-z]+$/i.test(s) && s.split(" ").length === 2)
      || organismPhrases[0] || null;
  } catch { /* best-effort */ }

  // Key phrases from the query itself, plus any learned rules that fire.
  let keyPhrases = [];
  try { keyPhrases = extractKeyPhrases(query, organismPhrases); } catch { /* best-effort */ }
  for (const rule of LEARNED_CONSTRAINT_RULES) {
    if (rule.match && rule.constraint && rule.match.test(query)
        && !keyPhrases.includes(rule.constraint)) {
      keyPhrases.push(rule.constraint);
    }
  }

  // Structured query hygiene (2026-10-14): extractKeyPhrases glues
  // adjacent surviving tokens into phrases, and the survivors
  // include the question's own scaffolding — the live sleep and
  // colds trace minted the "constraints" "not sleeping enough" and
  // "easier catch cold", phrases no paper contains, which then
  // drove the fanout topic string, the constraint gate terms, and
  // the shipped analysis. Every phrase passes the screen (see
  // screenKeyPhrase): filler words are stripped, a phrase left
  // with no content word is dropped, and a real constraint phrase
  // passes word for word unchanged.
  keyPhrases = [...new Set(keyPhrases.map((p) => screenKeyPhrase(p)).filter(Boolean))];
  // Manufactured phrases out (2026-10-23, L1-6): a screened
  // phrase whose words occur in the question only across a
  // clause boundary is not a span the user stated, and never
  // becomes a constraint.
  keyPhrases = keyPhrases.filter((p) => !keyPhraseCrossesClause(p, query));

  // Graded constraints (2026-10-23, L1-6): every phrase above
  // is a span the user stated, but spans are not all equal. A
  // learned constraint (a recorded failure: "waste oil" is one
  // concept) and a stated quantity phrase are required: they
  // are the constraints the question turns on. A multi word
  // span is preferred: a paper engaging it is on the question,
  // a paper missing it is weaker, not automatically off topic.
  // A single word phrase is contextual. The old code declared
  // every extracted phrase mandatory for every paper
  // (mustSatisfyAll: true, and a plain English sentence saying
  // so), including phrases the extraction had manufactured.
  const learnedPhrases = new Set();
  for (const rule of LEARNED_CONSTRAINT_RULES) {
    if (rule && rule.constraint) learnedPhrases.add(rule.constraint);
  }
  const constraints = keyPhrases.map((phrase) => {
    const level = learnedPhrases.has(phrase) || isQuantityPhraseKey(phrase)
      ? "required"
      : phrase.includes(" ")
        ? "preferred"
        : "contextual";
    return {
      phrase,
      terms: normalizeConstraintText(phrase).split(" ").filter(Boolean),
      level,
    };
  });

  // Plain-English intent statement. This is what the system believes the
  // user is asking for; it goes into _diag so the frontend can show it
  // (query translation transparency) and so failures are explainable.
  let plainEnglish = "";
  try {
    const parts = [];
    if (intent === "measurement") {
      parts.push("how the quantity in \"" + query.slice(0, 80) + "\" is measured (a methods question: papers about measuring it answer it; papers that merely report its values do not)");
    } else if (qType.type === "definition" && qType.term) {
      parts.push("a definition of \"" + qType.term + "\"");
    } else if (qType.type === "yesno") {
      parts.push("a yes/no answer to \"" + query.slice(0, 80) + "\"");
    } else if (isNameSearch) {
      parts.push("papers by or about \"" + query.slice(0, 80) + "\" (name search: no stance classification applies)");
    } else {
      const topicBits = [];
      if (organism) topicBits.push(organism);
      for (const c of constraints) topicBits.push("\"" + c.phrase + "\"");
      if (topicBits.length > 0) parts.push("studies involving " + topicBits.join(" + "));
      else parts.push("papers about \"" + query.slice(0, 80) + "\"");
    }
    plainEnglish = "Looking for " + parts.join("; ") + ".";
    if (constraints.length > 0 && !isNameSearch) {
      plainEnglish += " Every paper must mention "
        + constraints.map((c) => "\"" + c.phrase + "\"").join(" and ")
        + "; papers missing a constraint are off-topic, not supporting.";
    }
  } catch { plainEnglish = "Looking for papers about \"" + query.slice(0, 80) + "\"."; }

  return {
    originalQuery: raw,
    questionType: qType.type,
    questionTerm: qType.term || null,
    intent,
    mechanismShape,
    isNameSearch: !!isNameSearch,
    organism,
    organismPhrases,
    keyPhrases,
    constraints,
    plainEnglish,
    // True only when a required constraint exists (2026-10-23,
    // L1-6): the AND semantics bind the required spans, not
    // every extracted phrase.
    // mustSatisfyAll (2026-10-23, L1-6): no longer an
    // unconditional constant. It is true exactly when the
    // question yielded real span constraints (every surviving
    // phrase is a stated span now, graded above), and false
    // for a question with none, where the old constant claimed
    // a mandatory set that did not exist.
    mustSatisfyAll: constraints.length > 0,
  };
}

/**
 * Check a single paper against the query's constraints. This is the
 * self-checking step: after retrieval, the system verifies its own work.
 *
 * Returns:
 * {
 *   satisfiesAll: boolean,
 *   matched: ["waste oil"],     // constraints found in title/abstract
 *   missing: ["waste oil"],      // constraints NOT found
 *   verdict: "on-topic" | "partial" | "off-topic",
 *   explanation: "Mentions 'waste' but not 'oil' ...",
 * }
 */
export function verifyPaperConstraints(paper, analysis) {
  const empty = { satisfiesAll: true, matched: [], missing: [], verdict: "on-topic", explanation: "" };
  if (!analysis || !analysis.constraints || analysis.constraints.length === 0) return empty;
  if (analysis.isNameSearch) return empty; // name searches have no topical constraints

  const p = paper || {};
  const text = ((p.title || "") + " " + (p.abstract || "")).trim();
  const matched = [];
  const missing = [];
  for (const c of analysis.constraints) {
    // Word-level synonym variants of the constraint phrase. "gut microbiome"
    // must also match "gut microbiota" (same concept, standard alternate
    // term); testing the synonym as a bare phrase would be too loose
    // ("skin microbiota" is not the gut microbiome), so substitutes go
    // back into the phrase and are re-tested with the adjacent/proximity
    // regexes. Single substitutions of the original phrase only: enough
    // for real vocabulary variance without combinatorial blowup.
    const variants = [c.phrase];
    const words = c.phrase.split(" ");
    for (let i = 0; i < words.length; i++) {
      const subs = (SYNONYMS[words[i].toLowerCase()] || []).filter((s) =>
        String(s).split(" ").length <= 3);
      for (const s of subs) {
        const vw = words.slice();
        vw[i] = String(s);
        const vp = vw.join(" ");
        if (!variants.includes(vp)) variants.push(vp);
      }
    }
    let hit = false;
    for (const v of variants) {
      if (textMentionsPhrase(text, v, [])) { hit = true; break; }
    }
    // Concept-set title match (2026-10-12): a constraint of 3+ terms is
    // a set of concepts (subject + object), and a title is a dense
    // concept statement. When every term appears in the title and at
    // least one adjacent pair from the phrase survives adjacently,
    // the paper is about that concept set even when the title orders
    // the object before the subject ("Lignocellulose conversion by
    // insect gut symbionts" vs the constraint "insect gut
    // lignocellulose"). Two-term phrases stay phrase-only: order and
    // proximity are what make "waste oil" a concept rather than two
    // words, and that guard is load-bearing. Abstracts are untouched:
    // distant co-occurrence there still does not count.
    if (!hit && c.terms && c.terms.length >= 3 && p.title) {
      const titleNorm = normalizeConstraintText(p.title);
      const everyTerm = c.terms.every((t) => {
        const re = constraintPhraseRegex(t);
        return re && re.test(titleNorm);
      });
      if (everyTerm) {
        for (let i = 0; i + 1 < c.terms.length; i++) {
          const pairRe = constraintPhraseRegex(c.terms[i] + " " + c.terms[i + 1]);
          if (pairRe && pairRe.test(titleNorm)) { hit = true; break; }
        }
      }
    }
    if (hit) matched.push(c.phrase);
    else missing.push(c.phrase);
  }

  const satisfiesAll = missing.length === 0;
  let verdict = "on-topic";
  let explanation = "";
  if (!satisfiesAll) {
    // Partial: paper matches at least one constraint term individually
    // (e.g. mentions "waste" but not "waste oil").
    const normText = normalizeConstraintText(text);
    const partialHits = [];
    for (const c of analysis.constraints) {
      if (matched.includes(c.phrase)) continue;
      const hitTerms = c.terms.filter((t) => {
        const re = constraintPhraseRegex(t);
        if (re && re.test(normText)) return true;
        // Concept mention (2026-10-13, citation collapse fix): a term
        // also counts as mentioned when the paper uses the field's own
        // word for the same concept . any member of the term's concept
        // group, the same vocabulary bridge gatherPapers' matcher,
        // topicOverlapFilter, and the both concepts gate already use
        // via conceptSetFor. This test used to count literal words
        // only, which inverted the filter for everyday language
        // questions: for "Do the germs in a baby belly change how well
        // the baby grows" (constraints "germs baby belly" / "change
        // well baby"), the real infant gut papers mention NONE of the
        // literal terms (they write microbiota, intestinal, growth)
        // and were judged off-topic, while phrase collisions that
        // happen to print "belly" (belly dance, prune belly syndrome)
        // were judged partial and kept. The handler filter downstream
        // keeps on-topic and partial and drops off-topic, so the
        // on point shelf died at this verdict while the collisions
        // passed. Full phrase matching above is unchanged: a concept
        // mention earns partial (adjacent evidence), never on-topic.
        const group = conceptSetFor(String(t).toLowerCase(), null);
        if (group) {
          for (const member of group) {
            const m = String(member || "").toLowerCase();
            if (!m || m === String(t).toLowerCase()) continue;
            if (textMentionsPhrase(text, m, [])) return true;
          }
        }
        return false;
      });
      if (hitTerms.length > 0) partialHits.push("\"" + hitTerms.join(" ") + "\" without \"" + c.phrase + "\"");
    }
    if (partialHits.length > 0) {
      verdict = "partial";
      explanation = "Mentions " + partialHits.join("; ") + ". About an adjacent topic, not the requested one.";
    } else if (matched.length > 0) {
      // A fully matched constraint is the strictest evidence this
      // function has (the phrase itself, adjacent or in proximity):
      // a paper that satisfies one whole constraint and none of
      // another glued phrase is partial by definition, never
      // off-topic. The partial test above only inspects UNMATCHED
      // constraints, so before this branch a crop rotation paper
      // matching "crop rotation soil" outright was judged off-topic
      // for missing the window glued "fertility time" entirely.
      verdict = "partial";
      explanation = "Covers " + matched.map((m) => "\"" + m + "\"").join(", ") + " but not " + missing.map((m) => "\"" + m + "\"").join(" or ") + ".";
    } else {
      verdict = "off-topic";
      explanation = "Does not mention " + missing.map((m) => "\"" + m + "\"").join(" or ") + ".";
    }
  }
  return { satisfiesAll, matched, missing, verdict, explanation };
}

/**
 * Verify a list of papers. Returns aggregate stats plus per-paper verdicts.
 * Exported for testing and for the honesty gate.
 */
export function verifyPaperList(papers, analysis) {
  const list = papers || [];
  const verdicts = list.map((p, i) => ({ idx: i, ...verifyPaperConstraints(p, analysis) }));
  const onTopic = verdicts.filter((v) => v.verdict === "on-topic").length;
  const partial = verdicts.filter((v) => v.verdict === "partial").length;
  const offTopic = verdicts.filter((v) => v.verdict === "off-topic").length;
  // allMiss means NO paper engages the constraints at all. It used
  // to fire whenever no paper was fully on topic, but analyzeQuery
  // glues a plain language question into window phrases ("germs
  // baby belly") that no real paper can ever fully match, so every
  // paper with genuine concept level engagement read as a total
  // miss and the extractive honesty gate failed the whole shelf —
  // the run fell to the limited tier even when the shelf was the
  // right literature. A partial verdict IS engagement (the verdict
  // system's own middle tier); a miss is when there is none.
  return { verdicts, onTopic, partial, offTopic, total: list.length, allMiss: onTopic === 0 && partial === 0 && list.length > 0 };
}

// D1 table for the correction learning log. Created lazily on first write;
// a missing table or missing DB binding must never fail a search.
async function ensureCorrectionLogTable(db) {
  try {
    await db.prepare(
      "CREATE TABLE IF NOT EXISTS correction_patterns (" +
      "id INTEGER PRIMARY KEY AUTOINCREMENT, " +
      "pattern TEXT NOT NULL, " +
      "query_signature TEXT, " +
      "detail TEXT, " +
      "created_at INTEGER NOT NULL)"
    ).run();
  } catch { /* best-effort */ }
}

// Log a constraint failure for future learning. Called (best-effort, via
// waitUntil where available) when the verification step finds that none of
// the retrieved papers satisfy the query's key constraints. This is the
// system's memory: "this query pattern failed this way before."
export async function logConstraintFailure(env, analysis, verification, ledger = null) {
  try {
    const db = env && env.DB && typeof env.DB.prepare === "function" ? env.DB : null;
    if (!db || !analysis) return;
    // The ensure runs its CREATE on every call (not memoized).
    if (ledger) ledger.spendBinding("learning", 1);
    await ensureCorrectionLogTable(db);
    const sig = normalizeConstraintText(analysis.originalQuery).split(" ")
      .filter((t) => t.length > 2 && !QUERY_FRAMING_WORDS.has(t))
      .sort().join(" ");
    const detail = JSON.stringify({
      keyPhrases: analysis.keyPhrases,
      organism: analysis.organism,
      total: verification.total,
      partial: verification.partial,
      offTopic: verification.offTopic,
      missingEverywhere: (verification.verdicts || [])
        .map((v) => v.missing).flat()
        .filter((m, i, a) => a.indexOf(m) === i),
    }).slice(0, 2000);
    if (ledger) ledger.spendBinding("learning", 1);
    await db.prepare(
      "INSERT INTO correction_patterns (pattern, query_signature, detail, created_at) VALUES (?, ?, ?, ?)"
    ).bind("constraint_failure", sig, detail, Date.now()).run();
  } catch { /* learning must never break search */ }
}

// Read recent correction patterns (for operator diagnostics, not for
// request-time decisions: the learned rules above are the request-time
// path; this is the audit trail).
export async function getCorrectionPatterns(env, limit = 20) {
  try {
    const db = env && env.DB && typeof env.DB.prepare === "function" ? env.DB : null;
    if (!db) return [];
    await ensureCorrectionLogTable(db);
    const rows = await db.prepare(
      "SELECT pattern, query_signature, detail, created_at FROM correction_patterns ORDER BY id DESC LIMIT ?"
    ).bind(Math.min(limit, 100)).all();
    return (rows && rows.results) || [];
  } catch { return []; }
}

// E.g. "Reese Sahos studies on BSFL" -> "Reese Saho".
// Handles possessive forms (drops trailing 's or s when followed by a possessive
// context word like "studies", "papers", "research").
// Handles middle initials (Reese J Saho, Reese J. Saho).
// Returns the canonical name or null if nothing looks like a name.
function extractPersonNameFromQuery(raw) {
  if (!raw) return null;
  const s = raw.trim();
  if (!s) return null;

  // Commit 61 . refuse queries that are plainly not "who is this person".
  //
  // Real failure: "Explain the science behind: NASA Rocket Takes First
  // Multi-Point Look Inside Radio-Disrupting Clouds" was routed to the
  // author search, which then reported it had searched seven databases for
  // papers by an author named "Rocket Takes First Multi-Point". The scanner
  // below looks for a run of capitalised tokens, and a news headline is
  // nothing but capitalised tokens . so the more headline-shaped a question
  // is, the more confidently it gets misread as a name.
  //
  // Three guards, each aimed at a way a headline differs from a name:
  //   · an explicit instruction verb means the user asked for an
  //     explanation, not a person;
  //   · a name is short . nobody types a fourteen-word person query;
  //   · a colon separates a preamble from a title, and a title is not a
  //     name, so only what follows the colon is worth scanning at all.
  const lower = s.toLowerCase();
  if (/^(explain|describe|summar(y|ise|ize)|what|why|how|when|where|compare|tell me|give me|overview)\b/.test(lower)) return null;
  if (/\b(science behind|explain|research on|studies on|overview of)\b/.test(lower)) return null;
  const afterColon = s.includes(":") ? s.slice(s.indexOf(":") + 1).trim() : s;
  // The length cap only applies when nothing in the query signals that a
  // person is actually being asked about. "does Reese Saho have papers on
  // this" is nine words and unambiguously a person query; a nine-word
  // headline is not. The difference is the vocabulary, not the length, so
  // the cap stands down whenever author-context words are present.
  const hasPersonContext = /\b(papers?|publications?|authors?|wrote|written|research(ed)? by|studies by|work by|lab|et al)\b/i.test(s);
  if (!hasPersonContext && afterColon.split(/\s+/).length > 6) return null;
  if (afterColon !== s) return extractPersonNameFromQuery(afterColon);
  // If the query IS itself just a clean name, return it
  if (looksLikePersonName(s)) return s;

  // Otherwise, scan the query for a run of 2-3 name-shaped tokens.
  const toks = s.split(/\s+/);
  const isNameToken = (t) => {
    if (!t) return false;
    if (/^[A-Z]\.?$/.test(t)) return true;
    if (!/^[A-Z][a-zA-Z'\-]+$/.test(t)) return false;
    if (NAME_STOPWORDS.has(t)) return false;
    if (t.length >= 3 && t === t.toUpperCase()) return false;
    return true;
  };

  // Words that indicate the preceding word is a person's name in possessive form.
  const possessiveContext = new Set([
    "studies", "study", "papers", "paper", "research", "work", "works",
    "publications", "publication", "findings", "finding", "results", "result",
    "experiments", "experiment", "thesis", "dissertation", "articles", "article",
    "lab", "group", "team", "hypothesis", "theory", "approach", "method",
    "methods", "data", "dataset",
  ]);

  let bestName = null;
  for (let i = 0; i < toks.length; i++) {
    if (!isNameToken(toks[i])) continue;
    for (let len = 4; len >= 2; len--) {
      if (i + len > toks.length) continue;
      const chunk = toks.slice(i, i + len);
      // Middle initial can't be the LAST token
      if (/^[A-Z]\.?$/.test(chunk[chunk.length - 1])) continue;
      // First and last must be full words (2+ chars)
      if (chunk[0].length < 2 || chunk[chunk.length - 1].length < 2) continue;
      if (chunk.every(isNameToken)) {
        bestName = { toks: chunk, endIdx: i + len };
        break;
      }
    }
    if (bestName) break;
  }
  if (!bestName) return null;

  // Now apply possessive stripping on the last name token, using the word
  // AFTER the name as context to decide.
  const nextWord = (toks[bestName.endIdx] || "").toLowerCase().replace(/[.,;:?!]/g, "");
  const nameToks = bestName.toks.slice();
  const last = nameToks[nameToks.length - 1];

  if (/'s$/i.test(last)) {
    // "Saho's" . always safe to strip
    nameToks[nameToks.length - 1] = last.replace(/'s$/i, "");
  } else if (/s'$/i.test(last)) {
    nameToks[nameToks.length - 1] = last.replace(/s'$/i, "");
  } else if (
    // "Sahos studies" . trailing bare 's' followed by a possessive context word
    /[a-z]s$/.test(last) &&
    last.length > 3 &&
    !/ss$/i.test(last) &&
    possessiveContext.has(nextWord)
  ) {
    nameToks[nameToks.length - 1] = last.slice(0, -1);
  }
  return nameToks.join(" ");
}

// Direct bioRxiv API: pulls up to 100 recent preprints and filters by author
// name. Only finds someone if their preprint is public on bioRxiv itself. Not
// mirrored through OpenAlex or PubMed, so this catches things those miss.
async function biorxivDirectAuthor(fullName, ledger = null) {
  return preprintServerAuthor("biorxiv", fullName, ledger);
}
async function medrxivDirectAuthor(fullName, ledger = null) {
  return preprintServerAuthor("medrxiv", fullName, ledger);
}
/* ══════════════════════════════════════════════════════════════════
   Commit 94 . author search could not see preprints.

   Reported case: "does Reese Saho have papers on this" returned nothing,
   for the first author of a bioRxiv preprint that Europe PMC has indexed
   as PPR1250670. The author fanout queried Europe PMC, OpenAlex, Crossref,
   arXiv, Semantic Scholar and the two bioRxiv scans below . and none of
   them reach Europe PMC's preprint slice, which is where that record
   lives. Europe PMC's default search does not include SRC:PPR content;
   preprintSearch() exists precisely for that and was wired into the TOPIC
   fanout only, never the author one.

   This is the author-side equivalent. It is an index lookup rather than
   the brute-force scan below, so it finds a preprint regardless of how
   many were posted that week. */
async function europePMCPreprintAuthor(fullName, limit = 15, ledger = null) {
  try {
    const url = "https://www.ebi.ac.uk/europepmc/webservices/rest/search?" +
      new URLSearchParams({
        query: '("' + String(fullName).replace(/"/g, "") + '") AND (SRC:PPR)',
        resultType: "core",
        pageSize: String(limit),
        format: "json",
      });
    const data = await getJSON(url, {}, 6000, 1, ledger);
    const rows = (data && data.resultList && data.resultList.result) || [];
    return rows.filter((r) => r.title).map((r) => {
      const server =
        (r.bookOrReportDetails && r.bookOrReportDetails.publisher) ||
        r.journalTitle || r.publisher || "";
      return {
        title: r.title || "Untitled",
        url: r.doi ? "https://doi.org/" + r.doi : "https://europepmc.org/article/" + r.source + "/" + r.id,
        year: r.pubYear || "",
        citations: typeof r.citedByCount === "number" ? r.citedByCount : null,
        authors: r.authorString || "",
        _allAuthors: r.authorString || "",
        journal: server ? server + " (preprint)" : "Preprint",
        abstract: stripTags(r.abstractText),
        isPreprint: true,
      };
    });
  } catch (e) { return fetchFailed(e); }
}

async function preprintServerAuthor(server, fullName, ledger = null) {
  try {
    /* Commit 94 . this comment used to claim it pulled "up to ~1000 items".
       It pulled 100. The bioRxiv details endpoint returns one page of 100
       and the trailing "/0" is the cursor, which was never advanced. bioRxiv
       alone posts several thousand preprints a month, so a six-month window
       holds on the order of twenty thousand records and this was reading the
       oldest one hundred of them . roughly half a percent, and always the
       same half percent. As an author lookup it was never going to work, and
       it is why a preprint posted three months ago went unfound.

       Now walks a bounded number of pages. It is still a scan and still
       cannot cover the whole window . which is exactly why the Europe PMC
       preprint index above is the primary path and this is the backstop for
       records too new to be indexed there yet. */
    const now = new Date();
    const six = new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
    const iso = (d) => d.toISOString().slice(0, 10);
    const base = "https://api.biorxiv.org/details/" + server + "/" + iso(six) + "/" + iso(now) + "/";
    const MAX_PAGES = 12; // 1200 records . a real budget, not an accident
    let items = [];
    for (let page = 0; page < MAX_PAGES; page++) {
      const data = await getJSON(base + (page * 100), {}, 5000, 1, ledger);
      const batch = (data && data.collection) || [];
      if (!batch.length) break;
      items = items.concat(batch);
      if (batch.length < 100) break;
    }
    const nameLC = fullName.toLowerCase();
    const tokens = nameLC.split(/\s+/).filter(Boolean);
    const hits = items.filter((it) => {
      const auths = (it.authors || "").toLowerCase();
      return tokens.every((t) => auths.includes(t));
    });
    return hits.slice(0, 10).map((it) => ({
      title: it.title || "Untitled",
      // Bug: when a preprint has no DOI yet, the old fallback re-used the
      // same falsy `it.doi` inside the "no DOI" branch, producing a dead
      // link like ".../content/undefined". Fall back to a search link built
      // from the title instead, which always resolves to something useful.
      url: it.doi
        ? "https://doi.org/" + it.doi
        : "https://www.biorxiv.org/search/" + encodeURIComponent(it.title || fullName),
      year: (it.date || "").slice(0, 4),
      citations: null,
      authors: it.authors || "",
      journal: server === "biorxiv" ? "bioRxiv (preprint)" : "medRxiv (preprint)",
      abstract: it.abstract || "",
    }));
  } catch (e) {
    return fetchFailed(e);
  }
}

// Generic web search fallback via a keyless search index. Used only when
// scholarly + author + wiki all come up empty, so we never return "nothing."
async function genericWebSearch(query, ledger = null) {
  try {
    // Wikipedia opensearch: fast, no auth, returns page titles and short descriptions
    const url =
      "https://en.wikipedia.org/w/api.php?" +
      new URLSearchParams({
        action: "opensearch",
        search: query,
        limit: "5",
        namespace: "0",
        format: "json",
        origin: "*",
      });
    const data = await getJSON(url, {}, 4000, 1, ledger);
    if (!Array.isArray(data) || data.length < 4) return [];
    const [, titles, descs, urls] = data;
    const out = [];
    for (let i = 0; i < titles.length; i++) {
      if (!descs[i] || !urls[i]) continue;
      out.push({
        title: titles[i],
        url: urls[i],
        year: "",
        citations: null,
        authors: "Wikipedia",
        journal: "Wikipedia",
        abstract: descs[i],
        source: "web",
      });
    }
    return out;
  } catch {
    return [];
  }
}

export async function openAlex(query, limit = 10, key = "", ledger = null, opts = {}) {
  try {


    const params = new URLSearchParams({
      search: query,
      // Ask OpenAlex to only hand back actual literature in the first place .
      // don't rely on the post-fetch reject filter alone to do this work. The
      // pipe is OpenAlex's own OR syntax for multiple values on one filter
      // field (the exact mechanism `biorxiv()` above already trusts for
      // `type:preprint`); "article" is OpenAlex's label for a journal article.
      // A dataset deposit, a component record, a book chapter etc. never
      // matches either arm and is dropped server-side before it costs us a
      // slot in `limit`.
      // Type filter (2026-10-23, logic audit L2-7): the default
      // excludes the OpenAlex review type, which silently removed
      // systematic reviews and meta analyses, the strongest
      // evidence class, from the broadest source. The filter is
      // now a caller decision: the effectiveness review leg passes
      // opts.types "review" so reviews are fetched for those
      // questions and their yield is reported as its own leg.
      filter: "type:" + ((opts && typeof opts.types === "string" && opts.types) || "article|preprint"),
// 2026-10-05: prefer English-language papers. OpenAlex's language filter
// keeps results predominantly English; non-English papers from other
// sources are demoted (not dropped) in post-fetch ranking.
// 2026-10-10: REMOVED language:en. It silently drops papers with NULL
// language metadata, including very recent preprints (e.g. a 2026 bioRxiv
// paper on "waste oil substrates" for BSFL was excluded despite being
// exactly on-topic). The English query itself biases relevance toward
// English papers; null-language papers are not non-English, just unindexed.
      // Wave twelve (item 2): the foundational lane overrides
      // this with cited_by_count:desc . it is hunting the
      // field's most cited first descriptions, and relevance
      // order demonstrably ranks recent reviews above them.
      sort: (opts && typeof opts.sort === "string" && opts.sort) || "relevance_score:desc",
      // Page shifting (2026-10-23, L2-5): the shifted form
      // requery asks for page 2, so a paper ranked thirteenth or
      // lower on the first form's ordering can still enter the
      // pool when the citable floor is unmet.
      ...((opts && typeof opts.page === "number" && opts.page > 1) ? { page: String(opts.page) } : {}),
      per_page: String(limit),
      select:
        "title,doi,publication_year,cited_by_count,abstract_inverted_index,primary_location,authorships,ids,type",
      mailto: "contact@askcerebrum.org",
    });
    if (key) params.set("api_key", key);
    const data = await getJSON("https://api.openalex.org/works?" + params, {}, 4000, 1, ledger);
    return (data.results || [])
      .map((w) => {
        const first =
          (w.authorships && w.authorships[0] && w.authorships[0].author && w.authorships[0].author.display_name) || "";
        const rawPmcid = (w.ids && w.ids.pmcid) || "";
        const pmcid = rawPmcid.replace(/^https?:\/\/.*?\/(PMC\d+)$/i, "$1").replace(/[^0-9]/g, "");
        return {
          title: w.title || "Untitled",
          url:
            (w.doi ? "https://doi.org/" + w.doi.replace(/^https?:\/\/doi\.org\//i, "") : "") ||
            (w.primary_location && (w.primary_location.landing_page_url || w.primary_location.pdf_url)) ||
            "",
          year: w.publication_year || "",
          citations: typeof w.cited_by_count === "number" ? w.cited_by_count : null,
          authors:
            w.authorships && w.authorships.length > 1
              ? first + " et al."
              : first,
          // Full author list preserved for downstream filtering (e.g. did a
          // specific researcher actually write this paper?). Display uses
          // `authors` (short); logic uses `_allAuthors` (full).
          _allAuthors: (w.authorships || [])
            .map((a) => (a && a.author && a.author.display_name) || "")
            .filter(Boolean)
            .join(", "),
          journal:
            (w.primary_location && w.primary_location.source && w.primary_location.source.display_name) ||
            "OpenAlex",
          abstract: decodeInverted(w.abstract_inverted_index),
          pmcid: pmcid || "",
          // Belt-and-suspenders: the `filter` above should mean this is
          // always "article" or "preprint" already, but the universal
          // post-fetch reject filter (isNonLiterature) re-checks it anyway .
          // an upstream filter param silently failing should never be the
          // only thing standing between a dataset record and the sidebar.
          _rawType: w.type || "",
        };
      })
      .filter((p) => p.title);
  } catch (e) {
    return fetchFailed(e);
  }
}

async function crossref(query, limit = 8, ledger = null, opts = {}) {
  try {
    // Type filter (2026-10-23, logic audit L2-7): the default stays
    // journal articles only, for the reason the old comment gave
    // (posted-content also covers conference abstracts, and
    // preprints have dedicated fetchers). But the filter is now a
    // caller decision, not a silent constant: the effectiveness
    // review leg passes includePosted so posted content is FETCHED
    // for those questions, counted in the leg's record, and judged
    // by the same admission screen as everything else, instead of
    // being deleted upstream where no record could see it.
    const includePosted = !!(opts && opts.includePosted);
    const url =
      "https://api.crossref.org/works?" +
      new URLSearchParams({
        query,
        rows: String(limit),
        ...(includePosted ? {} : { filter: "type:journal-article" }),
        select:
          "title,author,container-title,published,DOI,abstract,is-referenced-by-count,type,relation",
      }) +
      "&mailto=contact@askcerebrum.org";
    const data = await getJSON(url, {}, 4000, 1, ledger);
    const items = (data && data.message && data.message.items) || [];
    return items
      .map((it) => ({
        title: Array.isArray(it.title) ? it.title[0] : it.title || "Untitled",
        url: it.DOI ? "https://doi.org/" + it.DOI : "",
        year:
          (it.published &&
            it.published["date-parts"] &&
            it.published["date-parts"][0] &&
            it.published["date-parts"][0][0]) ||
          "",
        citations:
          typeof it["is-referenced-by-count"] === "number"
            ? it["is-referenced-by-count"]
            : null,
        authors:
          (it.author || [])
            .slice(0, 1)
            .map((a) => ((a.given || "") + " " + (a.family || "")).trim())
            .join("") + ((it.author || []).length > 1 ? " et al." : ""),
        _allAuthors: (it.author || [])
          .map((a) => ((a.given || "") + " " + (a.family || "")).trim())
          .filter(Boolean)
          .join(", "),
        journal: Array.isArray(it["container-title"])
          ? it["container-title"][0]
          : it["container-title"] || "Crossref",
        abstract: stripTags(it.abstract || ""),
        _rawType: it.type || "",
        // Identifier graph edge (2026-10-23, L2-8): Crossref's
        // is-preprint-of relation names the published version's
        // DOI. Carried as preprintOf so paperDedupeKeys can yield
        // it as a key and the preprint record intersects its
        // published version on a registry asserted identifier.
        preprintOf: (() => {
          const rel = it.relation && it.relation["is-preprint-of"];
          const first = Array.isArray(rel) ? rel[0] : null;
          return (first && typeof first.id === "string" && /^10\.\d{4,9}\//.test(first.id)) ? first.id : "";
        })(),
      }))
      .filter((p) => p.title);
  } catch (e) {
    return fetchFailed(e);
  }
}

async function arxiv(query, limit = 6, ledger = null) {
  try {
    // 2026-10-10: the caller (fanout) already builds the "all:X AND all:Y"
    // syntax in `arx`. Do NOT prepend another "all:" here — that produced
    // "all:all:Hermetia illucens AND ..." which arXiv silently mishandles.
    const url =
      "https://export.arxiv.org/api/query?" +
      new URLSearchParams({
        search_query: query,
        max_results: String(limit),
        sortBy: "relevance",
      });
    const xml = await getText(url, {}, 4000, 1, ledger);
    const entries = xml.match(/<entry>[\s\S]*?<\/entry>/g) || [];
    return entries
      .map((e) => {
        const g = (re) => {
          const m = e.match(re);
          return m ? m[1].trim() : "";
        };
        const title = stripTags(g(/<title>([\s\S]*?)<\/title>/));
        const summary = stripTags(g(/<summary>([\s\S]*?)<\/summary>/));
        const id = g(/<id>([\s\S]*?)<\/id>/);
        const published = g(/<published>(\d{4})/);
        const authorNames = (e.match(/<name>([\s\S]*?)<\/name>/g) || []).map(
          (a) => a.replace(/<\/?name>/g, "").trim()
        );
        return {
          title: title || "arXiv paper",
          url: id,
          year: published || "",
          citations: null,
          authors:
            authorNames.length > 1
              ? authorNames[0] + " et al."
              : authorNames[0] || "",
          _allAuthors: authorNames.join(", "),
          journal: "arXiv",
          abstract: summary,
        };
      })
      .filter((p) => p.title);
  } catch (e) {
    return fetchFailed(e);
  }
}

// Semantic Scholar's own `publicationTypes` enum includes a literal
// "Dataset" value alongside real literature types . asking for everything
// EXCEPT Dataset (rather than an allowlist of just "JournalArticle") keeps
// reviews, meta-analyses, conference papers, and case reports in the mix
// instead of silently narrowing the source the way a tight allowlist would.
const S2_LITERATURE_TYPES = [
  "JournalArticle",
  "Review",
  "MetaAnalysis",
  "CaseReport",
  "ClinicalTrial",
  "Conference",
  "Study",
  "Book",
  "BookSection",
].join(",");

export async function semanticScholar(query, limit = 8, apiKey = "", ledger = null, opts = {}) {
  try {
    const url =
      "https://api.semanticscholar.org/graph/v1/paper/search?" +
      new URLSearchParams({
        query,
        limit: String(limit),
        publicationTypes: S2_LITERATURE_TYPES,
        // Wave twelve (item 2): the foundational lane passes
        // sort=citationCount:desc for the same reason the other
        // two lane legs sort by citations — first descriptions
        // are the most cited matches, not the most recent.
        ...(opts && typeof opts.sort === "string" && opts.sort ? { sort: opts.sort } : {}),
        fields:
          "title,abstract,tldr,year,citationCount,authors,venue,externalIds,openAccessPdf,url,publicationTypes",
      });
    // Scale fix (2026-09-14): without a key S2 sits in the unauthenticated
    // shared pool (100 req/5min) . at ~50+ concurrent users it 429s and
    // silently drops out of every answer. Key is opt-in via
    // SEMANTIC_SCHOLAR_KEY env (free); absent key = previous behavior.
    const headers = apiKey ? { "x-api-key": apiKey } : {};
    const data = await getJSON(url, headers, 4000, 1, ledger);
    return ((data && data.data) || [])
      .filter((r) => r.title)
      .map((r) => {
        const doi = r.externalIds && r.externalIds.DOI;
        return {
          title: r.title || "Untitled",
          url: doi
            ? "https://doi.org/" + doi
            : (r.openAccessPdf && r.openAccessPdf.url) || r.url || "",
          year: r.year || "",
          citations: typeof r.citationCount === "number" ? r.citationCount : null,
          authors:
            (r.authors || []).slice(0, 1).map((a) => a.name).join("") +
            ((r.authors || []).length > 1 ? " et al." : ""),
          _allAuthors: (r.authors || []).map((a) => a.name).filter(Boolean).join(", "),
          journal: r.venue || "",
          abstract: r.abstract || "",
          tldr: (r.tldr && r.tldr.text) || "",
          // `publicationTypes` comes back as an array (can be null/empty for
          // sparsely-catalogued records) . flatten to a comma string so the
          // universal reject filter can pattern-match it the same way it
          // matches every other source's `_rawType`.
          _rawType: Array.isArray(r.publicationTypes) ? r.publicationTypes.join(",") : "",
        };
      });
  } catch (e) {
    return fetchFailed(e);
  }
}

async function doaj(query, limit = 6, ledger = null) {
  try {
    const url =
      "https://doaj.org/api/search/articles/" +
      encodeURIComponent(query) +
      "?pageSize=" +
      limit;
    const data = await getJSON(url, {}, 4000, 1, ledger);
    return ((data && data.results) || [])
      .map((r) => {
        const b = r.bibjson || {};
        const doiId = (b.identifier || []).find((x) => x.type === "doi");
        const link = (b.link || [])[0];
        return {
          title: b.title || "Untitled",
          url: doiId ? "https://doi.org/" + doiId.id : (link && link.url) || "",
          year: b.year || "",
          citations: null,
          authors:
            (b.author || []).slice(0, 1).map((a) => a.name).join("") +
            ((b.author || []).length > 1 ? " et al." : ""),
          journal: (b.journal && b.journal.title) || "",
          abstract: stripTags(b.abstract || ""),
        };
      })
      .filter((p) => p.title);
  } catch (e) {
    return fetchFailed(e);
  }
}

// Commit 65 . dedicated preprint search.
//
// The bug this fixes: `biorxiv()` above is the only preprint-facing source in
// the topic fanout, and it reaches bioRxiv indirectly, through OpenAlex with
// `filter=type:preprint`. OpenAlex types a large share of bioRxiv/medRxiv
// deposits as plain `article`, so that filter quietly drops them . which is
// how Cerebrum ended up telling people a paper "isn't in the literature"
// when it is sitting on bioRxiv under exactly the terms they searched.
//
// Europe PMC's `SRC:PPR` is the authoritative preprint slice: bioRxiv,
// medRxiv, arXiv, Research Square, ChemRxiv, SSRN and Preprints.org, all
// searchable by topic through the same keyless endpoint the rest of this
// file already uses. Preprints are labelled as such in `journal` so the
// answer layer and the UI can weight them below peer-reviewed work rather
// than presenting them as equivalent evidence.
async function preprintSearch(query, limit = 8, ledger = null) {
  try {
    const url = "https://www.ebi.ac.uk/europepmc/webservices/rest/search?" +
      new URLSearchParams({
        query: "(" + query + ") AND (SRC:PPR)",
        resultType: "core",
        pageSize: String(limit),
        format: "json",
        // Commit 94 . the `sort` parameter was removed here. Europe PMC
        // documents CITED / P_PDATE_D / AUTH_FIRST as sort values; "relevance"
        // is not one of them, and relevance IS the default when sort is
        // omitted. Passing an undocumented value risked a 400 that this
        // function's bare catch would have turned into an empty result set .
        // i.e. a whole source silently contributing nothing.
      });
    const data = await getJSON(url, {}, 6000, 1, ledger);
    const rows = (data && data.resultList && data.resultList.result) || [];
    return rows.filter((r) => r.title).map((r) => {
      // bookOrReportDetails.publisher carries the actual server name
      // ("bioRxiv", "medRxiv") for PPR records; journalTitle is usually empty
      // for them, so falling back to it alone produced a bare "Preprint".
      const server =
        (r.bookOrReportDetails && r.bookOrReportDetails.publisher) ||
        r.journalTitle || r.publisher || "";
      return {
        title: r.title || "Untitled",
        url: r.doi ? "https://doi.org/" + r.doi : "https://europepmc.org/article/" + r.source + "/" + r.id,
        year: r.pubYear || "",
        citations: typeof r.citedByCount === "number" ? r.citedByCount : null,
        authors: r.authorString || "",
        _allAuthors: r.authorString || "",
        journal: server ? server + " (preprint)" : "Preprint",
        abstract: stripTags(r.abstractText),
        isPreprint: true,
      };
    });
  } catch (e) { return fetchFailed(e); }
}

async function biorxiv(query, limit = 6, ledger = null) {
  try {
    const params = new URLSearchParams({
      search: query,
      filter: "type:preprint",
      sort: "relevance_score:desc",
      per_page: String(limit),
      select:
        "title,doi,publication_year,cited_by_count,abstract_inverted_index,primary_location,authorships",
      mailto: "contact@askcerebrum.org",
    });
    const data = await getJSON("https://api.openalex.org/works?" + params, {}, 4000, 1, ledger);
    const out = [];
    for (const w of (data.results || [])) {
      if (!w.title) continue;
      const first =
        (w.authorships && w.authorships[0] && w.authorships[0].author && w.authorships[0].author.display_name) || "";
      out.push({
        title: w.title,
        url:
          w.doi ||
          (w.primary_location && w.primary_location.landing_page_url) ||
          "",
        year: w.publication_year || "",
        citations: typeof w.cited_by_count === "number" ? w.cited_by_count : null,
        authors:
          w.authorships && w.authorships.length > 1
            ? first + " et al."
            : first,
        journal:
          (w.primary_location && w.primary_location.source && w.primary_location.source.display_name) ||
          "Preprint",
        abstract: decodeInverted(w.abstract_inverted_index),
      });
    }
    return out;
  } catch (e) {
    return fetchFailed(e);
  }
}

// Zenodo is NOT a fanout source (2026-10-14, wave eight round
// three, Job 1). The v34 note that used to sit here recorded why
// its records are hard rejected downstream: the endpoint hosts a
// mix of genuine papers, posters, presentations, and raw
// data/software deposits under depositor declared types, with no
// clean way to tell them apart, and a raw dataset was once cited
// as literature — so isNonLiterature rejects every zenodo URL at
// admission (BLOCKED_DOMAINS above) and that standard stands.
// What changed in round three: the canonical source list in
// functions/lib/product.js no longer advertises Zenodo, and the
// fetcher that used to sit here (never called by the fanout, its
// results discarded even if it had been) is deleted rather than
// left as a decoy. If Zenodo ever returns, it returns through
// the same admission standard as every other source, with the
// canonical list and the fanout growing together.

async function plos(query, limit = 6, ledger = null) {
  try {
    const url =
      "https://api.plos.org/search?" +
      new URLSearchParams({
        q: query,
        fl: "id,title_display,author_display,journal,publication_date,abstract",
        wt: "json",
        rows: String(limit),
      });
    const data = await getJSON(url, {}, 4000, 1, ledger);
    return ((data && data.response && data.response.docs) || [])
      .map((d) => ({
        title: Array.isArray(d.title_display)
          ? d.title_display[0]
          : d.title_display || "Untitled",
        url: d.id ? "https://doi.org/" + d.id : "",
        year: (d.publication_date || "").slice(0, 4),
        citations: null,
        authors:
          (d.author_display || []).slice(0, 1).join("") +
          ((d.author_display || []).length > 1 ? " et al." : ""),
        journal: d.journal || "",
        abstract: stripTags(
          Array.isArray(d.abstract) ? d.abstract.join(" ") : d.abstract || ""
        ),
      }))
      .filter((p) => p.title);
  } catch (e) {
    return fetchFailed(e);
  }
}

// ---- ADDITIONAL SCHOLARLY APIs ----

async function coreSearch(query, limit = 8, ledger = null) {
  try {
    const url = "https://api.core.ac.uk/v3/search/works?" +
      new URLSearchParams({ q: query, limit: String(limit) });
    const data = await getJSON(url, {}, 6000, 1, ledger);
    return ((data && data.results) || []).filter((r) => r.title).map((r) => ({
      title: r.title || "Untitled",
      url: r.doi ? "https://doi.org/" + r.doi : (r.downloadUrl || ""),
      year: r.yearPublished ? String(r.yearPublished) : "",
      citations: null,
      authors: (r.authors || []).map((a) => a.name || "").slice(0, 1).join("") + ((r.authors || []).length > 1 ? " et al." : ""),
      _allAuthors: (r.authors || []).map((a) => a.name || "").join(", "),
      journal: r.publisher || "",
      abstract: stripTags((r.abstract || "").slice(0, 1500)),
    }));
  } catch (e) { return fetchFailed(e); }
}

async function baseSearch(query, limit = 8, ledger = null) {
  try {
    const url = "https://api.base-search.net/cgi-bin/BaseHttpSearchInterface.fcgi?" +
      new URLSearchParams({ func: "PerformSearch", query: query, format: "json", hits: String(limit) });
    const data = await getJSON(url, {}, 6000, 1, ledger);
    return ((data && data.response && data.response.docs) || []).filter((d) => d.dctitle).map((d) => ({
      title: Array.isArray(d.dctitle) ? d.dctitle[0] : (d.dctitle || "Untitled"),
      url: (Array.isArray(d.dcidentifier) ? d.dcidentifier.find((u) => (u||"").startsWith("http")) : d.dcidentifier) || "",
      year: Array.isArray(d.dcyear) ? d.dcyear[0] : (d.dcyear || ""),
      citations: null,
      authors: Array.isArray(d.dcperson) ? d.dcperson.slice(0,1).join("") + (d.dcperson.length > 1 ? " et al." : "") : (d.dcperson || ""),
      _allAuthors: Array.isArray(d.dcperson) ? d.dcperson.join(", ") : (d.dcperson || ""),
      journal: Array.isArray(d.dcsource) ? d.dcsource[0] : (d.dcsource || ""),
      abstract: stripTags(Array.isArray(d.dcdescription) ? d.dcdescription.join(" ").slice(0,1500) : (d.dcdescription || "").slice(0,1500)),
    }));
  } catch (e) { return fetchFailed(e); }
}

async function pmcFullText(query, limit = 8, ledger = null) {
  try {
    const url = "https://www.ebi.ac.uk/europepmc/webservices/rest/search?" +
      // Commit 94 . see the note in europePMC(): "relevance" is not a
      // documented Europe PMC sort value and relevance is the default.
      // Sent form (2026-10-23, L2-6): buildPmcFullTextQuery ANDs
      // the topic's content words as individual BODY terms. The
      // old form wrapped the whole string in one BODY phrase and
      // returned zero in every audit probe run.
      new URLSearchParams({ query: buildPmcFullTextQuery(query), resultType: "core", pageSize: String(limit), format: "json" });
    const data = await getJSON(url, {}, 6000, 1, ledger);
    return ((data && data.resultList && data.resultList.result) || []).filter((r) => r.title).map((r) => ({
      title: r.title || "Untitled",
      url: r.doi ? "https://doi.org/" + r.doi : "https://europepmc.org/article/" + r.source + "/" + r.id,
      year: r.pubYear || "",
      citations: typeof r.citedByCount === "number" ? r.citedByCount : null,
      authors: r.authorString || "",
      _allAuthors: r.authorString || "",
      journal: r.journalTitle || "",
      abstract: stripTags(r.abstractText),
    }));
  } catch (e) { return fetchFailed(e); }
}

async function openAire(query, limit = 8, ledger = null) {
  try {
    const url = "https://api.openaire.eu/search/publications?" +
      new URLSearchParams({ keywords: query, size: String(limit), format: "json" });
    const data = await getJSON(url, {}, 6000, 1, ledger);
    const results = data?.response?.results?.result || [];
    return results.filter((r) => r?.metadata?.["oaf:entity"]?.["oaf:result"]?.title).map((r) => {
      const m = r.metadata["oaf:entity"]["oaf:result"];
      const t = typeof m.title === "string" ? m.title : (m.title?.["$"] || "Untitled");
      const creators = Array.isArray(m.creator) ? m.creator : (m.creator ? [m.creator] : []);
      const names = creators.map((c) => c?.["$"] || "").filter(Boolean);
      const pids = Array.isArray(m.pid) ? m.pid : (m.pid ? [m.pid] : []);
      const doi = pids.find((p) => p?.["@classid"] === "doi");
      // Bug: dateofacceptance comes back as {"$": "2021-04-01"} (same shape as
      // title/description above), not a plain string. Calling .slice() on
      // that object threw on every single result, and since this whole
      // .map() runs inside the function's own try/catch, the exception was
      // silently swallowed and openAire() always returned [] . this source
      // never actually contributed a single paper. Unwrap it like the other
      // OAI-PMH-shaped fields already do.
      const acceptDate = typeof m.dateofacceptance === "string" ? m.dateofacceptance : (m.dateofacceptance?.["$"] || "");
      return {
        title: t, url: doi ? "https://doi.org/" + doi["$"] : "",
        year: acceptDate.slice(0,4), citations: null,
        authors: names.slice(0,1).join("") + (names.length > 1 ? " et al." : ""),
        _allAuthors: names.join(", "),
        journal: m.journal?.["$"] || "",
        abstract: stripTags((typeof m.description === "string" ? m.description : (m.description?.["$"] || "")).slice(0,1500)),
      };
    }).filter((p) => p.title && p.title !== "Untitled");
  } catch (e) { return fetchFailed(e); }
}


async function wikipedia(query, limit = 2, ledger = null) {
  try {
    const searchUrl =
      "https://en.wikipedia.org/w/api.php?" +
      new URLSearchParams({
        action: "query",
        list: "search",
        srsearch: query,
        srlimit: String(limit),
        format: "json",
        origin: "*",
      });
    const sdata = await getJSON(searchUrl, {}, 4000, 1, ledger);
    const hits = (sdata && sdata.query && sdata.query.search) || [];
    const out = [];
    for (const h of hits) {
      const title = h.title;
      try {
        const exUrl =
          "https://en.wikipedia.org/w/api.php?" +
          new URLSearchParams({
            action: "query",
            prop: "extracts",
            exintro: "1",
            explaintext: "1",
            titles: title,
            format: "json",
            origin: "*",
          });
        const ex = await getJSON(exUrl, {}, 4000, 1, ledger);
        const pages = (ex && ex.query && ex.query.pages) || {};
        const page = Object.values(pages)[0] || {};
        const extract = (page.extract || "").replace(/\s+/g, " ").trim();
        if (extract) {
          out.push({
            title: title + " (Wikipedia)",
            url:
              "https://en.wikipedia.org/wiki/" +
              encodeURIComponent(title.replace(/ /g, "_")),
            year: "",
            citations: null,
            authors: "Wikipedia contributors",
            journal: "Wikipedia",
            abstract: extract.slice(0, 1500),
            isEncyclopedia: true,
          });
        }
      } catch (cbErr) { console.error("[Cerebrum] search.js if:", cbErr); }
    }
    return out;
  } catch {
    return [];
  }
}

async function duckduckgo(query, ledger = null) {
  try {
    const url =
      "https://api.duckduckgo.com/?" +
      new URLSearchParams({
        q: query,
        format: "json",
        no_html: "1",
        skip_disambig: "1",
      });
    const data = await getJSON(url, {}, 4000, 1, ledger);
    const abstract = ((data && data.AbstractText) || "").trim();
    if (!abstract) return [];
    return [
      {
        title: (data.Heading || query) + " (" + (data.AbstractSource || "Web") + ")",
        url: data.AbstractURL || "",
        year: "",
        citations: null,
        authors: data.AbstractSource || "Web",
        journal: data.AbstractSource || "",
        abstract: abstract.slice(0, 1200),
        isEncyclopedia: true,
      },
    ];
  } catch {
    return [];
  }
}

// ============ VIDEO SEARCH ============
// Races multiple public Piped/Invidious instances. If one works, we use it.
// Instance list is refreshed with known-working ones and rotated randomly.

